// Examples that a study card itself works through, as 'kind:passage' (or 'kind:passage:figure') keys.
// An exercise does not ask about a card's own example in the same respect in which the card gives it.
function cardTaught(key){
  if(!cardTaught.set){
    const s = {};
    Object.keys(DECKS).forEach(k => DECKS[k].panels.forEach(p => (p.taught || []).forEach(t => { s[t] = 1; })));
    ITEM_SKIP.forEach(t => { s[t] = 1; });
    cardTaught.set = s;
  }
  return !!cardTaught.set[key];
}
