const TAXIS_PARTS = [
  {key:'exordium', name:'Exordium', duty:'to make the hearers attentive, teachable, and well-disposed.'},
  {key:'narration', name:'Narration', duty:'to state the facts briefly, clearly, and plausibly.'},
  {key:'division', name:'Division', duty:'to set out the points in dispute and the order of taking them.'},
  {key:'proof', name:'Proof', duty:'to give one’s own arguments (confirmatio).'},
  {key:'refutation', name:'Refutation', duty:'to answer the other side (reprehensio).'},
  {key:'peroration', name:'Peroration', duty:'to recapitulate, and to move.'}
];
const TAXIS_ITEMS = [
  {id:'t1', part:'exordium', text:'How much further, Catilina, will you carry your abuse of our forbearance?', src:'cic_cat', cite:'Cicero, First Catilinarian 1.1'},
  {id:'t2', part:'narration', text:'My boy, struck in the side on the training field by a javelin thrown by this young man, died on the spot.', src:'antiphon', cite:'Antiphon, Second Tetralogy 3.1.1'},
  {id:'t3', part:'division', text:'For either by the disposition of fortune and the ratification of the gods and the determination of necessity she did what she did, or by violence confounded, or by persuasion dumbfounded or to Love surrendered.', src:'gorgias_vh', cite:'Gorgias, Helen 6'},
  {id:'t4', part:'proof', text:'I consider that we are deliberating for the future more than for the present.', src:'thuc_crawley', cite:'Thucydides 3.44, Diodotus'},
  {id:'t6', part:'peroration', text:'How, then, is it fair to blame Helen who, whether by love captivated, or by word persuaded, or by violence dominated, or by divine necessity subjugated, did what she did, and is completely absolved from blame?', src:'gorgias_vh', cite:'Gorgias, Helen 20'},
  {id:'t7', part:'exordium', text:'I am more than seventy years of age, and appearing now for the first time in a court of law, I am quite a stranger to the language of the place.', src:'plato_jowett', cite:'Plato, Apology 17c–d (Jowett) — the refusal of a captatio'},
  {id:'t8', part:'narration', text:'But when a deep consideration had from the secret bottom of my soul drawn together and heaped up all my misery in the sight of my heart; there arose a mighty storm, bringing a mighty shower of tears.', src:'aug_pusey', cite:'Augustine, Confessions VIII.12 (Pusey)'},
  {id:'t9', part:'proof', text:'Logos is a powerful potentate, who with frailest, feeblest frame works wonders.', src:'gorgias_vh', cite:'Gorgias, Helen 8'},
  {id:'t10', part:'peroration', text:'For heroes have the whole earth for their tomb; and in lands far from their own, where the column with its epitaph declares it, there is enshrined in every breast a record unwritten with no tablet to preserve it, except that of the heart.', src:'thuc_crawley', cite:'Thucydides 2.43, Pericles'},
  {id:'t11', part:'exordium', text:'Although I am afraid, gentlemen of the jury, that fear is an unseemly condition in which to begin a speech in defence of the bravest of men.', src:'cic_cat', cite:'Cicero, Pro Milone 1'},
  {id:'t12', part:'exordium', text:'Most of my predecessors in this place have commended him who made this speech part of the law, telling us that it is well that it should be delivered at the burial of those who fall in battle.', src:'thuc_crawley', cite:'Thucydides 2.35, Pericles'},
  {id:'t13', part:'narration', why:'These sentences state what was done at Laeca’s house that night, in order, so they are narration. Cicero then presses the same night as evidence, and that use of it is proof.', text:'You were then, Catilina, at Laeca’s house that night; you divided Italy into districts; you decided to what quarter you wished each of your friends to proceed.', src:'cic_cat', cite:'Cicero, First Catilinarian 1.9'},
  {id:'t14', part:'proof', text:'If, men of Athens, you first supply the sum I have mentioned, and then, after making ready the rest of the armament—soldiers, ships, cavalry—bind the whole force in its entirety, by law, to remain at the seat of war.', src:'demosth', cite:'Demosthenes, First Philippic'},
  {id:'t15', part:'proof', text:'Inflict only such penalties as the laws have provided.', src:'sallust_w', cite:'Sallust, Catiline 51, Caesar'},
  {id:'t16', part:'refutation', text:'The strong do what they can and the weak suffer what they must. Melians. As we think, at any rate, it is expedient—we speak as we are obliged, since you enjoin us to let right alone and talk only of interest.', src:'thuc_crawley', cite:'Thucydides 5.89–90, Melian dialogue'},
  {id:'t17', part:'exordium', text:'To-day, conscript fathers, has brought to a close the long silence, due not to a feeling of fear, but to mingled feelings of grief and of diffidence.', src:'cic_orat', cite:'Cicero, Pro Marcello 1'},
  {id:'t18', part:'division', text:'Differently to be admonished are these that follow:—Men and women. The poor and the rich. The joyful and the sad.', src:'greg', cite:'Gregory, Pastoral Care III (Barmby)'},
  {id:'t19', part:'narration', text:'Cocles, (that defence the fortune of Rome had on that day,) who, happening to be posted on guard at the bridge, when he saw the Janiculum taken by a sudden assault.', src:'livy_r', cite:'Livy 2.10, Horatius'},
  {id:'t20', part:'refutation', text:'How you, O Athenians, have been affected by my accusers, I cannot tell; but I know that they almost made me forget who I was—so persuasively did they speak; and yet they have hardly uttered a word of truth.', src:'plato_jowett', cite:'Plato, Apology (Jowett)'},
  // English tradition (public-domain quotations; sources eng_cer, eng_cem, kjv).
  {id:'eng-t1', part:'exordium', text:'Friends, Romans, countrymen, lend me your ears; I come to bury Caesar, not to praise him.', src:'eng_cer', cite:'Shakespeare, Julius Caesar 3.2'},
  {id:'eng-t2', part:'division', text:'[T]here are but three ways of proceeding relative to this stubborn spirit which prevails in your colonies and disturbs your government. These are, – to change that spirit, as inconvenient, by removing the causes, – to prosecute it, as criminal, – or to comply with it, as necessary.', src:'eng_cer', cite:'Edmund Burke, Speech on Conciliation with the Colonies (1775)'},
  {id:'eng-t3', part:'refutation', text:'The gentleman asks, When were the colonies emancipated? I desire to know, when were they made slaves?', src:'eng_cer', cite:'William Pitt (the Elder), Speech in the House of Commons (1766)'},
  {id:'eng-t4', part:'refutation', text:'You say they will be better men than the English commoners. I say they will be infinitely worse men, because they are to be chosen blindfolded: their election (the term, as applied to their appointment, is inaccurate) will be an involuntary nomination, and not a choice.', src:'eng_cer', cite:'Patrick Henry, Speech at the Virginia Ratifying Convention (1788)'},
  {id:"t-herm-open", part:"exordium", text:"Camarinaeans, we did not come on this embassy because we were afraid of your being frightened by the actual forces of the Athenians, but rather of your being gained by what they would say to you before you heard anything from us.", src:"thuc_crawley", cite:"Thucydides 6.76, Hermocrates", why:"He opens by telling them why they should listen now: the embassy came not because of “the actual forces of the Athenians”, but because they might be “gained by what they would say” “before you heard anything from us”. That is the office of an opening, to make the hearers attentive and to keep them from the other side’s account."},
  {id:"t-cato-open", part:"exordium", text:"My feelings, Conscript Fathers, are extremely different, when I contemplate our circumstances and dangers, and when I revolve in my mind the sentiments of some who have spoken before me.", src:"sallust_w", cite:"Sallust, Catiline 52, Cato", why:"He begins by setting himself apart from “some who have spoken before me”, so that the senate will hear his view as a different one. An opening makes the hearers teachable, and this one does it by marking the difference before the argument starts."},
  {id:"t-corc-naval", part:"narration", text:"It is true that in the late naval engagement we drove back the Corinthians from our shores single-handed.", src:"thuc_crawley", cite:"Thucydides 1.32, Corcyra", why:"The sentence states a past fact, the “late naval engagement” in which they “drove back the Corinthians from our shores”. Narration states what happened, briefly and so that it can be believed."},
  {id:"t-cori-twenty", part:"narration", text:"When you were in want of ships of war for the war against the Aeginetans, before the Persian invasion, Corinth supplied you with twenty vessels.", src:"thuc_crawley", cite:"Thucydides 1.41, Corinth", why:"Corinth states what she did in a former war: she “supplied you with twenty vessels” “before the Persian invasion”. That is narration, the office that puts the facts before the hearers."},
  {id:"t-nic-two", part:"division", text:"I will, therefore, content myself with showing that your ardour is out of season, and your ambition not easy of accomplishment.", src:"thuc_crawley", cite:"Thucydides 6.9, Nicias", why:"He names the two points he will show, that their “ardour is out of season” and that their “ambition” is “not easy of accomplishment”. Division sets out the points in dispute and the order of taking them."},
  {id:"t-cato-question", part:"division", text:"The question, however, at present under discussion, is not whether we live in a good or a bad state of morals; nor how great, or how splendid, the empire of the Roman people is; but whether these things around us, of whatever value they are, are to continue our own, or to fall, with ourselves, into the hands of the enemy.", src:"sallust_w", cite:"Sallust, Catiline 52, Cato", why:"He sets aside “whether we live in a good or a bad state of morals” and “how great, or how splendid, the empire of the Roman people is”, and he names the point that is “under discussion”: whether these things “are to continue our own”. That is the division of the question."},
  {id:"t-theb-two", part:"division", text:"However, since they have done so, we must answer their charges and refute their self-praise, in order that neither our bad name nor their good may help them, but that you may hear the real truth on both points, and so decide.", src:"thuc_crawley", cite:"Thucydides 3.61, Thebes", why:"He lays out two tasks, to “answer their charges and refute their self-praise”, so that the judges “hear the real truth on both points, and so decide”. Division names the points and the order in which they will be taken."},
  {id:"t-herm-arm", part:"proof", text:"but you should help us without fear of their armament, which has no terrors if we hold together, but only if we let them succeed in their endeavours to separate us; since even after attacking us by ourselves and being victorious in battle, they had to go off without effecting their purpose.", src:"thuc_crawley", cite:"Thucydides 6.79, Hermocrates", why:"He gives his own reason for joining: the armament “has no terrors if we hold together, but only if we let them succeed in their endeavours to separate us”. Proof is the office that gives one’s own arguments."},
  {id:"t-nic-folly-p", part:"proof", text:"Now it is folly to go against men who could not be kept under even if conquered, while failure would leave us in a very different position from that which we occupied before the enterprise.", src:"thuc_crawley", cite:"Thucydides 6.11, Nicias", why:"The argument of his own side is stated here: it is “folly to go against men who could not be kept under even if conquered”, because failure would leave Athens in “a very different position”. That is proof."},
  {id:"t-herm-alliance", part:"refutation", text:"But you made that alliance, not against your friends, but against the enemies that might attack you, and to help the Athenians when they were wronged by others, not when as now they are wronging their neighbours.", src:"thuc_crawley", cite:"Thucydides 6.79, Hermocrates", why:"He takes up their plea of “that alliance” and answers it: the alliance was “not against your friends”, and it was not made for the Athenians “when as now they are wronging their neighbours”. Refutation answers the other side."},
  {id:"t-herm-neut", part:"refutation", text:"And you need not think that your prudent policy of taking sides with neither, because allies of both, is either safe for you or fair to us.", src:"thuc_crawley", cite:"Thucydides 6.79, Hermocrates", why:"He answers the policy they would keep, “taking sides with neither, because allies of both”, and he denies that it is “safe for you or fair to us”. That is the answer to the other side."},
  {id:"t-corc-sum", part:"peroration", text:"To sum up as shortly as possible, embracing both general and particular considerations, let this show you the folly of sacrificing us. Remember that there are but three considerable naval powers in Hellas—Athens, Corcyra, and Corinth—and that if you allow two of these three to become one, and Corinth to secure us for herself, you will have to hold the sea against the united fleets of Corcyra and Peloponnese. But if you receive us, you will have our ships to reinforce you in the struggle.", src:"thuc_crawley", cite:"Thucydides 1.36, Corcyra", why:"He marks the close, “To sum up as shortly as possible”, calls the refusal “the folly of sacrificing us”, and ends on what the vote will bring: “you will have our ships to reinforce you in the struggle”. A peroration recapitulates and moves."},
  {id:"t-herm-close", part:"peroration", text:"In conclusion, we Syracusans say that it is useless for us to demonstrate either to you or to the rest what you know already as well as we do; but we entreat, and if our entreaty fail, we protest that we are menaced by our eternal enemies the Ionians, and are betrayed by you our fellow Dorians. If the Athenians reduce us, they will owe their victory to your decision, but in their own name will reap the honour, and will receive as the prize of their triumph the very men who enabled them to gain it. On the other hand, if we are the conquerors, you will have to pay for having been the cause of our danger. Consider, therefore; and now make your choice between the security which present servitude offers and the prospect of conquering with us and so escaping disgraceful submission to an Athenian master and avoiding the lasting enmity of Syracuse.", src:"thuc_crawley", cite:"Thucydides 6.80, Hermocrates", why:"He marks the close with “In conclusion”, says further demonstration is “useless” because they “know already”, and he ends by making them “make your choice” between “present servitude” and “conquering with us”. The close sums the case and moves them to the vote."},
  {id:"t-nic-pryt", part:"peroration", text:"And you, Prytanis, if you think it your duty to care for the commonwealth, and if you wish to show yourself a good citizen, put the question to the vote, and take a second time the opinions of the Athenians.", src:"thuc_crawley", cite:"Thucydides 6.14, Nicias", why:"The speech ends by asking the Prytanis, “if you wish to show yourself a good citizen”, to “put the question to the vote, and take a second time the opinions of the Athenians”. A peroration moves the hearer to the act."},
  // Added from Lysias, Cicero, and the Plataean and Theban speeches in Thucydides; the offices are those of De inventione I.14.19.
  {id:"t-lys12-open", part:"exordium", text:"The difficulty that faces me, gentlemen of the jury, is not in beginning my accusation, but in bringing my speech to an end: so enormous, so numerous are the acts they have committed, that neither could lying avail one to accuse them of things more monstrous than the actual facts, nor with every desire to speak mere truth could one tell the whole; of necessity either the accuser must be tired out or his time must run short.", src:"lysias_lamb", cite:"Lysias, Against Eratosthenes 12.1", why:"He opens by saying that his difficulty is not to begin but to end, because the crimes are so many. An opening makes the hearers attentive (De inventione I.15.20), and this one promises a case larger than the time allowed."},
  {id:"t-lys22-open", part:"exordium", text:"Many people have come to me, gentlemen of the jury, in surprise at my accusing the corn-dealers in the Council, and telling me that you, however sure you are of their guilt, none the less regard those who deliver speeches about them as slander-mongers. I therefore propose to speak first of the grounds on which I have found it necessary to accuse them.", src:"lysias_lamb", cite:"Lysias, Against the Corn-Dealers 22.1", why:"He answers the suspicion that accusers of the dealers are slanderers, and says he will first give his reasons for accusing them. An opening makes the hearers well-disposed (De inventione I.15.20), here by removing a prejudice against the speaker."},
  {id:"t-plat-open", part:"exordium", text:"Lacedaemonians, when we surrendered our city we trusted in you, and looked forward to a trial more agreeable to the forms of law than the present, to which we had no idea of being subjected; the judges also in whose hands we consented to place ourselves were you, and you only (from whom we thought we were most likely to obtain justice), and not other persons, as is now the case.", src:"thuc_crawley", cite:"Thucydides 3.53, Plataea", why:"The Plataeans begin by recalling the trust with which they surrendered and the trial they expected. An opening makes the judges attentive and well-disposed before the case is argued (De inventione I.15.20)."},
  {id:"t-theb-open", part:"exordium", text:"We should never have asked to make this speech if the Plataeans on their side had contented themselves with shortly answering the question, and had not turned round and made charges against us, coupled with a long defence of themselves upon matters outside the present inquiry and not even the subject of accusation, and with praise of what no one finds fault with.", src:"thuc_crawley", cite:"Thucydides 3.61, Thebes", why:"The Thebans explain why they speak at all: the Plataeans did not keep to the question. An opening of this kind prepares the judges to hear what follows (De inventione I.15.20)."},
  {id:"t-lys1-narr", part:"narration", text:"When I, Athenians, decided to marry, and brought a wife into my house, for some time I was disposed neither to vex her nor to leave her too free to do just as she pleased; I kept a watch on her as far as possible, with such observation of her as was reasonable. But when a child was born to me, thence-forward I began to trust her, and placed all my affairs in her hands, presuming that we were now in perfect intimacy.", src:"lysias_lamb", cite:"Lysias, On the Murder of Eratosthenes 1.6", why:"The speaker begins the story from his marriage. Narration sets out what happened, briefly, clearly, and plausibly (De inventione I.19.27)."},
  {id:"t-lys12-narr", part:"narration", text:"My father Cephalus was induced by Pericles to come to this country, and dwelt in it for thirty years: never did he, any more than we, appear as either prosecutor or defendant in any case whatever, but our life under the democracy was such as to avoid any offence against our fellows and any wrong at their hands.", src:"lysias_lamb", cite:"Lysias, Against Eratosthenes 12.4", why:"After the opening he begins the facts with his father’s coming to Athens. Narration states what happened (De inventione I.19.27), and this one also shows a quiet family that harmed no one."},
  {id:"t-lys22-narr", part:"narration", text:"When the Committee of the time brought up their case before the Council, the anger felt against them was such that some of the orators said that they ought to be handed over without trial to the Eleven, for the penalty of death. But I, thinking it monstrous that the Council should get into the way of such practice, rose and said that in my opinion we ought to try the corn-dealers in accordance with the law; for I thought that if they had committed acts deserving of death you would be no less able than we to come to a just decision, while, if they were not guilty, they ought not to perish without trial.", src:"lysias_lamb", cite:"Lysias, Against the Corn-Dealers 22.2", why:"He tells what happened when the case came before the Council and what he said there. Narration sets out the facts in order (De inventione I.19.27)."},
  {id:"t-lys1-div", part:"division", text:"But I take it, sirs, that what I have to show is that Eratosthenes had an intrigue with my wife, and not only corrupted her but inflicted disgrace upon my children and an outrage on myself by entering my house; that this was the one and only enmity between him and me; that I have not acted thus for the sake of money, so as to raise myself from poverty to wealth; and that all I seek to gain is the requital accorded by our laws.", src:"lysias_lamb", cite:"Lysias, On the Murder of Eratosthenes 1.4", why:"He lists what he has to show: the intrigue, that this was the only enmity, that he did not act for money, and that he seeks only what the laws allow. Division sets out the points to be proved (De inventione I.22.31)."},
  {id:"t-arch-div", part:"division", text:"And if I feel that that indulgence is given and allowed me by you, I will soon cause you to think that this Aulus Licinius is a man who not only, now that he is a citizen, does not deserve to be expunged from the list of citizens, but that he is worthy, even if he were not one, of being now made a citizen.", src:"cic_yonge", cite:"Cicero, For Archias 4 (Yonge)", why:"Cicero names the two things he will show: that Archias, being a citizen, should not be struck from the list, and that he would deserve to be made one if he were not. Division sets out the points and their order (De inventione I.22.31)."},
  {id:"t-lys16-div", part:"division", text:"I will begin by showing that I did not serve in the cavalry or reside here under the Thirty, and that I had no hand in the government of that time.", src:"lysias_lamb", cite:"Lysias, In Defence of Mantitheus 16.3", why:"He announces the first points he will prove: that he did not serve in the cavalry, did not live in the city under the Thirty, and had no part in their government. Division names the points in dispute and the order of taking them (De inventione I.22.31)."},
  {id:"t-lys1-refut", part:"refutation", text:"Do but consider, sirs, what they say: they accuse me of ordering the maid-servant on that day to go and fetch the young man. Now I, sirs, could have held myself justified in using any possible means to catch the corrupter of my wife.", src:"lysias_lamb", cite:"Lysias, On the Murder of Eratosthenes 1.37", why:"He takes up the charge of the other side, that he sent the maid to fetch the young man, and begins to answer it. Refutation answers the arguments of the opponent (De inventione I.42.78)."},
  {id:"t-theb-refut", part:"refutation", text:"We say that if they did not Medize, it was because the Athenians did not do so either; just as afterwards when the Athenians attacked the Hellenes they, the Plataeans, were again the only Boeotians who Atticized.", src:"thuc_crawley", cite:"Thucydides 3.62, Thebes", why:"The Thebans answer the Plataeans’ boast that they alone refused to side with the Mede. Refutation answers what the other side has said (De inventione I.42.78)."},
  {id:"t-lys12-close", part:"peroration", text:"I will here conclude my accusation. You have heard, you have seen, you have suffered; you have them: give judgement.", src:"lysias_lamb", cite:"Lysias, Against Eratosthenes 12.100", why:"He marks the end and gathers the whole case into a few words: “You have heard, you have seen, you have suffered; you have them: give judgement.” The peroration sums up and moves the hearers to act (De inventione I.52.98)."},
  {id:"t-lys3-close", part:"peroration", text:"Justly, then, should I receive your pity, and that of all men else, not merely if I should meet with such a fate as Simon wishes, but even for having been compelled, as a result of such transactions, to stand my trial on such a charge.", src:"lysias_lamb", cite:"Lysias, Against Simon 3.48", why:"The last words of the speech ask for the jury’s pity. The peroration sums up and stirs the hearers, and Cicero names the appeal to pity as one of its parts (De inventione I.55.106)."},
  {id:"t-theb-close", part:"peroration", text:"Vindicate, therefore, Lacedaemonians, the Hellenic law which they have broken; and to us, the victims of its violation, grant the reward merited by our zeal.", src:"thuc_crawley", cite:"Thucydides 3.67, Thebes", why:"Near the end of their speech the Thebans tell the judges what to do: punish the breach of the law and reward Thebes. The peroration moves the hearers to the act (De inventione I.52.98)."},
  {id:"t-dem-fp-open", part:"exordium", text:"If some new subject were being brought before us, men of Athens, I would have waited until most of your ordinary advisers had declared their opinion; and if anything that they said were satisfactory to me, I would have remained silent, and only if it were not so, would I have attempted to express my own view. But since we find ourselves once more considering a question upon which they have often spoken, I think I may reasonably be pardoned for rising first of all. For if their advice to you in the past had been what it ought to have been, you would have had no occasion for the present debate.", src:"demosth", cite:"Demosthenes, First Philippic 1 (Pickard)", why:"He explains why he rises first, before the usual advisers: their past advice has failed. An opening makes the hearers attentive and well-disposed toward the speaker (De inventione I.15.20)."},
  {id:"t-burke-open", part:"exordium", text:"I hope, Sir, that notwithstanding the austerity of the Chair, your good nature will incline you to some degree of indulgence towards human frailty. You will not think it unnatural that those who have an object depending, which strongly engages their hopes and fears, should be somewhat inclined to superstition.", src:"burke_n", cite:"Edmund Burke, Speech on Conciliation with the Colonies (1775)", why:"Burke asks the Speaker’s indulgence and confesses his anxiety about the motion. An opening wins goodwill and attention before the matter is begun (De inventione I.15.20)."},
  {id:"t-dem-crown-narr", part:"narration", text:"When the Phocian war had broken out (not through any action of mine, for I had not yet entered public life), your own attitude, in the first place, was such, that you wished for the preservation of the Phocians, although you saw that their actions were unjustifiable; while you would have been delighted at anything that might happen to the Thebans, against whom you felt an indignation that was neither unreasonable nor unfair; for they had not used their good fortune at Leuctra with moderation.", src:"demosth", cite:"Demosthenes, On the Crown 18 (Pickard)", why:"He begins the story of the years before the peace with the outbreak of the Phocian war and the feelings of the Athenians at the time. Narration sets out what happened, in order (De inventione I.19.27)."},
  {id:"t-burke-div", part:"division", text:"The capital leading questions on which you must this day decide are these two: First, whether you ought to concede; and secondly, what your concession ought to be.", src:"burke_n", cite:"Edmund Burke, Speech on Conciliation with the Colonies (1775)", why:"Burke names the two questions before the House and their order: whether to concede, and what to concede. Division sets out the points to be decided and the order of taking them (De inventione I.22.31)."},
  {id:"t-per-resources", part:"proof", text:"As to the war and the resources of either party, a detailed comparison will not show you the inferiority of Athens. Personally engaged in the cultivation of their land, without funds either private or public, the Peloponnesians are also without experience in long wars across sea, from the strict limit which poverty imposes on their attacks upon each other.", src:"thuc_crawley", cite:"Thucydides 1.141, Pericles", why:"Pericles gives his own argument that Athens can win: the Peloponnesians have no funds and no experience of long wars across the sea. Proof sets out the speaker’s own arguments (De inventione I.24.34)."},
  {id:"t-burke-english", part:"proof", text:"First, the people of the Colonies are descendants of Englishmen. England, Sir, is a nation which still, I hope, respects, and formerly adored, her freedom. The Colonists emigrated from you when this part of your character was most predominant; and they took this bias and direction the moment they parted from your hands. They are therefore not only devoted to liberty, but to liberty according to English ideas, and on English principles.", src:"burke_n", cite:"Edmund Burke, Speech on Conciliation with the Colonies (1775)", why:"This is the first of Burke’s reasons for the colonists’ love of liberty: they are descended from Englishmen and keep English ideas of freedom. Proof gives the speaker’s own arguments, one by one (De inventione I.24.34)."},
  {id:"t-dem-chers-refut", part:"refutation", text:"'But, of course, he will not really get there.' And who can guarantee that? Do you realize, men of Athens, or take into account, what the coming season of the year is, the season against which some think you ought to evacuate the Hellespont and hand it over to Philip?", src:"demosth", cite:"Demosthenes, On the Chersonese 18 (Pickard)", why:"He quotes the other side’s comfort, “But, of course, he will not really get there,” and answers it with a question. Refutation takes up what the opponents say and answers it (De inventione I.42.78)."},
  {id:"t-lys24-horse", part:"refutation", text:"As to my horsemanship, which he has dared to mention to you, feeling neither awe of fortune nor shame before you, there is not much to tell. For I, gentlemen, am of opinion that all who suffer from some affliction make it their single aim and constant study to manage the condition that has befallen them with the least amount of discomfort. I am such an one, and in the misfortune that has stricken me I have devised this facility for myself on the longer journeys that I find necessary.", src:"lysias_lamb", cite:"Lysias, On the Refusal of a Pension to the Invalid 24.10 (Lamb)", why:"He takes up the accuser’s point about his riding and explains it by his disability. Refutation answers the arguments of the other side (De inventione I.42.78)."},
  {id:"t-lys24-archon", part:"refutation", text:"So utterly has he surpassed the whole human race in impudence that he tries with his single voice to persuade you all that I am not classed as disabled. Yet if he should persuade any of you on this point, gentlemen, what hinders me from drawing a lot for election as one of the nine archons, and you from depriving me of my obol as having sound health, and voting it unanimously to this man as being a cripple? For surely, after you have deprived a man of the grant as being able-bodied, the law officers are not going to debar this same person, as being disabled, from drawing a lot!", src:"lysias_lamb", cite:"Lysias, On the Refusal of a Pension to the Invalid 24.13 (Lamb)", why:"He answers the claim that he is not disabled by showing what would follow if the jury accepted it. Refutation answers the other side, here by drawing an absurd consequence from its claim (De inventione I.42.78)."},
  {id:"t-dem-crown-close", part:"peroration", text:"Never, O all ye gods, may any of you consent to their desire! If it can be, may you implant even in these men a better mind and heart. But if they are verily beyond all cure, then bring them and them alone to utter and early destruction, by land and sea. And to us who remain, grant the speediest release from the fears that hang over us, and safety that naught can shake!", src:"demosth", cite:"Demosthenes, On the Crown 324 (Pickard)", why:"These are the last words of the speech: a prayer against his enemies and for the safety of the city. The peroration closes the speech and moves the hearers (De inventione I.52.98)."},
  {id:"t-burke-close", part:"peroration", text:"English privileges have made it all that it is; English privileges alone will make it all it can be. In full confidence of this unalterable truth, I now, quod felix faustumque sit, lay the first stone of the Temple of Peace…", src:"burke_n", cite:"Edmund Burke, Speech on Conciliation with the Colonies (1775)", why:"Burke gathers his case into one claim about English privileges and then moves his resolutions. The peroration sums up and moves the hearers to act (De inventione I.52.98)."},
];
const ENTHYMEMES = [
  {id:'e1', said:'Catiline still lives — and sits in the senate.', missing:'A man who plots the massacre of the senate ought not to sit in it.',
    distractors:['A senator keeps his seat until the senate itself has voted to remove him from it.','A plotter is safest where the consul can watch him.','A citizen not yet condemned by a court has every right to sit and speak in the senate.'], src:'cic_cat', cite:'Cicero, First Catilinarian 1.2'},
  {id:'e2', said:'My boy was struck by this young man’s javelin and died; I charge him with unintentional homicide.', missing:'Whoever caused a death, even without intent, is liable for the killing.',
    distractors:['No one is liable for a death that he did not intend, whatever his hand may have done.','A death on the training field is the trainer’s fault.','Only a killing done with malice can be brought before a court as a charge of homicide.'], src:'antiphon', cite:'Antiphon, Second Tetralogy 3.1'},
  {id:'e3', said:'If logos deceived her, Helen is not culpable.', missing:'One who is acted on by a cause as strong as a drug or a kidnapper’s hand is not the author of the act.',
    distractors:['One who is persuaded by speech has given her consent, and so she is the author of whatever she does after it.','Speech is too weak a power to move anyone to act against her own will and judgment.','A woman deceived by words is more to blame than one carried off by force of arms.'], src:'gorgias_vh', cite:'Gorgias, Helen 8–14'},
  {id:'e4', said:'A democracy is incapable of empire — so Cleon, urging that Mytilene be punished without reopening the case.', missing:'To hold empire one must be willing to punish without being talked out of it.',
    distractors:['An empire is best held by mercy to rebels, since kindness wins back the subject cities.','A sentence passed in anger ought to be reopened later.','A democracy holds its allies by persuasion, and so it should hear every case twice.'], src:'thuc_crawley', cite:'Thucydides 3.37, Cleon'},
  {id:'e5', said:'I have not lived so long, Lacedaemonians, without having had the experience of many wars.', missing:'Experience of war teaches that it is not to be longed for as a good.',
    distractors:['The old have seen many victories, and so they know that war brings glory and gain.','Old men are too cautious to judge a war rightly.','A city that has fought many wars has learned that each new war is easier than the last.'], src:'thuc_crawley', cite:'Thucydides 1.80, Archidamus'},
  {id:'e6', said:'Our constitution does not copy the laws of neighbouring states; we are rather a pattern to others than imitators ourselves.', missing:'What is original and successful is more to be praised than what is borrowed.',
    distractors:['A city deserves most praise when it takes the best laws of its neighbors for its own.','The oldest constitution is always the best.','No constitution is better than another, since every city simply follows its own custom.'], src:'thuc_crawley', cite:'Thucydides 2.37, Pericles'},
  {id:'e7', said:'The unwritten laws of Heaven were not born today nor yesterday; they die not, and none knows their birth.', missing:'A human decree cannot override a law that is not of human making.',
    distractors:['The decree of the ruler binds every subject, whatever the gods may be thought to command.','A law is valid only if it is written down.','The newest law must prevail over an older one, since it shows the latest will of the city.'], src:'soph_storr', cite:'Sophocles, Antigone 450–457 (Storr)'},
  {id:'e8', said:'Men are not born with the art of politics; Zeus sent Hermes with dike and aidos for all.', missing:'If justice and shame had been given only to a few, cities could not stand.',
    distractors:['Justice and shame, like the other arts, need be given only to a few experts in each city.','What the gods give to all men is of little worth.','Cities are held together by force alone, and need neither justice nor shame in their citizens.'], src:'plato_jowett', cite:'Plato, Protagoras 322c–d (Jowett)'},
  {id:'e9', said:'The unexamined life is not worth living.', missing:'A life that is not worth living ought not to be chosen even to escape death.',
    distractors:['Any life at all is better than death, and so a man should accept any terms to keep it.','The jury decides which life is worth living.','A man may give up philosophy for a time and take it up again when the danger has passed.'], src:'plato_jowett', cite:'Plato, Apology (Jowett)'},
  {id:'e10', said:'The strong do what they can and the weak suffer what they must.', missing:'Right has no standing where power is unequal; only interest remains.',
    distractors:['Right is the same between unequal powers as between equals, and it binds the strong alike.','The gods protect the weak against the strong.','A strong city gains most by sparing the weak, whose goodwill it may need later.'], src:'thuc_crawley', cite:'Thucydides 5.89, Melian dialogue'},
  {id:'e11', said:'Inflict only such penalties as the laws have provided.', missing:'A penalty not in the law is itself a new crime against the republic.',
    distractors:['In a time of danger the senate may set any penalty that the safety of the state requires.','The heavier the penalty, the surer the deterrent.','The laws were written for ordinary crimes, and a conspiracy against the state is not one.'], src:'sallust_w', cite:'Sallust, Catiline 51, Caesar'},
  {id:'e12', said:'Give me chastity and continency, only not yet.', missing:'A prayer that postpones the good it names is still a love of the old disease.',
    distractors:['A prayer for chastity is answered the moment it is spoken, whenever its fulfillment comes.','To ask for a good is already to will it wholly.','To ask for a virtue at a later time is already to possess that virtue in the present.'], src:'aug_pusey', cite:'Augustine, Confessions VIII (Pusey)'},
  {id:'e13', said:'I have a better right to command than others — I must begin with this as Nicias has attacked me.', missing:'The man whose private splendor brings the city profit is fit to command.',
    distractors:['A man who spends his wealth on display is unfit to be trusted with the city’s fleet.','A general’s private life has no bearing on command.','Command belongs to the oldest citizen, whatever his wealth or his reputation abroad.'], src:'thuc_crawley', cite:'Thucydides 6.16, Alcibiades'},
  {id:'e14', said:'An eloquent man must speak so as to teach, to delight, and to persuade.', missing:'These three offices belong to the same orator, not to three different arts.',
    distractors:['Teaching belongs to the philosopher and persuading to the orator, and no one man does both.','An orator need only persuade, and never teach.','Delight is a vice in speech about sacred things, and the Christian orator should avoid it.'], src:'ddc', cite:'Augustine, De doctrina christiana IV'},
  {id:'e15', said:'Remember that there are but three considerable naval powers in Hellas—Athens, Corcyra, and Corinth—and that if you allow two of these three to become one, and Corinth to secure us for herself, you will have to hold the sea against the united fleets of Corcyra and Peloponnese.', missing:'It is folly to let two naval powers combine against you when you might keep one as an ally.',
    distractors:['Athens can always defeat the fleets of Corinth and Corcyra together, whatever alliance they make.','A naval power far from Athens can never be a danger to her, whichever side it takes.','Athens should keep clear of every alliance at sea, so that no war can be laid to her charge.'], src:'thuc_crawley', cite:'Thucydides 1.36, Corcyra'},
  {id:'e16', said:'To-day has brought to a close the long silence which I had observed during the recent troubles.', missing:'When the republic can again hear a free voice, the orator ought to speak.',
    distractors:['An orator who has kept silent for years has lost the right to speak in the senate.','Silence is safer than speech under a single ruler.','A senator owes the victor his silence, and should break it only if he is asked to speak.'], src:'cic_orat', cite:'Cicero, Pro Marcello 1'},
  {id:'e17', said:'Fear not, for you shall not be confounded — so the poor are to be comforted, while the rich are to be made afraid of elation.', missing:'The same vice is not cured by the same word in every hearer.',
    distractors:['One admonition, rightly framed, suits every hearer, whether he is poor or rich.','Fear cures the poor, and comfort cures the rich.','The rich and the poor are to be comforted alike, since both alike are in tribulation.'], src:'greg', cite:'Gregory, Pastoral Care III'},
  {id:'e18', said:'Although I am afraid, gentlemen of the jury, that fear is unseemly in a speech for the bravest of men.', missing:'If even the advocate of the brave man is afraid, the danger to the republic is real.',
    distractors:['An advocate who confesses fear has already admitted that his client’s cause is weak.','A brave man needs no defense, so the words of his advocate add nothing to the case.','Fear in a speaker is a fault of character, and the jury should discount what he says.'], src:'cic_cat', cite:'Cicero, Pro Milone 1'},
  // English tradition (public-domain quotations; sources eng_cer, eng_cem, kjv).
  {id:'eng-e1', said:'Thus I consent, sir, to this Constitution, because I expect no better, and because I am not sure that it is not the best.', missing:'Where no better plan can be had, a plan that may be the best ought to be accepted.', distractors:['A plan should be rejected until every member is sure that it is the best that can be had.','A wise man consents only to what he has first proved to be without fault.','A delegate who doubts a plan ought to vote against it, so that a better plan may be framed.'], src:'eng_cer', cite:'Benjamin Franklin, Speech at the Federal Convention (1787)'},
  {id:'eng-e2', said:'“A house divided against itself cannot stand.” I believe this government cannot endure permanently half slave and half free.', missing:'A nation divided over slavery is a house divided against itself.', distractors:['A nation can remain half slave and half free for as long as its parts keep their bargain.','Division over slavery strengthens a union.','A saying from Scripture about houses has no bearing on the government of a nation.'], src:'eng_cem', cite:'Abraham Lincoln, Speech at Springfield (1858)'},
  {id:'eng-e3', said:'They tell us, sir, that we are weak – unable to cope with so formidable an adversary. But when shall we be stronger? Will it be the next week, or the next year?', missing:'Delay will only leave us weaker, so if we are ever to resist it must be now.', distractors:['Every year of peace adds to our strength, so the longer we wait the stronger we shall be.','Britain will grow weaker if the colonies wait.','A weak people should never resist, whether now or later, since resistance cannot succeed.'], src:'eng_cer', cite:'Patrick Henry, Speech to the Second Virginia Convention (1775)'},
  {id:'eng-e4', said:'The gentleman asks, When were the colonies emancipated? I desire to know, when were they made slaves?', missing:'Those who were never made slaves need no emancipation to be free.', distractors:['Colonies are born subject to their mother country and are free only once she releases them.','Freedom belongs only to those freed by law.','A people who have been taxed by Parliament have already been made subjects, not free men.'], src:'eng_cer', cite:'William Pitt (the Elder), Speech in the House of Commons (1766)'},
  {id:'eng-e5', said:'If you do not succeed, you are without resource: for, conciliation failing, force remains; but, force failing, no further hope of reconciliation is left.', missing:'A course that leaves a second resource if it fails is to be tried before one that leaves none.', distractors:['The surest course is to be tried first, whatever is left to us if it should fail.','Force should be tried first, because conciliation can still be offered to the colonies after a victory has been won.','Once conciliation has failed, no other course is open, so it should be kept for last.'], src:'eng_cer', cite:'Edmund Burke, Speech on Conciliation with the Colonies (1775)'},
  {id:'eng-e6', said:'Ambition must be made to counteract ambition.', missing:'Since men are not angels, power can be checked only by setting one interest against another.', distractors:['Men in power can be trusted to restrain themselves once they have sworn an oath to the constitution.','Ambition should be removed from government, since a free state needs only virtuous men.','The vote of the people alone is enough to keep every branch of the government within its bounds.'], src:'eng_cer', cite:'James Madison, The Federalist no. 51 (1788)'},
  {id:"e-nic-folly", said:"Now it is folly to go against men who could not be kept under even if conquered, while failure would leave us in a very different position from that which we occupied before the enterprise.", missing:"A city ought not to vote an expedition that cannot hold its conquest and that leaves it worse if it fails.",
    distractors:["A city should sail against any enemy it can defeat, whether or not it can hold what it wins afterward.", "An expedition is worth its risk whenever victory is possible, since failure abroad costs a city little.", "A conquest far from home is easier to hold than one near at hand, because the conquered cannot easily rebel."], src:"thuc_crawley", cite:"Thucydides 6.11, Nicias", why:"Nicias calls the sailing “folly” because those men “could not be kept under even if conquered,” and because failure would leave Athens in “a very different position”. The hearers supply the premise that an expedition of that kind ought not to be voted."},
  {id:"e-nic-fear", said:"The Hellenes in Sicily would fear us most if we never went there at all, and next to this, if after displaying our power we went away again as soon as possible.", missing:"The safer course is the one that leaves a distant enemy most afraid of us.",
    distractors:["A people fears only the army that has already landed and begun to burn its towns.", "Sicily will send tribute of her own accord if Athens never shows a fleet at all.", "Fear of Athens ends as soon as a treaty is signed and the Spartans go home."], src:"thuc_crawley", cite:"Thucydides 6.11, Nicias", why:"He says the Hellenes in Sicily “would fear us most if we never went there at all,” and next if Athens displayed her power and left. The unstated premise is that Athens should choose the course that leaves those Hellenes most afraid."},
  {id:"e-nic-egest", said:"Our struggle, therefore, if we are wise, will not be for the barbarian Egestaeans in Sicily, but how to defend ourselves most effectually against the oligarchical machinations of Lacedaemon.", missing:"A wise city fights the enemy at her door before she fights for a distant ally.",
    distractors:["A city keeps its allies only by sending help to every one of them, however far away, before it looks to its own walls.", "The enemy at the door is the least danger, because he is already known.", "A barbarian ally is always a safer cause for Athens than any Greek city close to home."], src:"thuc_crawley", cite:"Thucydides 6.11, Nicias", why:"The struggle of a wise city, he says, “will not be for the barbarian Egestaeans in Sicily, but how to defend ourselves” against Sparta. The hearers must supply that the nearer danger is the one a wise city meets first."},
  {id:"e-corc-navy", said:"For your first endeavour should be to prevent, if possible, the existence of any naval power except your own; failing this, to secure the friendship of the strongest that does exist.", missing:"A rival fleet that is not a friend will be turned against the city that let it grow.",
    distractors:["A navy that a city allows to grow will stay grateful to the city that did not hinder it.", "Athens is safest when every neighboring city is encouraged to build a navy of her own.", "A naval power grows more friendly to Athens in proportion as Athens leaves it alone."], src:"thuc_crawley", cite:"Thucydides 1.35, Corcyra", why:"The Corcyraeans tell Athens her “first endeavour should be to prevent” any naval power but her own, and failing that to secure “the friendship of the strongest that does exist.” The premise they leave to the assembly is that a rival fleet, if not a friend, will be used against her."},
  {id:"e-corc-colony", said:"let her know that every colony that is well treated honours its parent state, but becomes estranged from it by injustice.", missing:"Corinth has treated this colony unjustly, so Corcyra owes her no honor and may seek another ally.",
    distractors:["Every colony remains the subject of its founder, and a wrong done by the parent only increases the honor owed.", "A colony that has been wronged should bear it in silence, since a quarrel with its founder shames them both.", "A parent that has been unjust is owed a greater honor, and the colony may not seek any other ally."], src:"thuc_crawley", cite:"Thucydides 1.34, Corcyra", why:"They answer Corinth with the rule that “every colony that is well treated honours its parent state, but becomes estranged from it by injustice.” The hearers supply that Corcyra’s estrangement follows from Corinth’s injustice, and so the colony is free to seek another ally."},
  {id:"e-cori-aux", said:"For you cannot become their auxiliary and remain our friend; if you join in their attack, you must share the punishment which the defenders inflict on them.", missing:"The ally of an attacker shares the penalty that the defender inflicts.",
    distractors:["Athens can arm Corcyra against Corinth and still be counted Corinth’s friend.", "A defender never turns his punishment upon the ally of the city that attacked him.", "Friendship between two cities survives any fleet sent against one of their colonies."], src:"thuc_crawley", cite:"Thucydides 1.40, Corinth", why:"Corinth tells Athens “you cannot become their auxiliary and remain our friend”, and that if Athens joins the attack she must “share the punishment which the defenders inflict”. The premise is that the ally of an attacker is treated as a party to the attack."},
  {id:"e-cori-punish", said:"It is now our turn to benefit by the principle that we laid down at Lacedaemon, that every power has a right to punish her own allies.", missing:"A principle a city has already used for herself she must allow another city to use.",
    distractors:["Sparta has forbidden every city in the alliance to punish one of its own allies.", "Corinth has never claimed any right to punish a colony or an ally of her own.", "A principle once spoken at Lacedaemon binds only the ambassador who happened to speak it."], src:"thuc_crawley", cite:"Thucydides 1.43, Corinth", why:"Corinth asks to “benefit by the principle” she and others “laid down at Lacedaemon, that every power has a right to punish her own allies.” The unstated premise is that a rule Athens has been willing to use may be used in turn against a Corinthian colony."},
  {id:"e-herm-abstain", said:"If the vanquished be defeated, and the victor conquer, through your refusing to join, what is the effect of your abstention but to leave the former to perish unaided, and to allow the latter to offend unhindered?", missing:"A city that can stop a conquest and does not stop it shares in the result.",
    distractors:["Camarina lies too far from Syracuse for either army to count her in this war.", "A refusal to join the fight leaves both the victor and the vanquished as they stood.", "The honor of the victor is lost whenever a neutral city chooses to stay at home."], src:"thuc_crawley", cite:"Thucydides 6.80, Hermocrates", why:"Hermocrates asks what abstention does but “leave the former to perish unaided, and to allow the latter to offend unhindered”. The premise he counts on is that a city able to join, which refuses, bears the defeat of one side and the offense of the other."},
  {id:"e-herm-prize", said:"If the Athenians reduce us, they will owe their victory to your decision, but in their own name will reap the honour, and will receive as the prize of their triumph the very men who enabled them to gain it.", missing:"The city whose decision gives a conqueror his victory will itself be taken as the prize.",
    distractors:["Athens has already promised Camarina the tribute and the harbour of Syracuse.", "A vote to stay neutral cannot be the cause of any other city’s victory in the field.", "The prize of a victory is paid to the city that stayed away and refused to fight."], src:"thuc_crawley", cite:"Thucydides 6.80, Hermocrates", why:"If Athens wins, he says, she “will owe” the victory “to your decision” and “will receive as the prize of their triumph the very men who enabled them to gain it.” The hearers are to grant that the helper of a conqueror becomes the conqueror’s prize."},
  {id:"e-theb-medize", said:"We say that if they did not Medize, it was because the Athenians did not do so either; just as afterwards when the Athenians attacked the Hellenes they, the Plataeans, were again the only Boeotians who Atticized.", missing:"A city that followed a neighbor’s lead cannot claim the virtue of having chosen alone.",
    distractors:["Plataea was the only city in Boeotia that had a wall in the year of the Mede.", "The Athenians went over to the Mede, and Plataea refused to follow that lead.", "Atticizing is simply the name for a city that stood against the Mede in the war."], src:"thuc_crawley", cite:"Thucydides 3.62, Thebes", why:"The Thebans say that if the Plataeans “did not Medize, it was because the Athenians did not do so either” and that later the Plataeans “were again the only Boeotians who Atticized.” The premise is that following Athens is not a virtue the Plataeans can claim as their own."},
  {id:"e-theb-mistress", said:"The city as a whole was not its own mistress when it so acted, and ought not to be reproached for the errors that it committed while deprived of its constitution.", missing:"A city that has lost its constitution is not to be blamed for what it did under that loss.",
    distractors:["Every city is blamed for the acts it happened to do while it was without laws.", "Thebes remained her own mistress through the whole of the war against the Mede.", "A constitution is lost only after the other cities have already praised the loser."], src:"thuc_crawley", cite:"Thucydides 3.62, Thebes", why:"They say the city “was not its own mistress when it so acted,” and “ought not to be reproached for the errors that it committed while deprived of its constitution.” The hearers supply that blame attaches to a city only when it is free to choose."},
  {id:"e-cato-vain", said:"Other crimes you may punish after they have been committed; but as to this, unless you prevent its commission, you will, when it has once taken effect, in vain appeal to justice.", missing:"A crime that destroys the court itself must be stopped before it is committed.",
    distractors:["Every crime is punished more justly once the city has fallen and the courts are gone.", "The senate has no power to act on a plot until the same charge has been tried twice.", "An appeal to justice can be heard only after the laws of the city have been suspended."], src:"sallust_w", cite:"Sallust, Catiline 52, Cato", why:"Cato allows that “Other crimes you may punish after they have been committed” but says that for this one, unless they “prevent its commission,” they will “in vain appeal to justice.” The premise is that this crime removes the court in which a later appeal could be heard."},
  {id:"e-cato-taken", said:"When the city is taken, no power is left to the vanquished.", missing:"A sentence passed after the city has fallen cannot restore the power to pass it.",
    distractors:["The vanquished keep their courts, their laws, and their full power of punishment.", "A city that has already been taken is the safest place left in which to judge a man.", "The senate’s power to punish grows greater in proportion as the city itself is lost."], src:"sallust_w", cite:"Sallust, Catiline 52, Cato", why:"The sentence is “When the city is taken, no power is left to the vanquished.” It becomes a reason to act now only if the hearers supply that a judgment delivered after that loss cannot bring the power back."},
  {id:"e-nic-behind", said:"I affirm, then, that you leave many enemies behind you here to go yonder and bring more back with you.", missing:"A city ought not to leave the enemies already at her door in order to make new ones abroad.",
    distractors:["The enemies left at home have already asked for peace, and the voyage will bring none of them back.", "Egesta has undertaken to fight every enemy Athens leaves behind, so the sailing adds no danger.", "A city grows safer in proportion as she leaves a greater number of enemies unattended at home."], src:"thuc_crawley", cite:"Thucydides 6.10, Nicias", why:"Nicias affirms that Athens will “leave many enemies behind you here to go yonder and bring more back with you.” The assembly has to supply that this exchange, old enemies left and new ones gained, is a reason to refuse the sailing."},
  {id:"e-nic-admire", said:"We all know that that which is farthest off, and the reputation of which can least be tested, is the object of admiration; at the least reverse they would at once begin to look down upon us, and would join our enemies here against us.", missing:"A reputation admired only because it is untested will collapse at the first reverse, and is no ground for a voyage.",
    distractors:["What is farthest off is always the safest conquest, because distance itself keeps the enemy from striking back.", "A reputation that has never been tested grows stronger at the first reverse, and the allies at home take heart.", "Sicily will admire Athens more after a defeat than after a victory, and will then pay tribute of her own accord."], src:"thuc_crawley", cite:"Thucydides 6.11, Nicias", why:"“that which is farthest off, and the reputation of which can least be tested, is the object of admiration”, and “at the least reverse” those who admired it “would at once begin to look down upon us”. The voyage is to be refused only if the hearers grant that an untested reputation is no ground for sending the fleet."},
  {id:"e-corc-before", said:"Now it is our policy to be beforehand with her—that is, for Corcyra to make an offer of alliance and for you to accept it; in fact, we ought to form plans against her instead of waiting to defeat the plans she forms against us.", missing:"The city that waits to answer an enemy’s plan has already given that enemy the first move.",
    distractors:["Corinth has published her plan in full, so Athens can wait and still strike the first blow.", "A plan formed after the enemy has moved is always the stronger, because it answers a known design.", "Corcyra asks Athens to wait until Corinth has finished her armament and then to vote on the alliance."], src:"thuc_crawley", cite:"Thucydides 1.33, Corcyra", why:"Their policy is “to be beforehand with her”, and they say “we ought to form plans against her instead of waiting to defeat the plans she forms against us.” The premise which turns that policy into a reason to accept the alliance now is that waiting hands Corinth the first move."},
  {id:"e-corc-sea", said:"And there is a wide difference between declining the alliance of an inland and of a maritime power.", missing:"Athens may refuse an inland ally, but she cannot with safety refuse a power that brings a fleet.",
    distractors:["An inland city and a naval city are the same sort of ally, and Athens may refuse either without a loss.", "A maritime ally weakens the city that receives her, and an inland ally is the one Athens must not refuse.", "Corcyra has no ships to offer, and the difference she names is only a difference of dialect."], src:"thuc_crawley", cite:"Thucydides 1.36, Corcyra", why:"They tell Athens there is “a wide difference between declining the alliance of an inland and of a maritime power.” The sentence does not say what the difference comes to. The assembly must supply that a fleet touches Athens’ own safety in a way an inland city does not."},
  {id:"e-cori-crime", said:"And not satisfied with their own misconduct there, they appear here now requiring you to join with them not in alliance but in crime, and to receive them in spite of their being at enmity with us.", missing:"To take in a city already at war with one’s friend is to share that quarrel, and not merely to add an ally.",
    distractors:["Corcyra is at peace with Corinth, and her request is only for a place in the Athenian games.", "A city may arm the enemy of a friend and remain that friend’s ally in every particular.", "Enmity with Corinth makes the reception of Corcyra a favor Corinth has already asked Athens to grant."], src:"thuc_crawley", cite:"Thucydides 1.37, Corinth", why:"Corinth says the Corcyraeans ask Athens “to join with them not in alliance but in crime, and to receive them in spite of their being at enmity with us.” The premise is that reception of a city already at enmity with Corinth is a share in that enmity."},
  {id:"e-cori-shared", said:"No, they should have shared their power with you before they asked you to share your fortunes with them.", missing:"A city that never shared its strength has no claim on the help of the city it shut out.",
    distractors:["Corcyra shared her fleet with Athens for many years, and the debt of that sharing is now due.", "A city in peril is owed help in proportion as she has always refused to share her power.", "Athens asked Corcyra for a share of Corcyra’s power, and Corcyra granted it before this war."], src:"thuc_crawley", cite:"Thucydides 1.37, Corinth", why:"Corinth says they “should have shared their power with you before they asked you to share your fortunes with them.” The general rule the hearers must add is that help is owed to those who have already shared their strength, and not to those who ask only when they are in peril."},
  {id:"e-cori-offend", said:"Why, if you make it your policy to receive and assist all offenders, you will find that just as many of your dependencies will come over to us, and the principle that you establish will press less heavily on us than on yourselves.", missing:"A rule that lets every subject desert its master will be turned against the city that made the rule.",
    distractors:["Athens has no subjects who could leave her, so a rule about receiving offenders cannot touch her.", "Corinth will be bound by the rule more tightly than Athens, and Athens’ dependencies will stay where they are.", "A policy of receiving offenders keeps every subject loyal to the city that announced the policy."], src:"thuc_crawley", cite:"Thucydides 1.40, Corinth", why:"If Athens receives “all offenders”, then “just as many of your dependencies will come over to us”, and the principle “will press less heavily on us than on yourselves.” The practical premise is that a city should not establish a rule that her own subjects can use against her."},
  {id:"e-herm-distant", said:"And do we fancy when destruction first overtakes a distant fellow countryman that the danger will not come to each of us also, or that he who suffers before us will suffer in himself alone?", missing:"A danger that has reached one city of the island will reach the city that leaves her to face it alone.",
    distractors:["A distant city’s fall leaves every other city of Sicily safer than she was on the day before that fall.", "The first city to suffer is the last city to suffer, and the danger ends in the place where it began.", "Camarina lies too far from Syracuse for an Athenian victory there to change anything in her own safety."], src:"thuc_crawley", cite:"Thucydides 6.78, Hermocrates", why:"He asks whether they fancy that “destruction” overtaking “a distant fellow countryman” “will not come to each of us also”, or that the one who “suffers before us will suffer in himself alone”. The premise he counts on is that a danger which has reached one of them will reach the rest if they stand apart."},
  {id:"e-herm-neither", said:"And you need not think that your prudent policy of taking sides with neither, because allies of both, is either safe for you or fair to us.", missing:"To take sides with neither, when one side is under attack, is already to favor the attacker.",
    distractors:["A city allied to both sides may refuse both, and the refusal leaves each side exactly as it stood.", "Neutrality is safe for Camarina precisely because she is allied to the city that is being attacked.", "Syracuse has asked Camarina to take neither side, and she calls that course fair to herself."], src:"thuc_crawley", cite:"Thucydides 6.79, Hermocrates", why:"He tells them not to think that “taking sides with neither, because allies of both, is either safe for you or fair to us.” The sentence denies their description of the policy. The premise still to be granted is that standing aside while one ally is attacked favors the attacker."},
  {id:"e-plat-chiefs", said:"Besides, the faults that either of you may commit in your supremacy must be laid, not upon the followers, but on the chiefs that lead them astray.", missing:"Plataea followed Athens into the war, so the blame for that following lies on Athens and not on Plataea.",
    distractors:["The follower is blamed for every fault of the chief, and the chief is held clear of it.", "Plataea led Athens into the war, and Athens was the follower who was led astray.", "A city that follows an ally is praised for the faults of the ally, and the ally is blamed for the following."], src:"thuc_crawley", cite:"Thucydides 3.55, Plataea", why:"They lay it down that faults committed “in your supremacy must be laid, not upon the followers, but on the chiefs that lead them astray.” The rule is stated. The case the judges must supply is that Plataea was the follower and Athens the chief."},
  {id:"e-cato-stake", said:"We are not now debating on the revenues, or on injuries done to our allies, but our liberty and our life is at stake.", missing:"When liberty and life are the question, the senate must not handle it as a dispute about revenue or about allies.",
    distractors:["The debate is only about the revenues and about injuries done to the allies, and life is not in question.", "A question of liberty is decided by the same quiet vote as a question of harbour dues.", "The allies have already been restored, and the revenues are the only matter left on the paper."], src:"sallust_w", cite:"Sallust, Catiline 52, Cato", why:"Cato says “We are not now debating on the revenues, or on injuries done to our allies, but our liberty and our life is at stake.” The premise which makes that a reason to drop ordinary counsel is that a threat to liberty and life is not an ordinary public question."},
  {id:"e-cato-names", said:"For some time past, it is true, we have lost the real name of things; for to lavish the property of others is called generosity, and audacity in wickedness is called heroism; and hence the state is reduced to the brink of ruin.", missing:"A state that gives vice the name of a virtue will be ruined by the vice it will not call by its own name.",
    distractors:["False names for vice have always kept the republic safe, and the treasury is the fuller for them.", "Generosity and heroism are the real names of the acts he describes, and the state grows stronger by them.", "The loss of the real names of things has no bearing on whether the prisoners are punished."], src:"sallust_w", cite:"Sallust, Catiline 52, Cato", why:"“we have lost the real name of things”, so that “to lavish the property of others is called generosity, and audacity in wickedness is called heroism”, “and hence the state is reduced to the brink of ruin.” The senate must supply that it ought not to decide this case under those false names."},
  {id:"e-cic-quit", said:"Quit Rome at last and soon; the city gates are open; depart at once: your camp under Manlius's command has too long been awaiting with anxiety the arrival of its general.", missing:"The general of a camp raised against the city has no place left in the city, and should be sent to that camp.",
    distractors:["Manlius has raised no camp at all, and the consul’s order is only that Catiline take a house nearer the forum.", "A general whose camp is waiting for him is the man the senate most needs to keep sitting in his place.", "The city gates are shut against him, and the order is that Catiline remain until that camp has been dispersed."], src:"cic_cat", cite:"Cicero, First Catilinarian 1.10", why:"The order is “Quit Rome at last and soon; the city gates are open; depart at once”, because “your camp under Manlius's command has too long been awaiting” “the arrival of its general.” The premise is that the general of that camp does not belong in the senate."},
  {id:"e-cic-either", said:"Therefore let them either depart now or cease to trouble us; or else, if they choose to remain in Rome and to remain of the same mind, let them expect to receive the reward they deserve.", missing:"Men who will neither leave the city nor give up their purpose are to be treated as enemies still inside it.",
    distractors:["Those who remain in Rome of the same mind are to be thanked for staying, and departure is the only crime.", "The reward of remaining is a public pardon, and the reward of departing is a prosecution in the courts.", "Cicero asks them to stay in Rome and to keep, unchanged, the purpose with which they entered the city."], src:"cic_cat", cite:"Cicero, Second Catilinarian 2.6", why:"“let them either depart now or cease to trouble us”, and if they “remain in Rome and” “remain of the same mind, let them expect to receive the reward they deserve.” The premise is that to stay, and to stay of that mind, is to choose the punishment of an enemy."},
  {id:"e-burke-tyrants", said:"Kings will be tyrants from policy, when subjects are rebels from principle.", missing:"Subjects who rebel on a principle leave a king no policy but tyranny, and that kind of rebellion is the one to refuse.",
    distractors:["A king grows mild in proportion as his subjects rebel on a settled principle, and obedience is what makes him cruel.", "Rebellion undertaken from private interest makes kings into tyrants, and rebellion from principle is what keeps them just.", "Kings become tyrants only while their subjects remain obedient, and a subject who rebels on principle restores the old law."], src:"eng_cer", cite:"Edmund Burke, Reflections on the Revolution in France (1791)", why:"“Kings will be tyrants from policy, when subjects are rebels from principle.” The sentence predicts the pair. It becomes a warning against that rebellion only if the hearers supply that a rebellion undertaken on principle is the course to refuse."},
  // Added from the Mytilenean debate and from Pericles’ first speech; the doctrine is Rhetoric I.2, 1357a, and II.21–23.
  {id:"e-diod-speech", said:"As for the argument that speech ought not to be the exponent of action, the man who uses it must be either senseless or interested: senseless if he believes it possible to treat of the uncertain future through any other medium; interested if, wishing to carry a disgraceful measure and doubting his ability to speak well in a bad cause, he thinks to frighten opponents and hearers by well-aimed calumny.", missing:"Men can deliberate about an uncertain future only by means of speech.",
    distractors:["Deeds speak more plainly than words, and an assembly should judge a policy by its results alone.", "Debate only delays what must in the end be done.", "The future can be foreseen by experience without debate, as an old soldier foresees a battle."], src:"thuc_crawley", cite:"Thucydides 3.42, Diodotus", why:"Diodotus calls anyone who would silence debate “senseless if he believes it possible to treat of the uncertain future through any other medium.” The hearers supply that speech is the only means by which a city can deliberate about what is still to come."},
  {id:"e-diod-advisers", said:"The city is no gainer by such a system, since fear deprives it of its advisers; although in truth, if our speakers are to make such assertions, it would be better for the country if they could not speak at all, as we should then make fewer blunders.", missing:"A city that frightens away its honest advisers will be worse counselled than one that hears them.",
    distractors:["The assembly needs no advisers at all, since the people can judge each question for themselves without them.", "A city is best served when its speakers are afraid to give unpopular advice.", "Advisers who fear an accusation give the soundest and most careful counsel of all."], src:"thuc_crawley", cite:"Thucydides 3.42, Diodotus", why:"He says that “fear deprives it of its advisers,” and that the city is “no gainer” from it. The argument holds only if the hearers grant that a city without honest advisers is worse counselled."},
  {id:"e-diod-interest", said:"However, I have not come forward either to oppose or to accuse in the matter of Mitylene; indeed, the question before us as sensible men is not their guilt, but our interests.", missing:"An assembly that deliberates about the future must decide by what is expedient, not by what is just.",
    distractors:["An assembly must punish every guilty city, whatever the cost to its own interests and its own revenue.", "Guilt and interest always point the same way, so either one may decide the question.", "The Mitylenians are innocent, and so no question of guilt arises here."], src:"thuc_crawley", cite:"Thucydides 3.44, Diodotus", why:"He sets aside “their guilt” for “our interests.” That is a reason only if the hearers grant what Aristotle says of deliberative speech, that its end is the expedient and the harmful (Rhetoric I.3, 1358b)."},
  {id:"e-diod-err", said:"All, states and individuals, are alike prone to err, and there is no law that will prevent them; or why should men have exhausted the list of punishments in search of enactments to protect them from evildoers?", missing:"If no penalty can keep men from erring, the death of the Mitylenians will not keep the next city from revolt.",
    distractors:["A city that revolts ought to suffer the heaviest penalty the law allows, so that every other ally is deterred from trying.", "The laws of Athens already fix a single penalty for revolt, and the assembly has no power to set it aside.", "Men err only where the law is silent, so a stricter law against revolt will put an end to the danger."], src:"thuc_crawley", cite:"Thucydides 3.45, Diodotus", why:"Diodotus says that “All, states and individuals, are alike prone to err, and there is no law that will prevent them.” This becomes a reason to spare Mytilene only if the hearers supply that the death penalty is one more such law, and so it will not prevent the next revolt."},
  {id:"e-diod-surrender", said:"At present, if a city that has already revolted perceive that it cannot succeed, it will come to terms while it is still able to refund expenses, and pay tribute afterwards. In the other case, what city, think you, would not prepare better than is now done, and hold out to the last against its besiegers, if it is all one whether it surrender late or soon?", missing:"Men who will suffer the same whether they yield early or late have no reason to yield early.",
    distractors:["The harsher the penalty for revolt, the more cheaply Athens will take each city that rebels.", "A city that expects death on surrender will give up sooner, to shorten its sufferings.", "Besieged cities always yield at the same time, whatever penalty awaits them."], src:"thuc_crawley", cite:"Thucydides 3.46, Diodotus", why:"If “it is all one whether it surrender late or soon,” a city will “hold out to the last.” The premise the hearers supply is that men have no reason to yield early when yielding brings them no better terms."},
  {id:"e-diod-people", said:"But if you butcher the people of Mitylene, who had nothing to do with the revolt, and who, as soon as they got arms, of their own motion surrendered the town, first you will commit the crime of killing your benefactors; and next you will play directly into the hands of the higher classes, who when they induce their cities to rise, will immediately have the people on their side, through your having announced in advance the same punishment for those who are guilty and for those who are not.", missing:"Athens holds her empire through the goodwill of the common people in the allied cities.",
    distractors:["The common people of the allied cities have no power, and their goodwill is of no use to Athens.", "The oligarchs in every city are the friends of Athens, and the people are her enemies.", "A punishment that falls on all alike makes every city more afraid to revolt."], src:"thuc_crawley", cite:"Thucydides 3.47, Diodotus", why:"Killing the people would “play directly into the hands of the higher classes,” who would then “have the people on their side.” The argument works only if the hearers grant that the people of the allied cities are what holds the empire to Athens."},
  {id:"e-cleon-delay", said:"For myself, I adhere to my former opinion, and wonder at those who have proposed to reopen the case of the Mitylenians, and who are thus causing a delay which is all in favour of the guilty, by making the sufferer proceed against the offender with the edge of his anger blunted…", missing:"A wrong is best requited while the anger it caused is still fresh.",
    distractors:["Delay favors the injured party.", "A wrong is judged most justly after the anger it caused has cooled.", "The guilty gain nothing from delay, since the penalty is already fixed by law."], src:"thuc_crawley", cite:"Thucydides 3.38, Cleon", why:"Cleon says that delay is “all in favour of the guilty,” because the sufferer comes to the offender “with the edge of his anger blunted.” The hearers must supply that a wrong is best answered while the anger is fresh, which Cleon goes on to say himself."},
  {id:"e-cleon-unprovoked", said:"I can make allowance for those who revolt because they cannot bear our empire, or who have been forced to do so by the enemy. But for those who possessed an island with fortifications; who could fear our enemies only by sea, and there had their own force of galleys to protect them; who were independent and held in the highest honour by you—to act as these have done, this is not revolt—revolt implies oppression; it is deliberate and wanton aggression…", missing:"A wrong done without provocation deserves a heavier punishment than one done under pressure.",
    distractors:["A city that rebels while it is strong is less to blame than one that rebels from weakness or want.", "Every revolt is the same offense, whatever the condition of the city that makes it.", "An independent ally may change sides at will, since it owes Athens nothing at all."], src:"thuc_crawley", cite:"Thucydides 3.39, Cleon", why:"He can “make allowance” for those who are oppressed or forced, but not for Mytilene, which was free and honored. The argument for a heavier sentence needs the premise that an unprovoked wrong deserves more punishment than one done under pressure."},
  {id:"e-cleon-fortune", said:"The truth is that great good fortune coming suddenly and unexpectedly tends to make a people insolent; in most cases it is safer for mankind to have success in reason than out of reason; and it is easier for them, one may say, to stave off adversity than to preserve prosperity.", missing:"The Mitylenians had enjoyed great and sudden good fortune, and so grew insolent.",
    distractors:["The Mitylenians had suffered long hardship under Athens, and revolted in despair.", "Prosperity makes a people cautious, so the Mitylenians revolted only from fear.", "Insolence is the fault of the poor, and never of a prosperous people."], src:"thuc_crawley", cite:"Thucydides 3.39, Cleon", why:"Cleon states the general rule, that sudden good fortune “tends to make a people insolent.” The rule says nothing about Mytilene until the hearers supply the particular premise: that the Mitylenians had such good fortune. Here the missing premise is the minor one, not the general one."},
  {id:"e-per-seamanship", said:"Familiarity with the sea they will not find an easy acquisition. If you who have been practising at it ever since the Median invasion have not yet brought it to perfection, is there any chance of anything considerable being effected by an agricultural, unseafaring population, who will besides be prevented from practising by the constant presence of strong squadrons of observation from Athens?", missing:"An art that long practice has not perfected cannot be learned quickly by those who have never practiced it.",
    distractors:["Seamanship is learned quickly by any people that has courage, a sound fleet, and money enough to pay its crews.", "Farmers make the best sailors, since their labor has hardened them.", "The Athenians have mastered the sea so fully that they no longer need to practice."], src:"thuc_crawley", cite:"Thucydides 1.142, Pericles", why:"If the Athenians, practicing “ever since the Median invasion,” have “not yet brought it to perfection,” the Peloponnesians will do worse. The argument is from the more to the less (Rhetoric II.23, 1397b), and it needs the premise that an art long practice has not perfected cannot be learned quickly by beginners."},
  // Added from Caesar in Sallust, Demosthenes, and Lincoln.
  {id:"e-caes-station", said:"If those who pass a life sunk in obscurity, commit any error, through excessive anger, few become aware of it, for their fame is as limited as their fortune; but of those who live invested with extensive power, and in an exalted station, the whole world knows the proceedings.", missing:"The senate holds the highest station in Rome, so whatever it does in anger will be known to all.",
    distractors:["The senate meets in private, and what it decrees there is known only to its own members and their friends.", "Men of great power are allowed more anger than the obscure, since their wrongs are greater.", "Anger is the same fault in every man."], src:"sallust_w", cite:"Sallust, Catiline 51, Caesar", why:"Caesar sets out the rule that the errors of the obscure go unnoticed, while “the whole world knows the proceedings” of the powerful. The rule bears on the debate only when the hearers supply the particular premise: that the senate is such a body, and its sentence will be watched by all."},
  {id:"e-caes-remember", said:"I am indeed of opinion, Conscript Fathers, that the utmost degree of torture is inadequate to punish their crime; but the generality of mankind dwell on that which happens last, and, in the case of malefactors, forget their guilt, and talk only of their punishment, should that punishment have been inordinately severe.", missing:"A punishment that men remember as too severe will turn opinion against those who inflicted it.",
    distractors:["A punishment is always remembered for the crime it answered, however severe it was or however long ago.", "The harsher the sentence, the longer men remember the guilt of the condemned.", "Opinion does not matter once the guilty are dead."], src:"sallust_w", cite:"Sallust, Catiline 51, Caesar", why:"Men “forget their guilt, and talk only of their punishment,” if it was “inordinately severe.” This tells against the death penalty only if the hearers grant that such remembered severity turns opinion against those who inflicted it."},
  {id:"e-caes-scourge", said:"But if scourging be a milder punishment than death, how is it consistent to observe the law as to the smaller point, when you disregard it as to the greater?", missing:"A law that must be kept in a lesser matter must be kept all the more in a greater one.",
    distractors:["A law that is kept in a lesser matter may be set aside in a greater one when the danger is greater.", "Scourging is a severer penalty than death, so the law rightly forbids it.", "The Porcian law concerns only scourging and says nothing at all about the penalty of death."], src:"sallust_w", cite:"Sallust, Catiline 51, Caesar", why:"Silanus would keep the law that forbids scourging but disregard the laws that protect a citizen’s life. Caesar’s question is an argument from the less to the more (Rhetoric II.23, 1397b), and it needs the premise that a law binding in the lesser matter binds still more in the greater."},
  {id:"e-caes-precedent", said:"All precedents productive of evil effects, have had their origin from what was good; but when a government passes into the hands of the ignorant or unprincipled, any new example of severity, inflicted on deserving and suitable objects, is extended to those that are improper and undeserving of it.", missing:"A power to put citizens to death without trial, once granted against the guilty, may later be turned by worse men against the innocent.",
    distractors:["A power granted against the guilty can never afterwards be used against the innocent, because the decree that grants it names its object.", "The present senate will hold power for ever, so no worse men will inherit its precedents.", "Severity against traitors makes a precedent that only good men will ever follow."], src:"sallust_w", cite:"Sallust, Catiline 51, Caesar", why:"Caesar says that every evil precedent began “from what was good,” and that a new severity is later “extended to those that are improper and undeserving of it.” The hearers must supply that the power they are asked to use now may pass to worse hands."},
  {id:"e-dem-fp-dare", said:"Now if in those days Philip had made up his mind that it was a hard thing to fight against the Athenians, with all their fortified outposts on his own frontiers, while he was destitute of allies, he would have achieved none of his recent successes, nor acquired this great power.", missing:"Athens, if she now dares as Philip then dared, may win back what he has taken from her.",
    distractors:["Philip succeeded only because the gods favored him, and no daring could have changed his fortune.", "Athens can never take back by force what she once lost.", "What Philip won against the odds he will keep, since his power is now too great to be resisted."], src:"demosth", cite:"Demosthenes, First Philippic 5 (Pickard)", why:"Philip would have gained nothing if he had thought it “a hard thing to fight against the Athenians.” The example becomes advice for Athens only if the hearers supply that the same daring will serve Athens now (Rhetoric II.20 on the example)."},
  {id:"e-dem-ol2-power", said:"It is impossible, men of Athens, utterly impossible, to acquire power that will last, by unrighteousness, by perjury, and by falsehood.", missing:"Philip has built his power by unrighteousness, by perjury, and by falsehood.",
    distractors:["Philip has built his power honestly, by keeping every treaty that he has sworn.", "Philip will grow stronger every year.", "Power gained by falsehood lasts longer than power gained honestly, because it is feared."], src:"demosth", cite:"Demosthenes, Second Olynthiac 10 (Pickard)", why:"Demosthenes states the general rule, that lasting power cannot be gained “by unrighteousness, by perjury, and by falsehood.” The conclusion, that Philip’s power will not last, follows only when the hearers supply the minor premise that Philip’s power was gained in that way."},
  {id:"e-dem-ol1-there", said:"If the resistance of Olynthus is maintained, you will fight there and will inflict damage on Philip's territory, while you remain secure in the enjoyment of this land of your own which you now possess.", missing:"A war fought in the enemy’s country is better for a city than a war fought in its own.",
    distractors:["A war fought at home is better, since the city can defend its own walls with its whole force.", "Philip never fights in Attica.", "Olynthus will hold out whether or not Athens sends help, so the choice does not matter."], src:"demosth", cite:"Demosthenes, First Olynthiac 25 (Pickard)", why:"If Olynthus holds, the Athenians “will fight there” while they “remain secure” at home. The reason to help Olynthus needs the premise that it is better to carry on a war in the enemy’s country than in one’s own."},
  {id:"e-dem-ph3-capture", said:"But you will not say this; for the man who is taking the steps and contriving the means which will lead to my capture is at war with me, even though he has not yet thrown a missile or shot an arrow.", missing:"Philip is taking the steps and preparing the means that will lead to the capture of Athens.",
    distractors:["Philip is keeping the peace, and has taken no step at all that threatens the safety or the freedom of Athens.", "A city is at war only when an enemy has thrown a missile at its walls.", "Athens is safe so long as the peace is kept on paper."], src:"demosth", cite:"Demosthenes, Third Philippic 17 (Pickard)", why:"Demosthenes gives the rule: whoever is “contriving the means which will lead to my capture is at war with me.” Philip is at war with Athens only if the hearers supply the minor premise, that Philip is doing just that."},
  {id:"e-lincoln-despotism", said:"When the white man governs himself, that is self-government; but when he governs himself and also governs another man, that is more than self-government,—that is despotism.", missing:"The slave is a man, and his master governs him without his consent.",
    distractors:["The slave is not a man in the sense of the Declaration, so his master’s rule is no despotism.", "Self-government belongs only to the states.", "A man who governs another with the law’s consent is not a despot, whatever the other wants."], src:"lincoln_ev", cite:"Abraham Lincoln, Reply to Douglas at Peoria (1854)", why:"Lincoln defines despotism as governing oneself “and also” governing “another man.” Slavery is despotism only when the hearers supply the premise that the slave is a man, which Lincoln states in the next sentence: “If the negro is a man.”"},
];
const PASSIONS = [
  {id:'p1', name:'anger', appetite:'irascible', text:'How much further, Catilina, will you carry your abuse of our forbearance?', cite:'Cicero, Catilinarian 1.1', src:'cic_cat', why:'Aristotle defines anger (II.2) as a desire, accompanied by pain, for conspicuous revenge, toward one who has slighted us.'},
  {id:'p2', name:'pity', appetite:'concupiscible', text:'My boy, struck in the side on the training field by a javelin thrown by this young man, died on the spot.', cite:'Antiphon 3.1.1', src:'antiphon', why:'Pity is pain at a destructive evil happening to one who does not deserve it (Aristotle II.8).'},
  {id:'p3', name:'fear', appetite:'irascible', text:'There are here, here among our fellow-senators… men who are meditating the destruction of us all, the total ruin of this city…', cite:'Cicero, Catilinarian 1.9', src:'cic_cat', why:'Fear is a pain due to imagining a future destructive evil (II.5).'},
  {id:'p4', name:'shame', appetite:'irascible', text:'Give me chastity and continency, only not yet.', cite:'Augustine, Confessions VIII (Pusey)', src:'aug_pusey', why:'Shame is pain about evils that seem to bring discredit (II.6), and here Augustine shows the divided will.'},
  {id:'p5', name:'indignation', appetite:'irascible', text:'Alas! what degenerate days are these! The senate is well aware of the facts… but the criminal still lives.', cite:'Cicero, Catilinarian 1.2', src:'cic_cat', why:'Indignation is pain at undeserved good fortune (II.9); here the good fortune is that of going unpunished.'},
  {id:'p6', name:'confidence', appetite:'irascible', text:'We throw open our city to the world, and never by alien acts exclude foreigners from any opportunity of learning or observing.', cite:'Thucydides 2.39, Pericles', src:'thuc_crawley', why:'Confidence is the opposite of fear: it is an imagination of safety (II.5).'},
  {id:'p7', name:'love', appetite:'concupiscible', text:'Too late loved I Thee, O Thou Beauty of ancient days, yet ever new!', cite:'Augustine, Confessions X (Pusey)', src:'aug_pusey', why:'Love is the motion toward a good taken as such, and the apostrophe here is pathos and prayer at once.'},
  {id:'p8', name:'kindness', appetite:'concupiscible', text:'My nature is for mutual love, not hate.', cite:'Sophocles, Antigone (Storr)', src:'soph_storr', why:'Kindness is here a settled wish for another’s good. Antigone names her ethos as a passion that has become character.'},
  {id:'p9', name:'hatred', appetite:'concupiscible', text:'To what destiny of mine, O conscript fathers, shall I say that it is owing, that none for the last twenty years has been an enemy to the republic without at the same time declaring war against me?', cite:'Cicero, Philippic 1', src:'cic_orat', why:'Hatred is a settled wish for another’s ill, without the pain of anger (II.4). Cicero makes the enemy of the republic his own.'},
  {id:'p10', name:'fear', appetite:'irascible', text:'Although I am afraid, gentlemen of the jury, that fear is an unseemly condition in which to begin a speech in defence of the bravest of men.', cite:'Cicero, Pro Milone 1', src:'cic_cat', why:'The advocate’s fear serves as the argument, since it shows that the danger is present and public (II.5).'},
  {id:'p11', name:'emulation', appetite:'irascible', text:'Athenian guest, much report of thee has come to us, both in regard to thy wisdom and thy wanderings… a desire has come upon me to ask thee whether thou hast seen any whom thou deemest to be the happiest.', cite:'Herodotus 1.30, Croesus to Solon', src:'herodotus', why:'Emulation is pain at seeing goods one might have (II.11); Croesus wants the name of happiest.'},
  {id:'p12', name:'pity', appetite:'concupiscible', text:'My children, latest born to Cadmus old, Why sit ye here as suppliants, in your hands Branches of olive filleted with wool?', cite:'Sophocles, Oedipus Tyrannus (Storr)', src:'soph_storr', why:'The city is shown as children and the plague as undeserved evil, so the king is moved to pity before he is moved to inquiry (II.8).'},
  {id:'p13', name:'anger', appetite:'irascible', text:'When I reflect on the causes of the war, and the circumstances of our situation, I feel a strong persuasion that our united efforts on the present day will prove the beginning of universal liberty to Britain.', cite:'Tacitus, Agricola 30, Calgacus (Oxford)', src:'tacitus_brooks', why:'This is anger at a slight to a free people, joined with the hope of revenge (II.2).'},
  {id:'p14', name:'love', appetite:'concupiscible', text:'But what do I love, when I love Thee? not beauty of bodies, nor the fair harmony of time, nor the brightness of the light.', cite:'Augustine, Confessions X (Pusey)', src:'aug_pusey', why:'This is love seeking its object by denying lesser goods (II.4; Aquinas I–II on the concupiscible).'},
  {id:'p15', name:'confidence', appetite:'irascible', text:'If your courage and fidelity had not been sufficiently proved by me, this favorable opportunity would have occurred to no purpose; mighty hopes, absolute power, would in vain be within our grasp.', cite:'Sallust, Catiline 20', src:'sallust_w', why:'This is confidence as an imagination of safety and of goods within reach (II.5), and here it is a conspirator’s confidence.'},
  {id:'p16', name:'shame', appetite:'irascible', text:'How you, O Athenians, have been affected by my accusers, I cannot tell; but I know that they almost made me forget who I was—so persuasively did they speak; and yet they have hardly uttered a word of truth.', cite:'Plato, Apology (Jowett)', src:'plato_jowett', why:'Socrates would have the jury feel the shame of being moved by a lie (II.6).'},
  {id:'p17', name:'indignation', appetite:'irascible', text:'I think the two things most opposed to good counsel are haste and passion.', cite:'Thucydides 3.42, Diodotus', src:'thuc_crawley', why:'Diodotus would have the assembly feel indignation at being rushed, not only pity for Mytilene (II.9).'},
  {id:'p18', name:'kindness', appetite:'concupiscible', text:'The ruler should be a near neighbour to every one in sympathy, and exalted above all in contemplation, so that through the bowels of loving-kindness he may transfer the infirmities of others to himself.', cite:'Gregory, Pastoral Care II (Barmby)', src:'greg', why:'This is kindness as wishing another’s good and taking his ills as one’s own (II.7).'},
  // English tradition (public-domain quotations; sources eng_cer, eng_cem, kjv).
  {id:'eng-p1', name:'shame', appetite:'irascible', text:'I can not forgive you, my brethren, who till this late hour have been silent while successive murders were committed.', cite:'Eliphalet Nott, Sermon at Albany (1804)', src:'eng_cer', why:'Shame is pain about evils that seem to bring discredit (II.6), and the preacher charges his own hearers with silence while men were killed.'},
  {id:'eng-p2', name:'pity', appetite:'concupiscible', text:'Bear with me, My heart is in the coffin there with Caesar, And I must pause till it come back to me.', cite:'Shakespeare, Julius Caesar 3.2', src:'eng_cer', prompt:'Antony pauses over Caesar’s body and shows the crowd his own grief. Which passion is he moving in the crowd toward Caesar?', why:'Pity is pain at a destructive evil that has fallen on one who did not deserve it (II.8). The grief is Antony’s own, but Aristotle notes that those who heighten an evil by gesture, voice, and bearing make it more pitiable, because they set it before our eyes; so Antony’s pause is the means, and the passion moved in the crowd is pity for Caesar, whose death the speech goes on to show was undeserved.'},
  {id:'eng-p3', name:'fear', appetite:'irascible', text:'A democracy is a volcano, which conceals the fiery materials of its own destruction.', cite:'Fisher Ames, Speech at the Massachusetts Ratifying Convention (1788)', src:'eng_cem', why:'Fear is pain at the imagined approach of a destructive evil (II.5), and the volcano puts that evil beneath the hearers’ feet.'},
  {id:'eng-p4', name:'anger', appetite:'irascible', text:'Can there be a more mortifying insult? Can even our ministers sustain a more humiliating disgrace? Do they dare to resent it?', cite:'William Pitt (the Elder), Speech in the House of Lords (1777)', src:'eng_cer', prompt:'Chatham speaks of the welcome France has given the American commissioners, an insult to Britain that the ministers have let pass. Which passion is he moving in the Lords, toward France and toward the ministers?', why:'Aristotle defines anger (II.2) as a desire, accompanied by pain, for revenge for a conspicuous slight directed without justification toward what concerns oneself or one’s friends. Chatham extends the slight from the person to the State, whose honor the Lords count as their own; and the disgrace is not presented as their own fault, which would move shame (II.6), but as an insult from France that the ministers have not dared to resent.'},
  {id:'eng-p5', name:'confidence', appetite:'irascible', text:'In my Father’s house are many mansions: if it were not so, I would have told you. I go to prepare a place for you.', cite:'John 14:2 (King James Version)', src:'kjv', prompt:'Christ is speaking to disciples who are troubled at his going away (“Let not your heart be troubled,” 14:1). Which passion is he moving in them?', why:'Aristotle defines confidence (II.5) as the opposite of fear, that is, the expectation that what keeps us safe is near and what is terrible is far off. He has in view dangers such as war or a lawsuit, so this is an extension of his account; but the disciples’ trouble is a fear of loss at their master’s going, and the promise of a place prepared sets the good near and takes the fear away.'},
  {id:"p-cic-execute", name:"anger", appetite:"irascible", text:"No, Catilina, long ere now you should yourself have been led by the consul's orders to execution; and on your own head should have been brought down the destruction which you are now devising for us.", cite:"Cicero, First Catilinarian 1.2", src:"cic_cat", prompt:"Cicero is speaking to Catiline in the senate’s hearing. Which passion toward Catiline is he stirring in the senate?", why:"The wish is that he “should yourself have been led by the consul's orders to execution”, and that “the destruction which you are now devising for us” be brought down “on your own head”. Anger, in Aristotle II.2, is pain joined to a desire for a conspicuous revenge upon the man who has slighted us."},
  {id:"p-plat-quarter", name:"pity", appetite:"concupiscible", text:"To grant us our lives would be, therefore, a righteous judgment; if you consider also that we are prisoners who surrendered of their own accord, stretching out our hands for quarter, whose slaughter Hellenic law forbids, and who besides were always your benefactors.", cite:"Thucydides 3.58, Plataea", src:"thuc_crawley", prompt:"The Plataeans are speaking to the Spartan judges, who have their lives in hand. Which passion toward the prisoners is this picture meant to move?", why:"They are “prisoners who surrendered of their own accord, stretching out our hands for quarter, whose slaughter Hellenic law forbids”, and they were “always your benefactors”. Pity, in Aristotle II.8, is pain at a destructive evil that is about to fall on people who have not deserved it."},
  {id:"p-cic-mass", name:"fear", appetite:"irascible", text:"They contemplate nothing short of massacre and conflagration and pillage.", cite:"Cicero, Second Catilinarian 2.5", src:"cic_cat", prompt:"Cicero is describing the men Catiline has left in the city, and he is speaking to the people. Which passion is he moving in them?", why:"What he sets before the citizens is “massacre and conflagration and pillage”, a destructive evil still to come. Fear, in Aristotle II.5, is pain at the imagination of such an evil."},
  {id:"p-cato-life", name:"fear", appetite:"irascible", text:"We are not now debating on the revenues, or on injuries done to our allies, but our liberty and our life is at stake.", cite:"Sallust, Catiline 52, Cato", src:"sallust_w", prompt:"Cato is addressing the senate on the fate of the prisoners. Which passion is he moving in them about their own case?", why:"He puts before the senate an evil still ahead: “our liberty and our life is at stake.” Fear, in Aristotle II.5, is the pain of imagining a destructive evil of that kind."},
  {id:"p-cic-brave", name:"shame", appetite:"irascible", text:"And we, such is our bravery, think we are doing our duty to our country, if we merely keep ourselves out of the way of his reckless words and bloody deeds.", cite:"Cicero, First Catilinarian 1.2", src:"cic_cat", prompt:"Cicero turns from Catiline to the senate’s own conduct. Which passion is he moving in the senators about themselves?", why:"He calls it “our bravery” that “we merely keep ourselves out of the way of his reckless words and bloody deeds”, and he says they think this is “doing our duty”, but he is not praising them. Shame, in Aristotle II.6, is pain at conduct that brings discredit, and the conduct here is the senate’s shrinking."},
  {id:"p-cato-names-p", name:"indignation", appetite:"irascible", text:"For some time past, it is true, we have lost the real name of things; for to lavish the property of others is called generosity, and audacity in wickedness is called heroism; and hence the state is reduced to the brink of ruin.", cite:"Sallust, Catiline 52, Cato", src:"sallust_w", prompt:"Cato is telling the senate how the city now speaks of wickedness. Which passion is he moving in them toward that misuse of names?", why:"Vice is wearing the fortunate name of a virtue: “to lavish the property of others is called generosity, and audacity in wickedness is called heroism”. Indignation, in Aristotle II.9, is pain at good fortune that is not deserved, and a good name for a bad act is that fortune."},
  {id:"p-cic-popular", name:"indignation", appetite:"irascible", text:"Moreover he certainly does not think that this Lentulus, however extravagant in his bribes, having entertained so cruel and barbarous a design for the ruin of the Roman people and the destruction of this city, can possibly be called a popular leader.", cite:"Cicero, Fourth Catilinarian 4.5", src:"cic_cat", prompt:"Cicero is speaking of Lentulus in the senate. Which passion toward the idea of calling him a popular leader is the sentence moving?", why:"A man who has “entertained so cruel and barbarous a design for the ruin of the Roman people” cannot “be called a popular leader”. The good name would be good fortune he has not deserved. Indignation, in Aristotle II.9, is pain at that sort of fortune."},
  {id:"p-cic-gates", name:"confidence", appetite:"irascible", text:"There are no sentries at the gates, there are no men in ambush on the road; if any one wishes to depart, I need not see him go.", cite:"Cicero, Second Catilinarian 2.12", src:"cic_cat", prompt:"Cicero is telling the people how a conspirator may leave the city. Which passion about the city’s safety is he moving?", why:"“There are no sentries at the gates, there are no men in ambush on the road”, and if a man “wishes to depart”, the consul “need not see him go”. Confidence, in Aristotle II.5, is the imagination that what keeps us safe is at hand and that the terrible thing need not be guarded against at every door."},
  {id:"p-per-suffer", name:"love", appetite:"concupiscible", text:"Such is the Athens for which these men, in the assertion of their resolve not to lose her, nobly fought and died; and well may every one of their survivors be ready to suffer in her cause.", cite:"Thucydides 2.43, Pericles", src:"thuc_crawley", prompt:"Pericles has just described the city. Which passion toward that city is he moving in the survivors?", why:"The dead “nobly fought and died” for this Athens, “their resolve not to lose her”, and “every one of their survivors” is to “be ready to suffer in her cause”. Love, as Aristotle treats the concupiscible motion toward a good, is here the city’s good held so dear that one will suffer for it."},
  {id:"p-matt-give", name:"kindness", appetite:"concupiscible", text:"Heal the sick, cleanse the lepers, raise the dead, cast out devils: freely ye have received, freely give.", cite:"Matthew 10:8 (King James Version)", src:"kjv", prompt:"Christ is sending out the twelve. Which passion is he moving in them toward the people they will meet?", why:"The twelve are sent to “the sick”, “the lepers”, the dead, and those with “devils”, and they are to “freely give” what they have “freely” received. Kindness, in Aristotle II.7, is a service to someone in need, and the word “freely” marks it as not a return of a debt."},
  {id:"p-cori-ships", name:"kindness", appetite:"concupiscible", text:"When you were in want of ships of war for the war against the Aeginetans, before the Persian invasion, Corinth supplied you with twenty vessels.", cite:"Thucydides 1.41, Corinth", src:"thuc_crawley", prompt:"Corinth is reminding Athens of a past service. Which passion toward Corinth is that reminder meant to move?", why:"Athens was “in want of ships of war”, and “Corinth supplied you with twenty vessels”. Kindness, in Aristotle II.7, is a service done to someone in need, and the reminder is meant to wake the goodwill that such a service leaves behind."},
  {id:"p-cic-enemy", name:"hatred", appetite:"concupiscible", text:"Merely to depart from the city this is the sole order given by the consul to a public enemy.", cite:"Cicero, First Catilinarian 1.13", src:"cic_cat", prompt:"Cicero states the order he has given Catiline, and he wants the senate to stand in it with him. Which passion toward Catiline does the order ask them to share?", why:"The order to depart is given “to a public enemy”, and it is called “the sole order”. Hatred, in Aristotle II.4, is a settled wish for another’s ill, and it does not wait on a fresh slight. The name “public enemy” is that settled wish, and the ill is that he go."},
  {id:"p-per-sons", name:"emulation", appetite:"irascible", text:"Turning to the sons or brothers of the dead, I see an arduous struggle before you. When a man is gone, all are wont to praise him, and should your merit be ever so transcendent, you will still find it difficult not merely to overtake, but even to approach their renown.", cite:"Thucydides 2.45, Pericles", src:"thuc_crawley", prompt:"Pericles turns to the sons and brothers of the dead. Which passion is he moving in them?", why:"He sets “an arduous struggle” before “the sons or brothers of the dead”: “should your merit be ever so transcendent, you will still find it difficult not merely to overtake, but even to approach their renown.” Emulation, in Aristotle II.11, is pain at the absence of goods we might still gain, when we see those goods in people like ourselves."},
  // Added from Lysias, Thucydides, Plato, Demosthenes, Lincoln, and the Douay-Rheims Bible; the passions are those of Rhetoric II.2–11.
  {id:"p-lys-corn", name:"hatred", appetite:"concupiscible", text:"For their interests are the opposite of other men's: they make most profit when, on some bad news reaching the city, they sell their corn at a high price. And they are so delighted to see your disasters that they either get news of them in advance of anyone else, or fabricate the rumor themselves; now it is the loss of your ships in the Black Sea, now the capture of vessels on their outward voyage by the Lacedaemonians, now the blockade of your trading ports, or the impending rupture of the truce; and they have carried their enmity to such lengths that they choose the same critical moments as your foes to overreach you.", cite:"Lysias, Against the Corn-Dealers 22.14 (Lamb)", src:"lysias_lamb", prompt:"The speaker describes the corn-dealers, as a class, to the jury. Which passion toward them is he moving?", why:"He says that their interests “are the opposite of other men’s” and that they are “delighted to see your disasters.” Aristotle says that anger is felt toward individuals, while hatred is felt also toward a whole class, and that hatred wishes the other’s ruin and not merely his pain (II.4, 1382a). Here the jury is set against the dealers as a class."},
  {id:"p-per-model", name:"emulation", appetite:"irascible", text:"These take as your model and, judging happiness to be the fruit of freedom and freedom of valour, never decline the dangers of war.", cite:"Thucydides 2.43, Pericles", src:"thuc_crawley", prompt:"Pericles has praised the dead and turns to the citizens who survive them. Which passion is he moving in them toward the dead?", why:"He sets the dead before the living as their “model.” Emulation, in Aristotle II.11, is pain at the absence of goods that we see in others like ourselves, and it moves us to try to gain those goods for ourselves."},
  {id:"p-menex-exceed", name:"emulation", appetite:"irascible", text:"And all knowledge, when separated from justice and virtue, is seen to be cunning and not wisdom; wherefore make this your first and last and constant and all-absorbing aim, to exceed, if possible, not only us but all your ancestors in virtue; and know that to excel you in virtue only brings us shame, but that to be excelled by you is a source of happiness to us.", cite:"Plato, Menexenus 246e–247a (Jowett)", src:"plato_jowett", prompt:"In the funeral speech the dead are made to speak to their sons. Which passion are they moving in the sons?", why:"The fathers ask the sons “to exceed, if possible, not only us but all your ancestors in virtue.” Emulation, in Aristotle II.11, is the pain that moves us to gain goods we see in others like us, and Aristotle notes that those whose ancestors or kinsmen are honored are especially given to it (1388b)."},
  {id:"p-lincoln-friends", name:"love", appetite:"concupiscible", text:"I am loath to close. We are not enemies, but friends. We must not be enemies. Though passion may have strained, it must not break our bonds of affection.", cite:"Abraham Lincoln, First Inaugural Address (1861)", src:"lincoln_ev", prompt:"Lincoln closes his first inaugural address to a country in which several states have already seceded. Which passion is he moving in those states toward the Union?", why:"He tells them “We are not enemies, but friends,” and speaks of “our bonds of affection.” Love, in Aristotle II.4, is wishing for another what we think good, for his sake, and Lincoln names the friendship that he wants them to feel again."},
  {id:"p-john-love", name:"love", appetite:"concupiscible", text:"This is my commandment, that you love one another, as I have loved you. Greater love than this no man hath, that a man lay down his life for his friends.", cite:"John 15:12–13 (Douay-Rheims)", src:"douay", prompt:"Christ is speaking to his disciples on the night before his death. Which passion is he moving in them toward one another?", why:"He commands them to “love one another,” and gives the measure of it: “that a man lay down his life for his friends.” Love, in Aristotle II.4, is wishing another’s good for his sake, and doing it as far as we can."},
  {id:"p-cleon-payback", name:"anger", appetite:"irascible", text:"Do not, therefore, be traitors to yourselves, but recall as nearly as possible the moment of suffering and the supreme importance which you then attached to their reduction; and now pay them back in their turn, without yielding to present weakness or forgetting the peril that once hung over you.", cite:"Thucydides 3.40, Cleon", src:"thuc_crawley", prompt:"Cleon is speaking to the Athenian assembly about the Mytilenians, who revolted. Which passion toward them is he moving?", why:"He asks the assembly to recall “the moment of suffering” and to “pay them back in their turn.” Anger, in Aristotle II.2, is a desire, accompanied by pain, for revenge on those who have slighted us, so Cleon renews the slight in order that the desire for revenge may return."},
  {id:"p-dem-news", name:"shame", appetite:"irascible", text:"Surely the strongest necessity that a free people can experience is the shame which they must feel at their position! What? Do you want to go round asking one another, 'Is there any news?' Could there be any stranger news than that a man of Macedonia is defeating Athenians in war, and ordering the affairs of the Hellenes?", cite:"Demosthenes, First Philippic 10 (Pickard)", src:"demosth", prompt:"Demosthenes is rebuking the Athenian assembly for its delay against Philip. Which passion is he moving in them about their own conduct?", why:"He names it himself: “the shame which they must feel at their position.” Shame, in Aristotle II.6, is pain at evils that seem to bring discredit, and the discredit here is that Athenians are being defeated by “a man of Macedonia.”"},
  {id:"p-bras-numbers", name:"confidence", appetite:"irascible", text:"The bravery that you habitually display in war does not depend on your having allies at your side in this or that encounter, but on your native courage; nor have numbers any terrors for citizens of states like yours, in which the many do not rule the few, but rather the few the many, owing their position to nothing else than to superiority in the field.", cite:"Thucydides 4.126, Brasidas", src:"thuc_crawley", prompt:"Brasidas is speaking to his soldiers, whose allies have deserted them in the face of a large barbarian army. Which passion is he moving in them?", why:"He tells them that “numbers” have no “terrors” for men like them. Confidence, in Aristotle II.5, is the opposite of fear, that is, the expectation that what keeps us safe is near and that what is terrible is far off or weak."},
  {id:"p-plat-tombs", name:"pity", appetite:"concupiscible", text:"We, as we have a right to do and as our need impels us, entreat you, calling aloud upon the gods at whose common altar all the Hellenes worship, to hear our request, to be not unmindful of the oaths which your fathers swore, and which we now plead—we supplicate you by the tombs of your fathers, and appeal to those that are gone to save us from falling into the hands of the Thebans and their dearest friends from being given up to their most detested foes.", cite:"Thucydides 3.59, Plataea", src:"thuc_crawley", prompt:"The Plataeans are pleading with the Spartan judges for their lives. Which passion toward themselves are they moving?", why:"They supplicate “by the tombs of your fathers” and ask not to be given up “to their most detested foes.” Pity, in Aristotle II.8, is pain at a destructive evil about to fall on those who do not deserve it, and it is strongest when the sufferers are near to us, as the Plataeans were to the Spartans’ fathers."},
  {id:"p-dem-risen", name:"indignation", appetite:"irascible", text:"Look then at the men whose policy gives you these things. Some of them who were poor have become rich; others, who were unknown to fame, have risen to honour; some of them have provided themselves with private houses more imposing than our public buildings; and the lower the fortunes of the city have fallen, the higher theirs have risen.", cite:"Demosthenes, Third Olynthiac 29 (Pickard)", src:"demosth", prompt:"Demosthenes is speaking to the assembly about the politicians who have managed the city in recent years. Which passion toward them is he moving?", why:"Some “who were poor have become rich,” and “the lower the fortunes of the city have fallen, the higher theirs have risen.” Indignation, in Aristotle II.9, is pain at good fortune that is not deserved, and Demosthenes sets the politicians’ rise against the city’s fall."},
  {id:"p-dem-frontier", name:"fear", appetite:"irascible", text:"Only consider what would happen, if Philip got such an opportunity to strike at us, and there was war on our frontier. Can you not imagine how readily he would march against us?", cite:"Demosthenes, First Olynthiac 24 (Pickard)", src:"demosth", prompt:"Demosthenes is urging the assembly to act while Philip is in difficulty. Which passion is he moving in them with these two sentences?", why:"He asks them to picture “war on our frontier” and how readily Philip “would march against us.” Fear, in Aristotle II.5, is pain at the imagination of a destructive evil that is near."},
  {id:"p-dem-phocis", name:"pity", appetite:"concupiscible", text:"For when recently we were on our way to Delphi we could not help seeing it all—houses razed to the ground, cities stripped of their walls, the land destitute of men in their prime—only a few poor women and little children left, and some old men in misery. Indeed, no words can describe the distress now prevailing there.", cite:"Demosthenes, On the Embassy 65 (Pickard)", src:"demosth", prompt:"Demosthenes is describing to the jury what the Phocians suffered after the peace. Which passion toward the Phocians is he moving?", why:"He sets before the jury “houses razed to the ground” and “only a few poor women and little children left, and some old men in misery.” Pity, in Aristotle II.8, is pain at a destructive evil that has fallen on those who did not deserve it, and Aristotle says that evils set before the eyes are the most pitiable."},
  {id:"p-lys-thirty", name:"kindness", appetite:"concupiscible", text:"Now, when the townsmen had assembled together before their setting out, as I knew that some among them, though true and ardent patriots, lacked means for expenses of service, I said that the well-to-do ought to provide what was necessary for those in needy circumstances. Not only did I recommend this to the others, but I myself gave thirty drachmae each to two men; not as being a person of great possessions, but to set a good example to the others.", cite:"Lysias, In Defence of Mantitheus 16.14 (Lamb)", src:"lysias_lamb", prompt:"Mantitheus tells the Council what he did for the poorer men of his township when they were called up for service. Which passion toward him is the account meant to move?", why:"He gave “thirty drachmae each to two men” who “lacked means for expenses of service.” Kindness, in Aristotle II.7, is a service done to someone in need, not for any return, and the greater the need, the greater the kindness."},
  {id:"p-nic-hope", name:"confidence", appetite:"irascible", text:"Athenians and allies, even in our present position we must still hope on, since men have ere now been saved from worse straits than this; and you must not condemn yourselves too severely either because of your disasters or because of your present unmerited sufferings.", cite:"Thucydides 7.77, Nicias", src:"thuc_crawley", prompt:"Nicias is speaking to the defeated Athenian army as it begins its retreat from Syracuse. Which passion is he moving in them?", why:"He tells them that “we must still hope on, since men have ere now been saved from worse straits than this.” Confidence, in Aristotle II.5, is the expectation that what keeps us safe is near, and one of its sources is knowing that others have come through the same dangers."},
  {id:"p-burke-affection", name:"love", appetite:"concupiscible", text:"My hold of the Colonies is in the close affection which grows from common names, from kindred blood, from similar privileges, and equal protection. These are ties which, though light as air, are as strong as links of iron.", cite:"Edmund Burke, Speech on Conciliation with the Colonies (1775)", src:"burke_n", prompt:"Burke is urging the House of Commons to hold the American colonies by conciliation rather than by force. Which passion between Britain and the colonies is he moving?", why:"He places his “hold of the Colonies” in “the close affection which grows from common names, from kindred blood, from similar privileges, and equal protection.” Love, in Aristotle II.4, is wishing another’s good for his sake, and Aristotle notes that we love those who share our ways and who are like us (1381a)."},
  {id:"p-lam-sorrow", name:"pity", appetite:"concupiscible", text:"O all ye that pass by the way, attend, and see if there be any sorrow like to my sorrow: for he hath made a vintage of me, as the Lord spoke in the day of his fierce anger.", cite:"Lamentations 1:12 (Douay-Rheims)", src:"douay", prompt:"Jerusalem, destroyed, is made to speak to those who pass by. Which passion toward the city is the lament moving?", why:"The city asks the passers-by to “see if there be any sorrow like to my sorrow.” Pity, in Aristotle II.8, is pain at a destructive evil that has fallen on another, and Aristotle says that it is strongest when the suffering is set before our eyes (1386a)."},
  {id:"p-cor-shame", name:"shame", appetite:"irascible", text:"I speak to your shame. Is it so that there is not among you any one wise man that is able to judge between his brethren?", cite:"1 Corinthians 6:5 (Douay-Rheims)", src:"douay", prompt:"Paul is writing to Christians at Corinth who take their disputes with one another before pagan courts. Which passion is he moving in them?", why:"He says plainly, “I speak to your shame,” and asks whether there is not one wise man among them to judge between brethren. Shame, in Aristotle II.6, is pain at evils that bring discredit, and it is felt most before those whose opinion we respect."},
  {id:"p-matt-sparrows", name:"confidence", appetite:"irascible", text:"Are not two sparrows sold for a farthing? and not one of them shall fall on the ground without your Father. But the very hairs of your head are all numbered. Fear not therefore: better are you than many sparrows.", cite:"Matthew 10:29–31 (Douay-Rheims)", src:"douay", prompt:"Christ is sending out the twelve, and has just warned them of persecution. Which passion is he moving in them?", why:"Not one sparrow falls “without your Father,” and “better are you than many sparrows.” Confidence, in Aristotle II.5, is the expectation that what keeps us safe is near and what is terrible is far off, and one of its grounds is that the gods are on our side."},
  {id:"p-heb-witnesses", name:"emulation", appetite:"irascible", text:"And therefore we also having so great a cloud of witnesses over our head, laying aside every weight and sin which surrounds us, let us run by patience to the fight proposed to us: Looking on Jesus, the author and finisher of faith, who, having joy set before him, endured the cross, despising the shame, and now sitteth on the right hand of the throne of God.", cite:"Hebrews 12:1–2 (Douay-Rheims)", src:"douay", prompt:"The letter has just recounted the faith of Abel, Abraham, Moses, and the other witnesses of the old law. Which passion is it moving in its readers?", why:"With “so great a cloud of witnesses over our head,” the readers are to “run by patience to the fight proposed to us,” looking to Christ. Emulation, in Aristotle II.11, is the pain that moves us to gain goods that we see in others like ourselves, and it makes us try to become like them."},
];
const DEBATES = [
  {id:'d-arch', title:'War with Athens', a:{who:'Archidamus', pid:'thuc-arch-1', claim:'Do not rush to war; experience teaches its cost.', wrong:'Never fight Athens; let the allies fend for themselves.'}, b:{who:'Sthenelaidas', pid:'thuc-sthen-1', claim:'Vote the war; the Athenians are in the wrong.', wrong:'Vote the war; plunder will pay its cost.'}, species:'deliberative', src:'thuc_crawley', locus:'Thucydides 1.80 / 1.86'},
  {id:'d-myt', title:'Mytilene', a:{who:'Cleon', pid:'thuc-cleon-1', claim:'A democracy that talks cannot hold empire; do not reopen the sentence.', wrong:'Athens should let Mytilene go, since it is strong enough by sea that the loss does not matter.'}, b:{who:'Diodotus', pid:'thuc-diod-1', claim:'The assembly was right to reopen the case, and it should now decide it without haste or passion.', wrong:'The assembly should decide at once, while its anger is fresh, so that the punishment is not weakened.'}, species:'deliberative', src:'thuc_crawley', locus:'Thucydides 3.37 / 3.42'},
  {id:'d-fun', title:'Pericles’ funeral oration', a:{who:'Pericles (the custom)', pid:'thuc-fun-1', claim:'I shall speak of the city, not only of the men.', wrong:'I shall praise the dead alone, not the city.'}, b:{who:'Pericles (the city)', pid:'thuc-fun-2', claim:'Our constitution does not copy our neighbors; we are an example.', wrong:'Our constitution favors the few, and class decides who advances in public life.'}, species:'epideictic', src:'thuc_crawley', locus:'Thucydides 2.35 / 2.37'},
  {id:'d-cat', title:'The Catilinarian conspirators', a:{who:'Catiline', pid:'sal-cat-consp', claim:'The conspirators should go forward now, since the opportunity is at hand and their courage is proved.', wrong:'The conspirators should wait for a surer time before they act at all.'}, b:{who:'Caesar', pid:'sal-caes-1', claim:'Inflict only such penalties as the laws have provided.', wrong:'Put the conspirators to death; the danger allows no delay.'}, species:'deliberative', src:'sallust_w', locus:'Sallust, Catiline 20 / 51'},
  {id:'d-ant', title:'The javelin', a:{who:'The father (prosecution)', pid:'ant-3.1.1', claim:'The jurors should convict the young man of unintentional homicide, since he caused the death.', wrong:'The jurors should convict the young man of intentional homicide, since he meant to kill.'}, b:{who:'The thrower’s father (defense)', pid:'ant-3.2.1', claim:'The jurors should acquit the young man, since the boy who ran out caused his own death.', wrong:'The jurors should pardon the young man, since his father admits that his son’s aim was bad.'}, species:'forensic', src:'antiphon', locus:'Antiphon 3.1 / 3.2'},
  {id:'d-sic', title:'The Sicilian expedition', a:{who:'Nicias', pid:'thuc-nic-sicily', claim:'Athens should ask again whether to sail at all, and not be drawn into a war that is not its own.', wrong:'Athens should sail to Sicily at once, because the Segestans have shown that they can pay for the whole war.'}, b:{who:'Alcibiades', pid:'thuc-alc-1', claim:'Athens should give Alcibiades the command, since his display has brought the city fame and profit.', wrong:'Athens should give Alcibiades the command, since he is the oldest and most experienced of the generals.'}, species:'deliberative', src:'thuc_crawley', locus:'Thucydides 6.9 / 6.16'},
  {id:'d-corc', title:'Corcyra and Corinth at Athens', a:{who:'The Corcyraeans', pid:'thuc-corc', claim:'Athens should receive Corcyra, so that its fleet is not joined to the fleet of Corinth.', wrong:'Athens should receive Corcyra, because Corcyra has always been a loyal ally of Athens.'}, b:{who:'The Corinthians', pid:'thuc-cor-neutral', claim:'Athens cannot ally with Corcyra and remain the friend of Corinth, so it should stay neutral.', wrong:'Athens should settle the quarrel itself as judge, since both cities have asked it to arbitrate between them.'}, species:'deliberative', src:'thuc_crawley', locus:'Thucydides 1.36 / 1.40'},
  {id:'d-plat', title:'Plataea before the Spartan judges', a:{who:'The Plataeans', pid:'thuc-plat-compassion', claim:'The judges should spare the Plataeans and yield to a reasonable compassion.', wrong:'The judges should spare Plataea, since it never fought against Sparta.'}, b:{who:'The Thebans', pid:'thuc-theb-vindicate', claim:'The judges should condemn the Plataeans and so uphold the Hellenic law that they broke.', wrong:'The judges should spare the Plataeans, since the Thebans have forgiven their old wrongs.'}, species:'forensic', src:'thuc_crawley', locus:'Thucydides 3.59 / 3.67'},
  {id:'d-cato', title:'The punishment of the conspirators', a:{who:'Caesar', pid:'sal-caes-passion', claim:'The senate should decide on the conspirators without hatred, affection, anger, or pity.', wrong:'The senate should let the conspirators go free, since none of their plots has yet taken effect.'}, b:{who:'Cato', pid:'sal-cato-feelings', claim:'The senate should secure the city against the conspirators, not only weigh their sentence.', wrong:'The senate should pardon the conspirators and so show its mercy.'}, species:'deliberative', src:'sallust_w', locus:'Sallust, Catiline 51 / 52'},
  {id:'d-cam', title:'Camarina between Syracuse and Athens', a:{who:'Hermocrates', pid:'thuc-herm-camarina', claim:'Camarina should side with Syracuse, since Athens has come not to restore the Leontines but to drive out the Syracusans.', wrong:'Camarina should side with Athens, since Athens has come to help Syracuse against the cities that threaten it.'}, b:{who:'Euphemus', pid:'thuc-euph-fear', claim:'Camarina should trust Athens, since Athens has come out of fear for its safety, to keep the cities from being enslaved.', wrong:'Camarina should trust Athens, since the oracle at Delphi commanded the Athenians to send out the fleet.'}, species:'deliberative', src:'thuc_crawley', locus:'Thucydides 6.76 / 6.83'}
];
const STASIS_ITEMS = [
  {id:"st-inn", status:"fact", text:"But the man with whose sword the murder had been committed, rose long before dawn and called over and over again on his companion; he thought that he did not answer because he was overcome with sleep; and so he took his sword and the rest of the things which he had with him, and departed on his journey alone. The innkeeper not long afterwards raised an outcry that the man was murdered, and in company with some of his lodgers pursued the man who had gone away. They arrest him on his journey, draw his sword out of its sheath, and find it bloody, the man is brought back to the city by them, and put on his trial. On this comes the allegation of the crime, \"You murdered him,\" and the denial, \"I did not murder him,\"…", src:"cic_inv", cite:"Cicero, De inventione II.4 (Yonge)", why:"The accused answers, “I did not murder him,” so he denies the deed itself. Cicero gives this case as his example of the conjectural statement (De inventione II.4), in which the dispute is about the fact, and the question for the judges is whether he murdered the man or not."},
  {id:"st-times", status:"fact", text:"For as to what has been done, an inquiry can be instituted in this way—\"whether Ulysses slew Ajax;\" and as to what is being done, in this way—\"whether the people of Tregellae are well affected towards the Roman people;\" and as to what is going to happen, in this way—\"if we leave Carthage uninjured, whether any inconvenience will accrue to the republic.\"", src:"cic_inv", cite:"Cicero, De inventione I.8 (Yonge)", why:"Each question asks whether something is so: whether Ulysses killed Ajax, whether the people of Tregellae are loyal now, and whether harm will follow if Carthage is spared. Cicero gives these three as disputes about fact, and he says that such a dispute “may be distributed over every sort of time” (De inventione I.8)."},
  {id:"st-decius", status:"fact", cue:"Cicero gives this as the question in a case about money that Decius is said to have taken.", text:"\"Whether Decius has received the money;\"", src:"cic_part", cite:"Cicero, Partitiones oratoriae 30 (Yonge)", why:"The question is whether Decius received the money at all, so the dispute is about the fact. Cicero gives this question as his example of conjecture in the Partitions (chapter 30)."},
  {id:"st-flaminius", status:"definition", text:"Caius Flaminius, who as consul met with great disasters in the second Punic war, when he was tribune of the people, proposed, in a very seditious manner, an agrarian law to the people, against the consent of the senate, and altogether against the will of all the nobles. While he was holding an assembly of the people, his own father dragged him from the temple. He is impeached of treason. The charge is—\"You attacked the majesty of the people in dragging down a tribune of the people from the temple.\" The denial is—\"I did not attack the majesty of the people.\" The question is—\"Whether he attacked the majesty of the people or not?\" The argument is—\"I only used the power which I legitimately had over my own son.\" The denial of this argument is—\"But a man who, by the power belonging to him as a father, that is to say, as a private individual, attacks the power of a tribune of the people, that is to say, the power of the people itself, attacks the majesty of the people.\"", src:"cic_inv", cite:"Cicero, De inventione II.17 (Yonge)", why:"The father does not deny that he dragged his son from the temple. The dispute is whether that deed should be called an attack on “the majesty of the people,” so it is about the name. Cicero gives this case as his example of the definitive statement (De inventione II.17)."},
  {id:"st-vessel", status:"definition", text:"…if any one has stolen any sacred vessel from a private place, whether he is to be considered a sacrilegious person, or a simple thief.", src:"cic_inv", cite:"Cicero, De inventione I.8 (Yonge)", why:"No one disputes that the vessel was taken. The question is whether the act should be called sacrilege or simple theft, so the dispute is about the name, and Cicero says that “it is necessary to define both points” (De inventione I.8)."},
  {id:"st-norbanus", status:"definition", cue:"Norbanus is accused of treason for the violence used against Caepio while he was tribune. The defense speaks first, and the accuser replies.", text:"\"He did not commit treason in proceeding to violent measures in respect to Caepio; for it was the first indignation of the Roman people that prompted that violent conduct, and not the conduct of the tribune: and the majesty, since it is identical with the greatness of the Roman people, was rather increased than diminished by retaining that man in power and office.\" And when the reply is, \"Majesty consists of the dignity of the empire and name of the Roman people, which that man impairs, who excites sedition by appealing to the violent passions of the multitude;\"", src:"cic_part", cite:"Cicero, Partitiones oratoriae 30 (Yonge)", why:"Both sides grant that there was violence against Caepio. They dispute what majesty is and whether this act diminished it, so the dispute is about the name. Cicero gives the question “Whether Norbanus has committed treason against the people” as his example of definition in the Partitions (chapter 30)."},
  {id:"st-knight", status:"transference", text:"When certain armed men had come for the purpose of committing violence, and armed men were also prepared on the other side, and when one of the armed men with his sword cut off the hand of a certain Roman knight who resisted his violence, the man whose hand had been cut off brings an action for the injury. The man against whom the action is brought pleads a demurrer before the praetor, without there being any prejudice to a man on trial for his life. The man who brings the action demands a trial on the simple fact, the man against whom the action is brought says that a demurrer ought to be added. The question is—\"Shall the demurrer be allowed or not?\"", src:"cic_inv", cite:"Cicero, De inventione II.20 (Yonge)", why:"The defendant does not answer the charge of injury. He asks the praetor to add a demurrer, so that an action for damages does not decide in advance a crime that belongs to the court for assassins. The dispute is therefore whether the action is rightly brought, and Cicero gives this case as his example of translation (De inventione II.20)."},
  {id:"st-parricide", status:"transference", text:"\"When a certain person had been prosecuted for poisoning, and, because he was also accused of parricide, the trial was ordered to proceed out of its regular order, when in the accusation some charges were corroborated by witnesses and arguments, but the parricide was barely mentioned, it was proper for the advocate for the defence to dwell much and long on this circumstance, as, nothing whatever was proved respecting the death of the accused person's parent, and therefore that it was a scandalous thing to inflict that punishment on him which is inflicted on parricides, but that that must inevitably be the case if he were convicted, since that it is added as one of the counts of the indictment, and since it is on that account that the trial has been ordered to be taken out of its regular order. Therefore if it is not right that that punishment should be inflicted on the criminal, it is also not right that he should be convicted, since that punishment must inevitably follow a conviction.\"", src:"cic_inv", cite:"Cicero, De inventione II.19 (Yonge)", why:"The advocate does not rest his defense on the facts of the poisoning. He argues that the trial was taken out of its regular order on a charge of parricide that was barely proved, so that a conviction would bring the wrong penalty. An objection to the penalty is one of the points that Cicero lists for the transferable statement (De inventione II.19)."},
  {id:"st-orestes", status:"quality", part:"retort", notParts:["absolute"], text:"If Orestes be accused of matricide, unless he says this, \"I did it rightfully, for she had murdered my father,\" he has no defence at all.", src:"cic_inv", cite:"Cicero, De inventione I.13 (Yonge)", why:"Orestes admits that he killed his mother and says that he did it rightfully. The dispute is therefore about the character of the act, which Cicero calls the general statement (De inventione I.8); the later name is the issue of quality.", partWhy:"Orestes defends the act by the wrong that his mother did first, since she “had murdered my father.” Cicero calls this the retorting of an accusation, in which the act is said to be lawful “because another had previously provoked the doer wrongfully” (De inventione I.11)."},
  {id:"st-trophy", status:"quality", part:"absolute", notParts:["comparison"], text:"When the Thebans had defeated the Lacedaemonians in war, as it was nearly universal custom among the Greeks, when they were waging war against one another, for those who were victorious to erect some trophy on their borders, for the sake only of declaring their victory at present, not that it might remain for ever as a memorial of the war, they erected a brazen trophy. They are accused before the Amphictyons, that is, before the common council of Greece. The charge is, \"They ought not to have done so.\" The denial is, \"We ought.\" The question is, \"Whether they ought.\" The reason is, \"For we gained such glory by our valour in that war, that we wished to leave an everlasting memorial of it to posterity.\"", src:"cic_inv", cite:"Cicero, De inventione II.23 (Yonge)", why:"The Thebans admit that they set up a bronze trophy and argue that they were right to do it. The dispute is about the character of the act, that is, the issue of quality (De inventione II.23).", partWhy:"The Thebans defend the trophy by its own merit, the glory they won, and they bring in nothing from outside the act. Cicero gives this as his example of the absolute division, which “itself contains in itself the question of right and not right” (De inventione II.23). He adds that if the Thebans pleaded that their enemies had made war unjustly, the case would pass to the retorting of an accusation."},
  {id:"st-general", status:"quality", part:"comparison", notParts:["necessity"], text:"\"A certain general, when he was blockaded by the enemy and could not escape by any possible means, made a covenant with them to leave behind his arms and his baggage, on condition of being allowed to lead away his soldiers in safety. And he did so. Having lost his arms and his baggage, he saved his men, beyond the hopes of any one. He is prosecuted for treason.\" … The charge is, \"He had no business to leave behind the arms and baggage.\" The denial is, \"Yes, he had.\" The question is, \"Whether he had any right to do so?\" The reason for doing so is, \"For else he would have lost all his soldiers.\"", src:"cic_inv", cite:"Cicero, De inventione II.24 (Yonge)", why:"The general admits that he left the arms and baggage and argues that he had the right to do so. The dispute is about the character of the act, the issue of quality (De inventione II.24). Cicero adds that a charge under the name of a crime, such as treason, also calls for a definition, but the question he sets out here is whether the general had the right.", partWhy:"The general defends a loss that could not be approved by itself, by the end for which he accepted it, the safety of his soldiers. Cicero calls this comparison, “when any action which intrinsically cannot be approved, is defended by reference to that for the sake of which it was done” (De inventione II.24)."},
  {id:"st-horatius", status:"quality", part:"retort", notParts:["absolute"], text:"\"Horatius, when he had slain the three Curiatii and lost his two brothers, returned home victorious. He saw his sister not troubled about the death of her brothers, but at the same time calling on the name of Curiatius, who had been betrothed to her, with groans and lamentation. Being indignant, he slew the maid\". He is prosecuted. The charge is, \"You slew your sister wrongfully\". The refutation is \"I slew her lawfully\". The question is, \"Whether he slew her lawfully\". The reason is, \"Yes, for she was lamenting the death of enemies, and was indifferent to that of her brothers, she was grieved that I and the Roman people were victorious\".", src:"cic_inv", cite:"Cicero, De inventione II.26 (Yonge)", why:"Horatius admits that he killed his sister and says that he did it lawfully. The dispute is about the character of the act, the issue of quality (De inventione II.26).", partWhy:"Horatius defends the killing by his sister’s own fault, since she mourned the enemy and not her brothers. Cicero gives this as his example of the retorting of a charge, in which the accused says “he did it justifiably, being induced by the sin committed against him by the other party” (De inventione II.26)."},
  {id:"st-rhodamb", status:"quality", part:"removal", notParts:["necessity", "accident"], text:"\"The Rhodians sent some men as ambassadors to Athens. The quaestors did not give the ambassadors the money for their expenses which they ought to have given them. The ambassadors consequently did not go. They are impeached.\" The charge brought against them is, \"They ought to have gone.\" The denial is, \"They ought not.\" The question is, \"Whether they ought.\" The reason alleged is, \"Because the money for their expenses, which is usually given to ambassadors from the public treasury, was not given to them by the quaestor.\"", src:"cic_inv", cite:"Cicero, De inventione II.29 (Yonge)", why:"The ambassadors admit that they did not go and argue that they were not bound to go. The dispute is about the character of their conduct, the issue of quality (De inventione II.29).", partWhy:"The ambassadors lay the blame on the quaestors, who did not give them the money for the journey. Cicero calls this removal (Yonge names it the transference of an accusation), in which the charge “is transferred to some other person or circumstance” (De inventione II.29). It is a division of the issue of quality, and not the fourth issue, transference, which objects to the trial itself."},
  {id:"st-calf", status:"quality", part:"ignorance", notParts:["necessity"], text:"\"There was a law in a certain nation that no one should sacrifice a calf to Diana. Some sailors, when in a terrible tempest they were being tossed about in the open sea, made a vow that if they reached the harbour which they were in sight of, they would sacrifice a calf to the god who presided over that place. Being ignorant of the law, when they landed, they sacrificed a calf.\" They are prosecuted. The accusation is, \"You sacrificed a calf to a god to whom it was unlawful to sacrifice a calf.\" The denial consists in the admission which has been already stated. The reason is, \"I was not aware that it was unlawful.\"", src:"cic_inv", cite:"Cicero, De inventione II.31 (Yonge)", why:"The sailors admit the sacrifice and plead that they did not know the law. The act is granted, and the question is whether they deserve punishment for it, which is the issue of quality (De inventione II.31).", partWhy:"The sailors plead that they did not know the law against sacrificing a calf to Diana. Cicero gives this as his example of ignorance, one of the three excuses under concession (he calls them purgation), in which “the intention of the person who is accused, is defended” (De inventione II.31)."},
  {id:"st-contractor", status:"quality", part:"accident", notParts:["necessity"], text:"\"There was a law among the Lacedaemonians, that if the contractor failed to supply victims for a certain sacrifice, he should be accounted guilty of a capital offence; and accordingly, the man who had contracted to supply them, when the day of the sacrifice was at hand, began to drive in cattle from the country into the city. It happened on a sudden that the river Eurotus, which flows by Lacedaemon, was raised by some violent storms, and became so great and furious that the victims could not by any possibility be conveyed across. The contractor, for the sake of showing his own willingness, placed all the victims on the bank of the river, in order that every one on the other side of the river might be able to see them. But though, everyone was aware that it was the unexpected rise of the river which hindered him from giving effect to his zeal, still some people prosecuted him on the capital charge.\" The charge was, \"The victims which you were bound to furnish for the sacrifice were not furnished.\" The reply was an admission of the fact. The reason alleged was, \"For the river rose on a sudden, and on that account it was impossible to convey them across.\"", src:"cic_inv", cite:"Cicero, De inventione II.31 (Yonge)", why:"The contractor admits that the victims were not furnished and gives the reason. The act is granted, and the question is whether he deserves punishment for it, which is the issue of quality (De inventione II.31).", partWhy:"The contractor did what he could, but the sudden flood of the river kept the victims from crossing. Cicero gives this as his example of accident, which is pleaded “when it is proved that some power of fortune interfered with his intention” (De inventione II.31)."},
  {id:"st-ship", status:"quality", part:"necessity", notParts:["accident"], text:"\"There is a law among the Rhodians, that if any vessel with a beak is caught in their harbour, it shall be confiscated. There was a violent storm at sea; the violence of the winds compelled a vessel, against the will of her crew, to take refuge in the harbour of the Rhodians. On this the quaestor claims the vessel for the people. The captain of the ship declared that it was not just that it should be confiscated.\" The charge is, \"A ship with a beak was caught in the harbour.\" The reply is an admission of the fact.", src:"cic_inv", cite:"Cicero, De inventione II.32 (Yonge)", why:"The captain admits that the beaked ship was in the harbor and argues that it should not be confiscated. The fact is granted, and the dispute is whether the penalty is just, which is the issue of quality (De inventione II.32).", partWhy:"The storm drove the ship into the harbor against the will of her crew. Cicero gives this as his example of necessity, in which the accused “is defended as having done what he is accused of having done under the influence of compulsion” (De inventione II.32)."},
  {id:"st-deprec", status:"quality", part:"deprecation", notParts:[], cue:"Cicero gives this as words that an advocate might use for a man who has done great services to the republic.", text:"\"But if, O judges, this man, in return for the services which he has done you, and the zeal which he has displayed in your cause at all times, were now, when he himself is in such peril, to entreat you, in consideration of his many good actions, to pardon this one error, it would only be what is due both to your own character for clemency, and to his virtue, O judges, for you to grant him this indulgence at his request.\"", src:"cic_inv", cite:"Cicero, De inventione II.34 (Yonge)", why:"The speaker does not deny the act or call it right; he asks the judges to pardon “this one error” for the sake of the man’s services. Pardon belongs to concession, which Cicero places under the general statement, the issue of quality (De inventione I.11 and II.34).", partWhy:"The speaker offers no defense of the act and asks only for pardon in return for the man’s services. Cicero calls this deprecation, “when it is not attempted to defend the action in question, but entreaties to be pardoned are employed,” and he says that it can hardly be approved in a court of justice (De inventione II.34)."},
  {id:"st-opimius", status:"quality", cue:"Opimius, as consul, put down Gaius Gracchus and his followers by force, and the tribune Decius later accused him.", text:"…as in the case of Opimius, \"I did it lawfully, for the sake of preserving the general safety and the republic;\" and when Decius replies, \"You had no power or right to slay even the wickedest of the citizens without a trial.\"", src:"cic_part", cite:"Cicero, Partitiones oratoriae 30 (Yonge)", why:"Opimius does not deny the killing; he says that he did it lawfully, for the safety of the republic. The dispute is whether he had the right to put a citizen to death without a trial, and Cicero gives “Whether Opimius slew Gracchus lawfully” as his example of the question of justice (Partitions, chapter 30), which is the issue of quality."},
  {id:"st-archias", status:"fact", cue:"Gratius prosecutes the poet Archias for claiming the rights of a Roman citizen. The law granted citizenship to a man who was enrolled in a confederate city, had a residence in Italy, and made a return of himself to the praetor within sixty days.", text:"“But he had no residence at Rome.” What, not he who for so many years before the freedom of the city was given to him, had established the abode of all his property and fortunes at Rome? “But he did not return himself.” Indeed he did, and in that return which alone obtains with the college of praetors the authority of a public document.", src:"cic_yonge", cite:"Cicero, For Archias 9 (Yonge)", why:"Cicero answers two of the prosecutor’s claims, that Archias had no residence at Rome and that he did not make a return of himself, by saying that he did both. The dispute is whether these things were done, so the case stands on the issue of fact, which Cicero calls the conjectural statement (De inventione I.8)."},
  {id:"st-roscius", status:"fact", cue:"Sextus Roscius is accused of killing his father, and Cicero answers the accuser, Erucius.", text:"The cause in question is parricide; which cannot be undertaken without many motives; and it is being tried before very wise men, who are aware that no one commits the very slightest crime without any motive whatever. Be it so; you are unable to allege any motive. Although I ought at once to gain my cause, yet I will not insist on this, and I will concede to you in this cause what I would not concede in another, relying on this man's innocence. I do not ask you why Sextus Roscius killed his father; I ask you how he killed him?", src:"cic_yonge", cite:"Cicero, For Sextus Roscius of Ameria 73 (Yonge)", why:"Cicero says that the accuser can allege no motive, and then he asks how Roscius could have killed his father, because he denies that Roscius killed him at all. The dispute is about the deed itself, so the case stands on the issue of fact. Quintilian gives “whether Roscius has murdered his father” as an example of conjecture (Institutio oratoria VII.2.2)."},
  {id:"st-olive", status:"fact", cue:"The speaker is accused before the Council of clearing away the stump of a sacred olive from his land.", text:"So I consider, gentlemen, that my business is to show that, when I acquired the plot, there was neither olive-tree nor stump upon it.", src:"lysias_lamb", cite:"Lysias, On the Olive-Stump 7.5 (Lamb)", why:"The speaker says that there was neither tree nor stump on the plot when he acquired it, so he denies the deed. The dispute is whether the thing was done, so the case stands on the issue of fact."},
  {id:"st-mantitheus", status:"fact", cue:"Mantitheus has been chosen by lot for the Council, and before he takes his seat he must pass a scrutiny of his life. His accusers say that he served in the cavalry under the Thirty.", text:"I will begin by showing that I did not serve in the cavalry or reside here under the Thirty, and that I had no hand in the government of that time. Our father, before the disaster at the Hellespont, had sent us abroad to live at the court of Satyrus, on the Pontus. We were not residing in Athens either when the walls were being demolished or when the constitution was being changed. We came here five days before the people at Phyle returned to the Peiraeus.", src:"lysias_lamb", cite:"Lysias, In Defence of Mantitheus 16.3–4 (Lamb)", why:"Mantitheus denies that he served in the cavalry or lived in Athens under the Thirty, and he offers his absence on the Pontus as proof. The dispute is whether he did what is alleged, so the case stands on the issue of fact."},
  {id:"st-knapp-street", status:"fact", cue:"Webster prosecutes John Francis Knapp for the murder of Joseph White of Salem. To convict Knapp as a principal, the government must prove that he was present, aiding in the murder.", text:"But, Gentlemen, let us now consider what is the evidence produced on the part of the government to prove that John Francis Knapp, the prisoner at the bar, was in Brown Street on the night of the murder. This is a point of vital importance in this cause. Unless this be made out, beyond reasonable doubt, the law of presence does not apply to the case. The government undertake to prove that he was present aiding in the murder, by proving that he was in Brown Street for this purpose.", src:"webster_w", cite:"Daniel Webster, argument on the trial of John Francis Knapp (1830)", why:"Webster turns to the evidence that Knapp was in Brown Street on the night of the murder. Whether he was there is a question about what was done, so on this point the case stands on the issue of fact. Webster says that unless this is proved, “the law of presence does not apply to the case.”"},
  {id:"st-murderer", status:"definition", cue:"Theomnestus said in court that the speaker had killed his own father. The speaker sues him for slander, since the law forbids certain words of abuse.", text:"Well, it may be, gentlemen, that he will make no defence on these points, but will state again to you what he had the boldness to say before the arbitrator—that it is not a use of a forbidden word to say that someone has killed his father, since the law does not prohibit that, but does disallow the use of the word murderer. For my part, gentlemen, I hold that your concern is not with mere words but with their meaning, and that you are all aware that those who have killed someone are murderers, and that those who are murderers have killed someone.", src:"lysias_lamb", cite:"Lysias, Against Theomnestus 10.6–7 (Lamb)", why:"Theomnestus does not deny what he said. He argues that the law forbids only the word “murderer,” and the speaker answers that the words mean the same thing. The dispute is about the name that the words should bear under the law, so the case stands on the issue of definition. Quintilian places this kind of question under definition, as a question about a term “which depends on the letter of the law” (Institutio oratoria VII.3.7)."},
  {id:"st-knapp-presence", status:"definition", cue:"The defense says that Knapp, waiting in Brown Street behind Mr. White’s garden, could not have given help from there, and so was not present at the murder. Webster has just quoted Foster, a writer on the criminal law.", text:"The author, in speaking of being present, means actual presence; not actual in opposition to constructive, for the law knows no such distinction. There is but one presence, and this is the situation from which aid, or supposed aid, may be rendered. The law does not say where the person is to go, or how near he is to go, but that he must be where he may give assistance, or where the perpetrator may believe that he may be assisted by him. Suppose that he is acquainted with the design of the murderer, and has a knowledge of the time when it is to be carried into effect, and goes out with a view to render assistance, if need be; why, then, even though the murderer does not know of this, the person so going out will be an abettor in the murder.", src:"webster_w", cite:"Daniel Webster, argument on the trial of John Francis Knapp (1830)", why:"Here Webster does not argue where Knapp was. He argues what the law means by presence, so that a man who waits in a place to give help, if it is needed, is an abettor in the murder. The dispute is about the name that the act should bear, so on this point the case stands on the issue of definition. Later in the speech Webster turns to the fact, whether Knapp was in Brown Street at all."},
  {id:"st-caecina", status:"definition", cue:"Aebutius and a band of armed men drove Caecina off a farm that both men claimed. Caecina obtained an interdict from the praetor against violence.", text:"Still Aebutius is not touched by this interdict. How so? Because violence was not offered to Caecina. Can it be said in this cause, where there were arms, where there was a multitude of men collected, where there were men carefully equipped and placed in appointed places with swords, where there were threats, dangers, and terrors of death, that there was no violence? “No one,” says he, “was slain, or even wounded.” What are you saying? When we are speaking of a dispute about a right of possession, and about an action at law between private individuals, will you say that no violence was done, if actual murder and slaughter did not take place? I say that mighty armies have often been put to flight and routed by the mere terror and charge of the enemy, not only without the death of any one, but even without one single person being wounded. In truth, O judges, that is not the only violence which reaches our persons and our lives, but that is even a much greater one, which, by threatening us with the danger of death, often drives our minds, agitated by fear as they are, from their steady position and condition.", src:"cic_yonge", cite:"Cicero, For Aulus Caecina 41–42 (Yonge)", why:"No one disputes that armed men were gathered and that Caecina’s party fled. The dispute is whether this may be called violence when no one was killed or wounded, so the case stands on the issue of definition. Quintilian quotes this passage of the speech in his chapter on definition (Institutio oratoria VII.3.17)."},
  {id:"st-suicide", status:"definition", cue:"Quintilian gives three questions that arise in the courts.", text:"Take as examples the questions, whether suicide is a form of homicide, or whether the man who forces a tyrant to kill himself can be considered a tyrannicide, or whether magical incantations are equivalent to the crime of poisoning. In all these cases there is no doubt about the facts, for it is well known that there is a difference between killing oneself and killing another, between slaying a tyrant and forcing him to suicide, between employing incantations and administering a deadly draught, but we enquire whether we are justified in calling them by the same name.", src:"quint", cite:"Quintilian, Institutio oratoria VII.3.7 (Butler)", why:"In each question the facts are agreed, and Quintilian says that we ask only “whether we are justified in calling them by the same name.” The dispute is about the name, so each question stands on the issue of definition."},
  {id:"st-postumus", status:"transference", cue:"Rabirius Postumus, a Roman knight, is prosecuted under the Julian law on extortion, in an inquiry into what became of the money that Aulus Gabinius had been condemned to repay.", text:"You have a tablet given you on which to record your judgment. According to what law? To the Julian law about extortion and peculation. Concerning what defendant? Concerning a Roman knight. But that body is not liable to the operation of that law.", src:"cic_yonge", cite:"Cicero, For Caius Rabirius Postumus 12 (Yonge)", why:"Cicero does not answer the charge itself here. He objects that the law under which Postumus is tried does not reach his order, so the dispute is whether the action is rightly brought. Cicero counts a case in which the accused is not tried “in accordance with the proper law” as a statement by way of demurrer, which is the issue of transference (De inventione I.8)."},
  {id:"st-attius", status:"transference", cue:"Cicero replies to the prosecutor, Titus Attius, about the law under which Cluentius is tried, and he imagines Attius himself accused under a law that does not reach him.", text:"If anyone, O Titus Attius, were to wish to prosecute you before me as judge, you would cry out that you were not liable under the law about extortion. Nor would this demurrer of yours be any confession that you had appropriated the money illegally; but it would be merely a refusal to encounter a labour and a danger which you were not obliged to encounter by the law.", src:"cic_yonge", cite:"Cicero, For Aulus Cluentius 148 (Yonge)", why:"In the case that Cicero imagines, Attius would neither deny nor admit that he took the money. He would object only that the law on extortion does not bind him, so the dispute is whether the action is rightly brought. Cicero calls this plea a demurrer, and the statement by way of demurrer is the issue of transference (De inventione I.8)."},
  {id:"st-prescription", status:"transference", cue:"Quintilian speaks of the defense that rests on a point of law, when the accused neither denies nor defends the act.", text:"When the dispute turns on prescription, there is no need to enquire into the facts of the case itself. For example, a son puts forward a demurrer against his father on the ground that his father has forfeited his civil rights. The only point which has to be decided is whether the demurrer can stand.", src:"quint", cite:"Quintilian, Institutio oratoria VII.5.3 (Butler)", why:"The son does not answer his father’s charge. He objects that a man who has lost his civil rights cannot bring the action, so the only question is whether the action may proceed. Butler calls this plea prescription, or a demurrer, and it belongs to the issue of transference, in which Cicero says that the inquiry is “who ought to be the accuser or pleader” (De inventione I.11)."},
  {id:"st-polemarchus", status:"quality", part:"removal", notParts:["necessity"], cue:"Lysias prosecutes Eratosthenes, one of the Thirty, for the death of his brother Polemarchus, and he questions Eratosthenes in court.", text:"Did you arrest Polemarchus or not?—I was acting on the orders of the government, from fear.—Were you in the Council-chamber when the statements were being made about us?—I was.—Did you speak in support or in opposition of those who were urging the death sentence?—In opposition.—You were against taking our lives?—Against taking your lives.—In the belief that our fate was unjust, or just?—That it was unjust.", src:"lysias_lamb", cite:"Lysias, Against Eratosthenes 12.25 (Lamb)", why:"Eratosthenes admits the arrest and says that he acted on the orders of the government. The deed is granted, and the dispute is whether he is to blame for it, so the case stands on the issue of quality.", partWhy:"Eratosthenes lays the cause of the arrest on the Thirty, whose orders he says he obeyed. Cicero calls this removal, in which it is said that “the deed was done in consequence of the power and influence of another” (De inventione I.11). Lysias answers that the Thirty cannot excuse themselves by the orders of the Thirty (Against Eratosthenes 12.29)."},
  {id:"st-ligarius", status:"quality", part:"deprecation", notParts:["ignorance", "necessity"], cue:"Tubero accuses Quintus Ligarius before Caesar of having been in Africa, on the side that fought against Caesar in the civil war.", text:"But, however, since that which was previously unknown has been ferreted out by the diligence of his enemy we must, I suppose, confess the truth; especially as my dear friend Caius Pansa has so acted that it would not now be in my power to deny it. Therefore, abandoning all dispute of the fact, all my speech must be addressed to your mercy; by which many have already been preserved, having besought of you, not a release from all guilt, but pardon from admitted error.", src:"cic_yonge", cite:"Cicero, For Ligarius 1 (Yonge)", why:"Cicero gives up “all dispute of the fact” and does not defend the act; he asks only for mercy. The act is granted, and the question is whether Ligarius should be pardoned, which belongs to the issue of quality (De inventione I.11 and II.34).", partWhy:"Cicero asks Caesar for “pardon from admitted error,” and not for release from guilt. Cicero calls this deprecation, “when it is not attempted to defend the action in question, but entreaties to be pardoned are employed” (De inventione II.34). Quintilian says that most writers do not admit such a plea in the courts, but that it has its place before one “who is in a position to show clemency,” as Caesar was (Institutio oratoria VII.4.17–18)."}
];
// Cicero's four statements of the case (De inventione I.8) and the divisions of the general statement (II.23–36).
const STASIS_LABELS = {
  fact:'Fact: it is disputed whether the thing was done or is so',
  definition:'Definition: the act is granted, and its name is disputed',
  quality:'Quality: the act is granted, and its character is disputed',
  transference:'Transference: whether an action may be brought is disputed'
};
const STASIS_PARTS = {
  absolute:'Absolute: the act is defended as right in its own nature',
  comparison:'Comparison: the act was done for the sake of a greater good',
  retort:'Retort: the act answered a wrong that the other did first',
  removal:'Removal: the blame is laid on some other person or thing',
  ignorance:'Ignorance: the accused did not know what the law forbade',
  accident:'Accident: fortune prevented what the accused had intended',
  necessity:'Necessity: the accused was compelled by force to do it',
  deprecation:'Deprecation: the act is not defended, and pardon is asked'
};
const TOPOI_ITEMS = [
  {id:"tp-inflect", list:"arist", topic:"inflections", notTopics:["relatives", "name", "definition", "opposites"], text:"…that the just is not entirely good, for in that case good would be predicable of anything that happens justly; but to be justly put to death is not desirable.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.2 (Freese)", why:"The argument passes from “just” to its derived form “justly”, so that if the just were entirely good, whatever happens justly would be good; but to be justly put to death is not desirable. Aristotle calls this the topic “derived from similar inflections” (II.23.2)."},
  {id:"tp-diomedon", list:"arist", topic:"relatives", notTopics:["analogy", "moreless", "opposites", "inflections", "turning"], text:"…as Diomedon the tax-gatherer said about the taxes, “If selling is not disgraceful for you, neither is buying disgraceful for us.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.3 (Freese)", why:"Selling and buying are relative terms, so if the one is not disgraceful, neither is the other. Aristotle gives the example under the topic “derived from relative terms” (II.23.3)."},
  {id:"tp-gods", list:"arist", topic:"moreless", notTopics:["analogy", "induction", "relatives", "judgment"], text:"For instance, if not even the gods know everything, hardly can men;", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.4 (Freese)", why:"Knowledge of everything belongs more probably to the gods than to men, so if the gods lack it, men lack it too. Aristotle says that “if a predicate, which is more probably affirmable of one thing, does not belong to it, it is clear that it does not belong to another of which it is less probably affirmable” (II.23.4)."},
  {id:"tp-statue", list:"arist", topic:"time", notTopics:["changechoice", "contradiction", "contrary", "relatives", "moreless"], text:"Thus Iphicrates, in his speech against Harmodius, says: “If, before accomplishing anything, I had demanded the statue from you in the event of my success, you would have granted it; will you then refuse it, now that I have succeeded? Do not therefore make a promise when you expect something, and break it when you have received it.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.6 (Freese)", why:"Iphicrates sets what the Athenians would have granted before his success beside what they refuse after it. Aristotle calls this the topic “derived from the consideration of time” (II.23.6)."},
  {id:"tp-aristophon", list:"arist", topic:"turning", notTopics:["moreless", "contradiction", "relatives", "analogy"], text:"…Iphicrates employed it against Aristophon, when he asked him whether he would have betrayed the fleet for a bribe; when Aristophon said no, “Then,” retorted Iphicrates, “if you, Aristophon, would not have betrayed it, would I, Iphicrates, have done so?”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.7 (Freese)", why:"Iphicrates answers the charge by turning it on Aristophon, who made it. Aristotle describes the topic as “turning upon the opponent what has been said against ourselves” (II.23.7), and he adds that it works only when the opponent “seems the more likely to have committed a crime”."},
  {id:"tp-daimonion", list:"arist", topic:"definition", notTopics:["name", "parts", "division", "inflections", "judgment"], cue:"The example refers to Socrates, who was accused of not believing in the gods.", text:"For instance, that the daimonion is nothing else than a god or the work of a god; but he who thinks it to be the work of a god necessarily thinks that gods exist.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.8 (Freese)", why:"The argument rests on what the daimonion is, because if it is a god or the work of a god, the man who believes in it believes that gods exist. Aristotle says that in such cases “it is by definition and the knowledge of what the thing is in itself that conclusions are drawn” (II.23.8)."},
  {id:"tp-motives", list:"arist", topic:"division", notTopics:["parts", "induction", "cause", "motive", "crossing"], text:"For example, “There are always three motives for wrongdoing; two are excluded from consideration as impossible; as for the third, not even the accusers assert it.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.10 (Freese)", why:"The speaker divides the possible motives into three and sets aside each of them in turn. Aristotle introduces the example with the words “Another, from division” (II.23.10)."},
  {id:"tp-horses", list:"arist", topic:"induction", notTopics:["analogy", "moreless", "judgment", "sameresult"], text:"There is another instance in the “law” of Theodectes: “If we do not entrust our own horses to those who have neglected the horses of others, or our ships to those who have upset the ships of others; then, if this is so in all cases, we must not entrust our own safety to those who have failed to preserve the safety of others.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.11 (Freese)", why:"From the cases of horses and of ships the speaker draws a rule for “all cases”, and then he applies it to our own safety. Aristotle gives it as an instance of the topic “from induction” (II.23.11)."},
  {id:"tp-sappho", list:"arist", topic:"judgment", notTopics:["consequence", "definition", "opposites", "moreless", "incredible", "cause"], text:"…Sappho, “Death is an evil; the gods have so decided, for otherwise they would die.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.12 (Freese)", why:"The gods, by not choosing to die, have judged that death is an evil, and their judgment is not to be contradicted. Aristotle calls this the topic “from a previous judgement”, and he includes the judgment of “those whose judgement it is unseemly to contradict, for instance, the gods” (II.23.12)."},
  {id:"tp-holyplace", list:"arist", topic:"parts", notTopics:["division", "definition", "induction", "contradiction"], text:"There is an instance of this in the Socrates of Theodectes: “What holy place has he profaned? Which of the gods recognized by the city has he neglected to honor?”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.13 (Freese)", why:"The charge of impiety is examined in its parts, the holy places and the gods of the city, and each part is denied. Aristotle calls this the topic “from enumerating the parts” (II.23.13)."},
  {id:"tp-education", list:"arist", topic:"consequence", notTopics:["crossing", "opposites", "contrary", "cause"], text:"For instance, education is attended by the evil of being envied, and by the good of being wise; therefore we should not be educated, for we should avoid being envied; nay rather, we should be educated, for we should be wise.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.14 (Freese)", why:"Education has a bad consequence and a good one, and the speaker argues from either. Aristotle says that this topic consists “in employing the consequence to exhort or dissuade, accuse or defend, praise or blame” (II.23.14)."},
  {id:"tp-priestess", list:"arist", topic:"crossing", notTopics:["consequence", "opposites", "contrary", "division", "contradiction"], text:"For instance, a priestess refused to allow her son to speak in public; “For if,” said she, “you say what is just, men will hate you; if you say what is unjust, the gods will.” On the other hand, “you should speak in public; for if you say what is just, the gods will love you, if you say what is unjust, men will.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.15 (Freese)", why:"Speaking justly and speaking unjustly are opposites, and each brings both a good and an evil, so the argument can be turned either way. Aristotle says that the topic is used “in regard to two opposites”, when “good and evil follow on each” (II.23.15)."},
  {id:"tp-tallboys", list:"arist", topic:"analogy", notTopics:["opposites", "relatives", "moreless", "induction", "inflections", "definition", "sameresult", "turning"], text:"For instance, Iphicrates, when they tried to force his son to perform public services because he was tall, although under the legal age, said: “If you consider tall boys men, you must vote that short men are boys.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.17 (Freese)", why:"Iphicrates applies to short men the same reasoning that the Athenians apply to tall boys, so that if height can make a boy a man, the lack of it can make a man a boy. Aristotle calls this the topic “derived from analogy in things” (II.23.17)."},
  {id:"tp-leodamas", list:"arist", topic:"cause", notTopics:["motive", "mistakes", "consequence", "falseopinion", "contradiction", "moreless"], text:"For example, Leodamas, when defending himself against the accusation of Thrasybulus that his name had been posted in the Acropolis but that he had erased it in the time of the Thirty, declared that it was impossible, for the Thirty would have had more confidence in him if his hatred against the people had been graven on the stone.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.25 (Freese)", why:"Leodamas argues that he had no cause to erase his name, since under the Thirty the inscription would have helped him, and so the erasure did not happen. Aristotle says of this topic, “If the cause exists, the effect exists; if the cause does not exist, the effect does not exist” (II.23.25)."},
  {id:"tp-polus", list:"arist", topic:"name", notTopics:["inflections", "definition", "analogy"], text:"…Herodicus said of Thrasymachus, “Thou art ever bold in fight,” and of Polus, “Thou art ever Polus (colt) by name and colt by nature,” and of Draco the legislator that his laws were not those of a man, but of a dragon, so severe were they.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.29 (Freese)", why:"Each saying takes the man’s name as a sign of what he is, since the name of Thrasymachus means bold in fight, Polus means a colt, and the name Draco means a dragon. Aristotle calls this the topic “derived from the meaning of a name” (II.23.29)."},
  {id:"tp-civillaw", list:"cic", topic:"definition", notTopics:["genus", "species", "parts", "notation", "effects"], text:"\"Civil law is equity established among men who belong to the same city, for the purpose of insuring each man in the possession of his property and rights: and the knowledge of this equity is useful: therefore the knowledge of civil law is useful.\"", src:"cic_topica", cite:"Cicero, Topica 9 (Yonge)", why:"The argument states what civil law is and draws its conclusion from that statement. Cicero says that “a definition is employed with reference to the entire matter under discussion” (Topica 9)."},
  {id:"tp-slave", list:"cic", topic:"parts", notTopics:["definition", "genus", "species", "contradictories", "difference", "contraries"], text:"\"If a slave has not been declared free either by the censor, or by the praetor's rod, or by the will of his master, he is not free: but none of those things is the case: therefore he is not free.\"", src:"cic_topica", cite:"Cicero, Topica 10 (Yonge)", why:"The ways in which a slave is made free are counted one by one, and since none of them has taken place, he is not free. Cicero calls this “the enumeration of the parts” (Topica 10)."},
  {id:"tp-assiduus", list:"cic", topic:"notation", notTopics:["conjugates", "definition", "similarity", "genus", "species", "authority"], text:"As the Aelian Sentian law orders an assiduus to support an assiduus, it orders a rich man to support a rich man, for a rich man is an assiduus, called so, as Aelius says, from asse dando.", src:"cic_topica", cite:"Cicero, Topica 10 (Yonge)", why:"The argument rests on the origin of the word assiduus, which Aelius derives from asse dando (the paying of money), so that an assiduus is a rich man. Cicero says that here the argument “is derived from the meaning of a word” (Topica 10), and he later calls this topic notation (notatio)."},
  {id:"tp-readymoney", list:"cic", topic:"genus", notTopics:["species", "parts", "definition", "similarity", "comparison", "notation", "adjuncts"], text:"Since all the money has been bequeathed to the woman, it is impossible that that ready money which was left in the house should not have been bequeathed.", src:"cic_topica", cite:"Cicero, Topica 13 (Yonge)", why:"Ready money is a kind of money, so the bequest of all the money includes the ready money. Cicero explains that “the species is never separated from the genus as long as it retains its name” (Topica 13)."},
  {id:"tp-houses", list:"cic", topic:"similarity", notTopics:["comparison", "difference", "genus", "species", "contraries"], text:"\"If those houses have fallen down, or got into disrepair, a life-interest in which is bequeathed to some one, the heir is not bound to restore or to repair them, any more than he is bound to replace a slave, if a slave, a life-interest in whom has been bequeathed to some one, has died.\"", src:"cic_topica", cite:"Cicero, Topica 15 (Yonge)", why:"A house left for someone’s use during life is like a slave left in the same way, so the heir is no more bound to repair the one than to replace the other. Cicero gives this as an argument “derived from similarity” (Topica 15)."},
  {id:"tp-strongbox", list:"cic", topic:"difference", notTopics:["similarity", "contraries", "species", "genus", "parts", "comparison", "contradictories"], text:"\"It does not follow, if a man has bequeathed to his wife all the money which belonged to him, that therefore he bequeathed all which was down in his books as due to him; for there is a great difference whether the money is laid up in his strong box, or set down as due in his accounts.\"", src:"cic_topica", cite:"Cicero, Topica 16 (Yonge)", why:"Money in the strong box and money owed in the accounts seem to be the same thing, but they differ, so the bequest of the one is not the bequest of the other. Cicero gives this as an argument “derived from difference” (Topica 16)."},
  {id:"tp-cellars", list:"cic", topic:"contraries", notTopics:["difference", "contradictories", "similarity", "genus", "species", "comparison"], text:"\"That woman to whom her husband has left a life-interest in all his property, has no right, if his cellars of wine and oil are left full, to think that they belong to her; for the use of them is what has been bequeathed to her, and not the misuse: and they are contrary to one another.\"", src:"cic_topica", cite:"Cicero, Topica 17 (Yonge)", why:"Use and misuse are contraries, so a bequest of the use of the property does not give her the wine and oil to consume. Cicero gives this as an argument “derived from contraries” (Topica 17)."},
  {id:"tp-divorce", list:"cic", topic:"antecedents", notTopics:["causes", "consequents", "effects", "adjuncts", "contradictories"], text:"\"If a divorce has been caused by the fault of the husband, although the woman has demanded it, still she is not bound to leave any of her dowry for her children.\"", src:"cic_topica", cite:"Cicero, Topica 19 (Yonge)", why:"The argument rests on what went before the divorce, namely the husband’s fault, and not on which of the two demanded it. Cicero gives this as his example of the argument “from antecedents” (Topica 19)."},
  {id:"tp-partywall", list:"cic", topic:"causes", notTopics:["effects", "antecedents", "consequents", "adjuncts", "comparison"], text:"\"All men have a right to add to a common party wall, a wall extending its whole length, either solid or on arches; but if any one in demolishing the common wall should promise to pay for any damages which may arise from his action, he will not be bound to pay for any damage sustained or caused by such arches: for the damage has been done, not by the party which demolished the common wall, but in consequence of some fault in the work, which was built in such a manner as to be unable to support itself.\"", src:"cic_topica", cite:"Cicero, Topica 22 (Yonge)", why:"The damage is traced to what produced it, the faulty building of the arches, and not to the man who pulled down the common wall. Cicero gives this as an argument “derived from efficient causes” (Topica 22)."},
  {id:"tp-scaevola", list:"cic", topic:"authority", notTopics:["similarity", "comparison", "definition", "effects"], text:"\"In the case of some one building a roof for the purpose of covering a common wall, Publius Scaevola asserted that there was no right of carrying that roof so far that the water which ran off it should run on to any part of any building which did not belong to the owner of the roof. This I affirm to be law.\"", src:"cic_topica", cite:"Cicero, Topica 24 (Yonge)", why:"The argument rests on the opinion of the jurist Publius Scaevola, which is brought in from outside the case. Cicero says that arguments “derived from external circumstances are deduced chiefly from authority” (Topica 24)."},
  {id:"tp-selfcontrol", list:"arist", topic:"opposites", notTopics:["crossing", "contrary", "consequence", "contradiction", "inflections"], text:"…self-control is good, for lack of self-control is harmful;", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.1 (Freese)", why:"Self-control and the lack of it are opposites, so the good of the one is argued from the harm of the other. Aristotle says that for this topic “it is necessary to consider whether one opposite is predicable of the other” (II.23.1)."},
  {id:"tp-nicanor", list:"arist", topic:"relatives", notTopics:["analogy", "moreless", "opposites", "inflections", "judgment", "turning"], text:"Another example may be found in the trial of Demosthenes and those who slew Nicanor. For since it was decided that they had justly slain him, it was thought that he had been justly put to death.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.3 (Freese)", why:"To slay justly and to be justly put to death are relative terms, so the judgment on the slayers settles the case of the slain. Aristotle says that “if rightly or justly can be predicated of the sufferer, it can equally be predicated of the one who inflicts suffering; if of the latter, then also of the former” (II.23.3)."},
  {id:"tp-philip", list:"arist", topic:"time", notTopics:["changechoice", "contradiction", "contrary", "relatives", "moreless", "mistakes"], text:"Again, to persuade the Thebans to allow Philip to pass through their territory into Attica, they were told that “if he had made this request before helping them against the Phocians, they would have promised; it would be absurd, therefore, if they refused to let him through now, because he had thrown away his opportunity and had trusted them.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.6 (Freese)", why:"The Thebans are asked to grant now what they would have granted before Philip helped them, since his help should not make his claim weaker. Aristotle gives this as a second example of the topic “derived from the consideration of time” (II.23.6)."},
  {id:"tp-noble", list:"arist", topic:"definition", notTopics:["moreless", "relatives", "name", "judgment", "parts", "inflections", "induction"], text:"When Iphicrates desired to prove that the best man is the noblest, he declared that there was nothing noble attaching to Harmodius and Aristogiton, before they did something noble; and, “I myself am more akin to them than you; at any rate, my deeds are more akin to theirs than yours.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.8 (Freese)", why:"Iphicrates argues from what nobility is, namely that it comes from noble deeds and not from birth, and so he claims to be more akin to them than his opponent is. Aristotle says that in such cases “it is by definition and the knowledge of what the thing is in itself that conclusions are drawn” (II.23.8)."},
  {id:"tp-peparethus", list:"arist", topic:"induction", notTopics:["analogy", "judgment", "moreless", "sameresult", "division"], text:"For instance, from the case of the woman of Peparethus, it is argued that in matters of parentage women always discern the truth; similarly, at Athens, when Mantias the orator was litigating with his son, the mother declared the truth; and again, at Thebes, when Ismenias and Stilbon were disputing about a child, Dodonis declared that Ismenias was its father, Thettaliscus being accordingly recognized as the son of Ismenias.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.11 (Freese)", why:"A general rule, that in matters of parentage women always discern the truth, is drawn from several like cases, at Peparethus, Athens, and Thebes. Aristotle introduces the example with the words “Another, from induction” (II.23.11)."},
  {id:"tp-aristippus", list:"arist", topic:"judgment", notTopics:["consequence", "definition", "moreless", "analogy", "induction", "contradiction", "turning"], text:"Or as Aristippus, when in his opinion Plato had expressed himself too presumptuously, said, “Our friend at any rate never spoke like that,” referring to Socrates.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.12 (Freese)", why:"Aristippus answers Plato with the judgment of Socrates, whose judgment Plato could not well contradict. Aristotle includes under this topic the judgment “of those whose judgement it is not possible to contradict” or “unseemly to contradict” (II.23.12)."},
  {id:"tp-xenophanes", list:"arist", topic:"sameresult", notTopics:["opposites", "consequence", "cause", "moreless", "contrary", "crossing", "definition"], text:"Thus Xenophanes said: “There is as much impiety in asserting that the gods are born as in saying that they die; for either way the result is that at some time or other they did not exist.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.18 (Freese)", why:"To say that the gods are born and to say that they die lead to the same thing, that at some time the gods did not exist, and so the two sayings are equally impious. Aristotle describes this topic as “concluding the identity of antecedents from the identity of results” (II.23.18)."},
  {id:"tp-exile", list:"arist", topic:"changechoice", notTopics:["time", "contradiction", "contrary", "opposites", "consequence", "crossing", "moreless"], text:"“If, when in exile, we fought to return to our country [it would be monstrous] if, now that we have returned, we were to return to exile to avoid fighting”!", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.19 (Freese)", why:"The exiles once chose to fight in order to return, and now they would be choosing exile in order not to fight. Aristotle says that this topic is “derived from the fact that the same men do not always choose the same thing before and after, but the contrary” (II.23.19)."},
  {id:"tp-diomedes", list:"arist", topic:"motive", notTopics:["cause", "falseopinion", "consequence", "judgment", "mistakes", "moreless"], text:"And the following remark from the Ajax of Theodectes, that Diomedes chose Odysseus before all others, not to do him honor, but that his companion might be his inferior; for this may have been the reason.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.20 (Freese)", why:"A motive that Diomedes might have had, that his companion should be his inferior, is put forward as his real motive. Aristotle says that this topic consists “in maintaining that the cause of something which is or has been is something which would generally, or possibly might, be the cause of it” (II.23.20)."},
  {id:"tp-androcles", list:"arist", topic:"incredible", notTopics:["analogy", "induction", "moreless", "contradiction", "judgment", "opposites", "sameresult"], text:"Thus, Androcles of Pitthus, speaking against the law, being shouted at when he said “the laws need a law to correct them,” went on, “and fishes need salt, although it is neither probable nor credible that they should, being brought up in brine; similarly, pressed olives need oil, although it is incredible that what produces oil should itself need oil.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.22 (Freese)", why:"Androcles grants that it seems incredible that the laws need a law, as it seems incredible that fishes need salt and olives oil, and yet these things are so. Aristotle says of this topic that “if then a thing is incredible and not probable, it will be true” (II.23.22)."},
  {id:"tp-thirty", list:"arist", topic:"contradiction", notTopics:["turning", "opposites", "crossing", "contrary", "mistakes", "changechoice"], text:"…first, separately in the case of the adversary, for instance, “he says that he loves you, and yet he conspired with the Thirty;” next, separately in your own case, “he says that I am litigious, but he cannot prove that I have ever brought an action against anyone”; lastly, separately in the case of your adversary and yourself together: “he has never yet lent anything, but I have ransomed many of you.”", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.23 (Freese)", why:"In each example the speaker sets words against deeds, or one man’s deeds against another’s, and shows that they do not agree. Aristotle says that this topic, “appropriate to refutation, consists in examining contradictories, whether in dates, actions, or words” (II.23.23)."},
  {id:"tp-embrace", list:"arist", topic:"falseopinion", notTopics:["motive", "cause", "mistakes", "contradiction"], text:"For example, a woman embraced her son in a manner that suggested she had illicit relations with him, but when the reason was explained, the slander was quashed.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.24 (Freese)", why:"The slander is answered by explaining why the embrace was misunderstood. Aristotle says that when men or things have been attacked by slander, this topic “consists in stating the reason for the false opinion” (II.23.24)."},
  {id:"tp-leucothea", list:"arist", topic:"contrary", notTopics:["crossing", "opposites", "division", "contradiction", "definition", "consequence", "changechoice"], text:"For instance, when the people of Elea asked Xenophanes if they ought to sacrifice and sing dirges to Leucothea, or not, he advised them that, if they believed her to be a goddess they ought not to sing dirges, but if they believed her to be a mortal, they ought not to sacrifice to her.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.27 (Freese)", why:"Sacrifice is offered to a goddess and dirges are sung for a mortal, so the two acts are contrary, and Xenophanes examines them together. Aristotle says that the topic is used “when something contrary to what has already been done is on the point of being done” (II.23.27)."},
  {id:"tp-medea", list:"arist", topic:"mistakes", notTopics:["cause", "motive", "moreless", "falseopinion", "turning", "consequence"], text:"For instance, in the Medea of Carcinus, some accuse Medea of having killed her children,—at any rate, they had disappeared; for she had made the mistake of sending them out of the way. Medea herself pleads that she would have slain, not her children, but her husband Jason; for it would have been a mistake on her part not to have done this, if she had done the other.", src:"arist_freese", cite:"Aristotle, Rhetoric II.23.28 (Freese)", why:"The accusers use Medea’s mistake in sending the children away, and Medea answers that if she had killed the children, it would have been a mistake to spare Jason. Aristotle says that this topic consists “in making use of errors committed, for purposes of accusation or defence” (II.23.28)."},
  {id:"tp-agent", list:"cic", topic:"similarity", notTopics:["comparison", "genus", "species", "parts", "definition"], text:"\"If a guardian is bound to behave with good faith, and a partner, and any one to whom you have entrusted anything, and any one who has undertaken a trust then so ought an agent.\"", src:"cic_topica", cite:"Cicero, Topica 42 (Yonge)", why:"The agent is like the guardian, the partner, and the trustee, so he is bound in the same way. Cicero places this argument under similarity, and he says that because it arrives at its point “by a comparison of many instances”, it “is called induction” (Topica 42)."},
  {id:"tp-minor", list:"cic", topic:"difference", notTopics:["similarity", "contraries", "species", "genus", "comparison", "contradictories"], text:"\"If you have contracted a debt to a woman, you can pay her without having recourse to a trustee, but what you owe to a minor, whether male or female; you cannot pay in the same manner.\"", src:"cic_topica", cite:"Cicero, Topica 46 (Yonge)", why:"A debt to a woman and a debt to a minor seem alike, but they differ, so what is allowed in the one is not allowed in the other. Cicero gives this as an instance of the topic of “difference between things” (Topica 46)."},
  {id:"tp-folly", list:"cic", topic:"contraries", notTopics:["difference", "contradictories", "similarity", "comparison", "consequents"], text:"\"If we avoid folly, let us pursue wisdom; and if we avoid wickedness, let us pursue goodness.\"", src:"cic_topica", cite:"Cicero, Topica 47 (Yonge)", why:"Folly and wisdom, and wickedness and goodness, are contraries in the same kind, so what we avoid in the one directs us to the other. Cicero gives this as an argument deduced from contraries, which, being “contrary qualities in the same class, are called opposites” (Topica 47)."},
  {id:"tp-lifeinterest", list:"cic", topic:"contradictories", notTopics:["contraries", "difference", "consequents", "antecedents", "adjuncts"], text:"\"If the head of a family has left to his wife in reversion after his son the life-interest in the female slaves, and has made no mention of any other reversionary heir, if the son dies, the woman shall not lose her life-interest. For that which has once been given to any one by will, cannot be taken away from the legatee to whom it has been given without his consent; for it is a contradiction for any one to have a right to receive a thing, and yet to be forced to give it up against his will.\"", src:"cic_topica", cite:"Cicero, Topica 21 (Yonge)", why:"The right to receive a thing and the duty to give it up against one’s will cannot stand together, so the woman keeps her life-interest. Cicero gives this as his example of the argument “from contradictories” (Topica 21)."},
  {id:"tp-water", list:"cic", topic:"comparison", notTopics:["similarity", "genus", "species", "difference", "contraries"], text:"\"That which is valid in a greater affair, ought to be valid in a less: so that, if the law does not regulate the limits in the city, still more will it not compel any one to turn off the water in the city.\"", src:"cic_topica", cite:"Cicero, Topica 23 (Yonge)", why:"The boundaries of property are a greater matter than the turning off of rain-water, so if the law does not reach the greater within the city, it does not reach the less. Cicero gives this under comparison, among the “many kinds of valid arguments” of that topic (Topica 23)."},
  {id:"tp-counsellors", list:"cic", topic:"comparison", notTopics:["similarity", "genus", "species", "difference", "consequents", "definition"], text:"\"If to assist one's fellow-citizens with counsel and personal aid deserves equal praise, those men who act as counsellors ought to enjoy an equal glory with those who are the actual defenders of a state.\"", src:"cic_topica", cite:"Cicero, Topica 71 (Yonge)", why:"Help by counsel and help in person are compared as equals, so the men who give each deserve equal glory. Cicero gives this as an example of the comparison of things “like or equal to each other” (Topica 71)."}
];
// Aristotle's topics of the enthymeme (Rhetoric II.23), named as Freese gives them.
const TOPOI_ARIST = {
  opposites:'Opposites: what holds for a thing is examined in its opposite',
  inflections:'Inflections: what holds of a word holds for its derived forms',
  relatives:'Relative terms: what is true of one party holds for the other',
  moreless:'More and less: if the likelier case fails, the less must fail',
  time:'Time: what would have been granted earlier is due now as well',
  turning:'Turning the charge: the accusation is turned upon the accuser',
  definition:'Definition: the conclusion is inferred from what the thing is',
  division:'Division: the possible cases are listed and each is set aside',
  induction:'Induction: a general rule is drawn from several similar cases',
  judgment:'Previous judgment: those who must be believed have decided it',
  parts:'Parts: the whole is examined by going through each part of it',
  consequence:'Consequence: a thing is urged or opposed for its consequences',
  crossing:'Two opposites: good and evil follow on each of two contraries',
  analogy:'Analogy: what is granted in one case holds in its counterpart',
  sameresult:'Same result: things with the same result are held to be alike',
  changechoice:'Change of choice: people choose the contrary of a past choice',
  motive:'Possible motive: a possible motive is taken as the actual one',
  incredible:'The incredible: a thing so unlikely would be said only if true',
  contradiction:'Contradiction: the opponent’s words and deeds are at variance',
  falseopinion:'Cause of a slander: the reason for the false opinion is given',
  cause:'Cause: the effect is decided by whether its cause was present',
  contrary:'Contrary acts: the two contrary courses are examined together',
  mistakes:'Mistakes: an error made before is used to accuse or to defend',
  name:'Meaning of a name: a name is taken to show what the person is'
};
// Cicero's topics (Topica 8–24), named as Yonge gives them.
const TOPOI_CIC = {
  definition:'Definition: the whole matter is unfolded by saying what it is',
  parts:'Enumeration of the parts: the whole is examined part by part',
  notation:'Notation: the argument rests on what a word originally meant',
  conjugates:'Conjugates: the argument rests on words of the same root',
  genus:'Genus: what is granted of the kind holds of what is under it',
  species:'Species: the argument turns on which form of the kind is meant',
  similarity:'Similarity: cases that are alike must be judged in a like way',
  difference:'Difference: two things that seem alike are shown to be unlike',
  contraries:'Contraries: what is true of a thing is denied of its contrary',
  adjuncts:'Adjuncts: the argument rests on what goes along with the thing',
  antecedents:'Antecedents: the argument rests upon what went before the act',
  consequents:'Consequents: the argument rests on what followed after the act',
  contradictories:'Contradictories: two claims are shown unable to stand at once',
  causes:'Efficient causes: the effect is explained by what produced it',
  effects:'Effects: the argument rests on what has been brought about',
  comparison:'Comparison: a case is laid beside one greater, equal, or less',
  authority:'Authority: a weighty opinion is brought from outside the case'
};
const GREG_PAIRS = [
  {id:'g1', pair:'the joyful and the sad', why:'The first are to be checked lest they run to excess; the second are to be comforted lest they break.', src:'greg'},
  {id:'g2', pair:'the humble and the proud', why:'The first are to be praised carefully, lest praise become a snare; the second are to be rebuked, lest silence confirm them.', src:'greg'},
  {id:'g3', pair:'the silent and the talkative', why:'The first must be drawn to a useful word; the second must be taught to spare the hearer.', src:'greg'},
  {id:'g4', pair:'the young and the old', why:'The first are to be admonished to keep order; the second are to be asked for the example that their years already claim.', src:'greg'},
  {id:'g5', pair:'men and women', why:'Heavier injunctions are laid on the one, lighter on the other, that those may be exercised by great things and these winningly converted by light ones.', src:'greg'},
  {id:'g6', pair:'the poor and the rich', why:'The first are to be offered the solace of comfort against tribulation; the second are to be made afraid of elation.', src:'greg'},
  {id:'g7', pair:'subjects and prelates', why:'The first must not be crushed by obedience; the second must not be elated by their place, nor command more than is just.', src:'greg'},
  {id:'g8', pair:'servants and masters', why:'The first are to be admonished not to despise those over them; the second, not to forget that they too have a Lord in heaven.', src:'greg'},
  {id:'g9', pair:'the wise of this world and the dull', why:'The first must not trust their own cleverness; the second must not despair of being taught.', src:'greg'},
  {id:'g10', pair:'the impudent and the bashful', why:'The first are to be checked by open rebuke; the second are to be drawn on by gentle encouragement.', src:'greg'},
  {id:'g11', pair:'the gluttonous and the abstinent', why:'The first are to be restrained from the belly; the second are to be kept from pride in their fasting.', src:'greg'},
  {id:'g12', pair:'the merciful and the envious', why:'The first are to be praised without being taught to spare justice; the second are to be shown that another’s good is no theft from themselves.', src:'greg'},
  {id:'g13', pair:'the peaceful and the brawlers', why:'The first are to be kept from a false quiet that hides the wound; the second are to be taught the cost of a quarrel.', src:'greg'},
  {id:'g14', pair:'those who preach and those who are silent in the office of preaching', why:'The first must not neglect their own life; the second must not hide the talent.', src:'greg'},
  {id:'g15', pair:'the forward and the faint-hearted', why:'The first are to be shown that deeds they prize may displease God; the second are to be lifted out of despondency.', src:'greg'},
  {id:'g16', pair:'the impatient and the patient', why:'Fury drives the first into evils they were not seeking; the second are to be kept from turning endurance into a wish for revenge.', src:'greg'},
  {id:'g17', pair:'the simple and the insincere', why:'The first are sometimes to be silent about a truth; the second are to learn how heavy a labor duplicity is.', src:'greg'},
  {id:'g18', pair:'those who fear scourges and those whom scourges do not correct', why:'The first are to grow out of dread into charity; the second grow worse by complaining under a stroke that does not heal them.', src:'greg'},
  {id:'g19', pair:'the slothful and the hasty', why:'The first lose a good by delay, until they can no longer do it; the second change the merit of a deed by doing it before its time.', src:'greg'},
  {id:'g20', pair:'the meek and the passionate', why:'The first soften strictness more than the case allows; the second take their anger for the zeal of righteousness.', src:'greg'},
  {id:'g21', pair:'the obstinate and the fickle', why:'The first will not take counsel, thinking too well of themselves; the second abandon their own judgment, thinking too little of themselves.', src:'greg'},
  {id:'g22', pair:'those who give of their own and those who seize what belongs to others', why:'The first are to be kept from swelling above those they support; the second are to be called off from the taking.', src:'greg'},
  {id:'g23', pair:'those who neither covet nor give, and those who give and still seize', why:'The first withhold a common gift from the poor; the second, for all their alms, remain in the taking.', src:'greg'},
  {id:'g25', pair:'sowers of strifes and peacemakers', why:'The first follow the enemy who scattered tares among the wheat; the second must learn between whom concord ought to be made.', src:'greg'},
  {id:'g26', pair:'those who misread the sacred law and those who understand it but speak it without humility', why:'In the first the medicine of Scripture is turned into poison; the second, proud of their learning, treat true words as if they were their own.', src:'greg'},
  {id:'g28', pair:'those who prosper in temporal wishes and those worn by adversity', why:'The first are to seek the giver along with the gift; the second are to see a physician’s care in what is withheld.', src:'greg'},
  {id:'g29', pair:'those who have known sins of the flesh and those who have not', why:'The first are to fear the sea after shipwreck; the second are to be warned lest innocence grow torpid.', src:'greg'},
  {id:'g30', pair:'those who weep for sins and still commit them, and those who leave their sins and do not weep', why:'In the first, tears that prepare a return to filth cleanse nothing; the second still owe the mourning for what they have left.', src:'greg'},
  {id:'g31', pair:'those who commend the wrong they do and those who blame a wrong and still commit it', why:'The first teach their fault to every hearer; the second pass sentence on themselves.', src:'greg'},
  {id:'g32', pair:'those overcome by a sudden passion and those who sin on purpose', why:'The first are struck while the heart is unguarded; the second, having chosen their guilt with deliberation, kindle a stricter judgment.', src:'greg'},
  {id:'g33', pair:'those who often commit small sins and those who seldom commit grievous ones', why:'The first are to count their faults, as drops that fill a river; the second are to see that pride in the faults they avoid prepares a heavier fall.', src:'greg'},
  {id:'g34', pair:'those who do not begin a good work and those who do not finish one', why:'The first are to be shown that what they love is vain; the second tear up what they had started.', src:'greg'},
  {id:'g35', pair:'those who do evil in private and good before men, and those who hide their good', why:'The first lie open to the divine sentence, whatever virtue they show in public; the second lay a stumbling-block before the weak by letting ill be thought of them.', src:'greg'},
  // Quotations from Barmby’s Book III (chapters 1–17); the question asks which pair Gregory is dividing.
  {id:'gq-old', pair:'the young and the old', quote:'For it is written, Rebuke not an elder, but entreat him as a father.', why:'The first are for the most part improved by severity of admonition; the second are better disposed by kind remonstrance.', src:'greg'},
  {id:'gq-wise', pair:'the wise of this world and the dull', quote:'The former are for the most part converted by arguments of reasoning; the latter sometimes better by examples.', why:'The first must be argued out of their own opinion of their cleverness; the second are better drawn on by the praiseworthy deeds of others.', src:'greg'},
  {id:'gq-impudent', pair:'the impudent and the bashful', quote:'There is come unto thee a whore\'s forehead; thou wouldest not blush.', why:'The first are corrected only by direct and open rebuke; the second are better touched by a rebuke given as if in passing.', src:'greg'},
  {id:'gq-envious', pair:'the merciful and the envious', quote:'Whence it is written, And the Lord had respect unto Abel and to his offering, but unto Cain and to his offering He had not respect.', why:'The first are to keep their good deeds from pride; the second are to see that another’s gift takes nothing from them.', src:'greg'},
  {id:'gq-insincere', pair:'the simple and the insincere', quote:'Hence it is said through Jeremiah, They have taught their tongue to speak lies, and weary themselves to commit iniquity…', why:'The first must sometimes keep back a truth to spare others; the second are to learn that deceit costs more labor than plain dealing.', src:'greg'},
  {id:'gq-scourges', pair:'those who fear scourges and those whom scourges do not correct', quote:'Against these the prophet complains to the Lord, saying, Thou hast bruised them, and they have refused to receive discipline.', why:'The first must be led from dread of punishment to love; the second grow harder under every blow that is meant to heal them.', src:'greg'},
  {id:'gq-talk', pair:'the silent and the talkative', quote:'Hence it is written, As a city that lieth open and without environment of walls, so is a man that cannot keep in his spirit in speaking.', why:'The first must learn when a word is owed; the second must learn that many words leave the mind open to every enemy.', src:'greg'},
  {id:'gq-sloth', pair:'the slothful and the hasty', quote:'To him it is well said again through the same Solomon, He that observeth the wind doth not sow: and he that regardeth the clouds never reapeth.', why:'The first wait on every doubt until the time for acting has gone; the second act before they have weighed the deed.', src:'greg'},
  // Quotations from Barmby’s Book III (chapters 18–35).
  {id:'gq-obstinate', pair:'the obstinate and the fickle', quote:'To the former it is said through Paul, Be not wise in your own conceits: but the latter on the other hand should hear this; Let us not be carried about with every wind of doctrine.', why:'The first trust their own judgment too much to be moved; the second are moved by every new opinion.', src:'greg'},
  {id:'gq-abstinent', pair:'the gluttonous and the abstinent', quote:'…Paul would by no means have said, Let not him that eateth not judge him that eateth.', why:'The first are to fear the levity and lust that follow on excess; the second are to fear the pride that follows on restraint.', src:'greg'},
  {id:'gq-seize', pair:'those who neither covet nor give, and those who give and still seize', quote:'But the Lord shews with what strong censure he disowns them, saying through a certain wise man, Whoso offereth a sacrifice of the substance of the poor doeth as one that killeth the son before the father\'s eyes.', why:'The first are to learn that keeping back what should be shared is itself a fault; the second, that a gift made from what was taken is hateful to God.', src:'greg'},
  {id:'gq-flesh', pair:'those who have known sins of the flesh and those who have not', quote:'Let them hear what is said through John; These are they which have not been defiled with women; for they are virgins, and follow the Lamb whithersoever He goeth…', why:'The first are to be raised by the hope of pardon after their fall; the second are to keep the purity they have without despising those who fell.', src:'greg'},
  {id:'gq-weep', pair:'those who weep for sins and still commit them, and those who leave their sins and do not weep', quote:'Hence through a certain wise man it is said, He that is baptized from the touch of a dead body and toucheth it again, what availeth his washing?', why:'The first wash themselves with tears only to soil themselves again; the second must still mourn the faults they have left behind.', src:'greg'},
  {id:'gq-commend', pair:'those who commend the wrong they do and those who blame a wrong and still commit it', quote:'Hence it is written, They have declared their sin as Sodom, neither have they hidden it.', why:'The first make their fault worse by publishing it with praise; the second condemn it in words and keep it in deed.', src:'greg'},
  {id:'gq-small', pair:'those who often commit small sins and those who seldom commit grievous ones', quote:'For hence it is that it is said of the Pharisees, Straining out a gnat, but swallowing a camel.', why:'The first are to fear the slow ruin that comes from many little faults; the second are to see that care about the least things does not excuse the greatest.', src:'greg'},
  {id:'gq-finish', pair:'those who do not begin a good work and those who do not finish one', quote:'Hence it is said by the Angel to the Church of Sardis, Be watchful, and strengthen the things which remain, that are ready to die; for I find not thy works complete before my God.', why:'The first are to be urged to set their hand to good works at all; the second are to be urged to bring to an end what they have started.', src:'greg'},
  {id:'gq-hide', pair:'those who do evil in private and good before men, and those who hide their good', quote:'Hence it is that Moses, when he said, Thou shalt not curse the deaf, at once added, Nor put a stumblingblock before the blind.', why:'The first are to fear the judgment that sees what is done in secret; the second are to let their good be seen, so that others are not made to stumble.', src:'greg'}
];
const FIGURE_GLOSS = {
  anaphora:'the same word at the head of successive members',
  antithesis:'opposed thoughts set in parallel frames',
  apostrophe:'a turn away from the hearers to address someone absent or dead, a god, or a thing treated as a person',
  tricolon:'three coordinated members, often rising',
  isocolon:'members of roughly equal length and shape',
  homoeoteleuton:'like endings on successive clauses',
  metaphor:'naming one thing with another’s name, on a seen likeness',
  irony:'saying less, or the opposite, to mean more',
  'rhetorical question':'a question that is a charge, not a request for information',
  chiasmus:'crossed order (ABBA)',
  epizeuxis:'immediate repetition of the same word',
  sententia:'a general maxim, briefly stated',
  climax:'members rising in force',
  asyndeton:'coordination without conjunctions',
  personification:'treating an abstraction as an agent',
  simile:'a likeness stated openly, usually with like or as',
  hyperbole:'deliberate excess',
  occupatio:'anticipating an objection',
  praeteritio:'claiming to pass over what one thereby names',
  hypotyposis:'vivid description that sets a scene before the eyes',
  exclamatio:'an open cry of feeling',
  correctio:'taking back a word to put a sharper one',
  enumeratio:'a numbered or listed unfolding',
  dilemma:'a choice between two alternatives, both unfavorable',
  mythos:'a story offered as explanation',
  definition:'an argument from what the thing is called',
  ethos:'the speaker’s character serving as proof',
  pathos:'the hearer’s passion serving as proof',
  prooimion:'the Greek opening, which has the same office as the Latin exordium',
  exordium:'the opening part (office) of the speech',
  exemplum:'an example used as proof',
  hendiadys:'one idea through two coordinated nouns',
  litotes:'understatement by denying the contrary',
  parenthesis:'a break that inserts a second voice',
  hypothesis:'a supposed case used as argument',
  prosopopoeia:'giving a voice to the absent or the dead',
  epithet:'a descriptive word or phrase attached to a name',
  // Further figures added with the English-tradition passages (all in the optional tier)
  epistrophe:'the same word at the end of successive members',
  symploce:'the same words at the head and at the end of successive members',
  anadiplosis:'the last word of one member taken up at the head of the next',
  epanalepsis:'a member that ends with the word it began with',
  epimone:'a phrase repeated as a refrain, to dwell on one point',
  conduplicatio:'a key word repeated in successive clauses',
  polyptoton:'the same root repeated in different grammatical forms',
  anastrophe:'a word or phrase moved out of its usual order for emphasis',
  polysyndeton:'a conjunction placed between every member of a series',
  ellipsis:'leaving out words that the hearer supplies from the context',
  aposiopesis:'breaking off in the middle of a sentence',
  hypophora:'asking a question and then answering it'
};
const SPEECH_FIGURES = {
  anaphora:1, antithesis:1, apostrophe:1, tricolon:1, isocolon:1, homoeoteleuton:1,
  metaphor:1, irony:1, 'rhetorical question':1, chiasmus:1, epizeuxis:1, sententia:1,
  climax:1, asyndeton:1, personification:1, simile:1, hyperbole:1, occupatio:1,
  praeteritio:1, hypotyposis:1, exclamatio:1, correctio:1, enumeratio:1, dilemma:1,
  hendiadys:1, litotes:1, parenthesis:1, prosopopoeia:1, epithet:1,
  epistrophe:1, symploce:1, anadiplosis:1, epanalepsis:1, epimone:1, conduplicatio:1, polyptoton:1, anastrophe:1, polysyndeton:1, ellipsis:1, aposiopesis:1, hypophora:1
};
function isSpeechFigure(name){ return !!SPEECH_FIGURES[name]; }
function speechSpans(p){ return (p.spans||[]).filter(s => isSpeechFigure(s.figure)); }
// Two tiers of figures. The main figures exercises ask only about the core figures, the ones most
// commonly taught; every other speech figure is in the optional tier, drilled in Further figures.
// To move a figure between tiers, add it to CORE_FIGURES or take it out.
const CORE_FIGURES = {
  anaphora:1, antithesis:1, apostrophe:1, tricolon:1, isocolon:1, homoeoteleuton:1, metaphor:1, simile:1, personification:1, irony:1, 'rhetorical question':1, chiasmus:1, climax:1, asyndeton:1, hyperbole:1, sententia:1, litotes:1, praeteritio:1
};
function isCoreFigure(name){ return isSpeechFigure(name) && !!CORE_FIGURES[name]; }
function isAdvancedFigure(name){ return isSpeechFigure(name) && !CORE_FIGURES[name]; }
function coreSpans(p){ return speechSpans(p).filter(s => isCoreFigure(s.figure)); }
// Core figures that may be asked about in this passage: not those that a study card itself shows in it.
function askCore(p){ return coreSpans(p).filter(s => !cardTaught('fig:'+p.id+':'+s.figure)); }
function advancedSpans(p){ return speechSpans(p).filter(s => isAdvancedFigure(s.figure)); }
function figLabel(f){ return isAdvancedFigure(f) ? f+' (optional)' : f; }
function isOration(p){
  if(!p) return false;
  if(/Douay|Matthew|Paul|John/.test(p.author||'')) return false;
  if(/Homer|Virgil|Boethius/.test(p.author||'')) return false;
  if(/Pastoral Rule|Consolation|Confessions/.test(p.work||'')) return false;
  return !!speciesOf(p);
}
const PISTEIS_ITEMS = [
  {pid:'cic-cat1-1', pistis:'pathos', why:'The questions are not for information; they put the senate into alarm and shame.'},
  {pid:'ant-3.2.1', pistis:'ethos', why:'The quiet man is forced into court against his nature, and his character serves as proof.'},
  {pid:'gor-hel-8', pistis:'logos', why:'Gorgias makes a claim about what logos is and offers it as the ground of Helen’s acquittal.'},
  {pid:'thuc-diod-1', pistis:'logos', why:'Diodotus argues from the nature of counsel: haste and passion oppose good deliberation.'},
  {pid:'ant-3.1.1', pistis:'logos', why:'The facts are agreed, so the charge is a description of cause.'},
  {pid:'plato-ap-1', pistis:'ethos', why:'Socrates refuses the usual bid for the jury’s goodwill, and his manner of speaking becomes the proof of his character.'},
  {pid:'aug-chast', pistis:'pathos', why:'The divided will is shown so that the hearer feels the shame of “not yet.”'},
  {pid:'thuc-fun-2', pistis:'ethos', why:'Athens is characterized, and the city’s ethos becomes the speaker’s.'},
  {pid:'sal-caes-1', pistis:'logos', why:'Caesar argues from the laws and from the consequences of a novel penalty.'},
  {pid:'cic-cat1-4', pistis:'pathos', why:'“Where are we?” The question raises fear and indignation before the proof is unfolded.'},
  {pid:'gor-hel-10', pistis:'pathos', why:'Song is treated as witchery, and the account of the passions is offered as an account of how the soul is moved.'},
  {pid:'soph-ant-2', pistis:'ethos', why:'“My nature is for mutual love, not hate”: character is named as the ground of the act.'},
  {pid:'cic-milo-1', pistis:'ethos', why:'The advocate’s confessed fear is made a proof of the man he defends, and of the danger.'},
  {pid:'thuc-arch-1', pistis:'ethos', why:'The speaker appeals to his age and his experience of many wars, so his character is the reason to wait.'},
  {pid:'thuc-cleon-1', pistis:'logos', why:'Cleon argues from what empire is: a democracy that talks cannot hold it.'},
  {pid:'aug-ddc-12', pistis:'logos', why:'The three offices are distinguished by what they do, not by a display of feeling.'},
  {pid:'sal-cat-consp', pistis:'pathos', why:'Catiline moves the conspirators by hope, grievance, and the dare.'},
  {pid:'plato-ap-2', pistis:'ethos', why:'He will not beg, and his bearing serves as the argument.'},
  {pid:'tac-cal-1', pistis:'pathos', why:'Calgacus puts the host into the mind of a last free people, with no land behind them.'},
  {pid:'dem-3', pistis:'logos', why:'Money, ships, and a law that the force remain make up a policy argued from its parts.'},
  {pid:'cic-marc-1', pistis:'ethos', why:'The long silence came from grief, not fear, and Cicero’s character is restored with Caesar’s clemency.'},
  {pid:'gor-hel-6', pistis:'logos', why:'Four causes are named, so the case is divided before it is proved.'},
  {pid:'ant-3.2.10', pistis:'pathos', why:'The father sets his son’s ruin and his own childlessness before the jurors, so that they feel pity.'},
  {pid:'thuc-fun-1', pistis:'ethos', why:'He will not praise as others have praised; the city’s character is his.'},
  // English tradition (public-domain quotations; sources eng_cer, eng_cem, kjv).
  {pid:'eng-henry-liberty-death', pistis:'pathos', why:'The questions and the prayer are meant to make slavery hateful and liberty worth any risk, so the force lies in what the hearers feel.'},
  {pid:'eng-lincoln-proclamation', pistis:'logos', why:'Lincoln takes both possible cases of the law and shows that neither allows a retraction, so the proof lies in the argument.'},
  {pid:'eng-franklin-consent', pistis:'ethos', why:'The sentence has the form of an argument, but its two reasons (he expects no better, and he is not sure that it is not the best) prove little about the Constitution; they are confessions of doubt. What persuades is the man who makes them: the oldest delegate, and one of the most eminent, admits his doubts and still consents, and his candor is offered as a reason for others to do the same.'},
  {pid:'eng-ames-volcano', pistis:'pathos', why:'The image of a volcano does not prove that democracy destroys itself; it makes the hearers afraid that it will.'},
  {pid:'eng-nott-duel', pistis:'pathos', why:'The preacher moves his hearers to shame, since the charge ends with their own silence.'},
  {pid:'eng-burke-tyrants', pistis:'logos', why:'The sentence is a maxim, and Aristotle treats a maxim as the premise or the conclusion of an enthymeme (II.21). Burke states a general cause and effect, that rebellion on principle gives kings a reason to rule as tyrants, and the hearers are asked to judge whether it is true, not chiefly to feel fear or to trust the speaker.'},
  // Further labels. Each one is defensible from the excerpt of about 240 characters, which is what the hardest setting shows.
  {pid:'cic-cat3-11', pistis:'ethos', why:'He declines any reward of merit and any memorial of his renown, and he places the distinction in the eternal remembrance of this day.'},
  {pid:'cic-cat4-2', pistis:'pathos', why:'Cicero sets before the senators their own safety, their wives, their children, and their properties, so that fear for these, and not regard for the consul, governs their vote; the line about ceasing to consider him serves that end.'},
  {pid:'dem-1', pistis:'ethos', why:'Speakers who praise the forefathers, he judges, desire to gratify the hearers, and are not acting in the interests of those whom they praise.'},
  {pid:'dem-2', pistis:'ethos', why:'He lays it down as the duty of every speaker to declare the policy he considers best, and to keep malice and favor out of the speech.'},
  {pid:'plato-ap-3', pistis:'ethos', why:'He honors and loves the Athenians, he will obey God rather than them, and he will never cease from the practice of philosophy.'},
  {pid:'cic-cat2-12', pistis:'ethos', why:'The safe defense of the city is what he has taken thought for, and what he has made provision for.'},
  {pid:'sal-cat-2', pistis:'ethos', why:'He tells the soldiers he is well aware that words cannot inspire courage, and that a speech cannot make a timid army valiant.'},
  {pid:'eng-lincoln-events', pistis:'ethos', why:'He attempts no compliment to his own sagacity, and he says plainly that events have controlled him.'},
  {pid:'eng-johnson-macpherson', pistis:'ethos', why:'He repeats the judgment he has given the public, that the book is an imposture, and he defies the rage turned on him.'},
  {pid:'eng-jc-brutus-rome', pistis:'ethos', why:'He gives, as his answer for rising against Caesar, that he loved Rome more.'},
  {pid:'eng-lincoln-misquotes', pistis:'ethos', why:'He declines to say the misquotation was willful, and he states that the quotation fails to be accurate.'},
  {pid:'cic-cat1-5', pistis:'pathos', why:'The repeated line “I will not bear, I will not endure, I will not allow it” sets the indignation of the consul in front of the senate.'},
  {pid:'cic-cat1-6', pistis:'pathos', why:'Outside the band of conspirators, there is not a man in Rome who does not fear him, and not a man who does not hate him.'},
  {pid:'cic-cat1-7', pistis:'pathos', why:'The country pleads with mute eloquence, and the plea opens on the years in which no crime has been committed without his help.'},
  {pid:'cic-cat1-9', pistis:'pathos', why:'“Yet why do I speak?” and the questions whether he will reform, or think of flight, or contemplate exile, are put to a man the speaker treats as beyond appeal.'},
  {pid:'cic-cat2-1', pistis:'pathos', why:'“At length and at last, citizens of Rome, we have prevailed” releases the citizens from the man of violent heart and furious lips.'},
  {pid:'tac-cal-3', pistis:'pathos', why:'“These plunderers of the world,” stimulated by avarice if the enemy is rich and by ambition if poor, is a charge spoken to raise hatred.'},
  {pid:'eng-henry-let-it-come', pistis:'pathos', why:'“Our chains are forged” and “let it come” put the hearers into a war he calls inevitable.'},
  {pid:'eng-grattan-corry', pistis:'pathos', why:'Refusing to call the man villain, and refusing to call him fool, is itself the insult.'},
  {pid:'eng-grattan-blood-felony', pistis:'pathos', why:'The cry of blood and felony, repeated through every period of the bill, is meant to make the hearers recoil.'},
  {pid:'eng-grattan-cradle-hearse', pistis:'pathos', why:'“I sat by her cradle, I followed her hearse” mourns the Irish Parliament with a parental recollection.'},
  {pid:'cic-cat1-8', pistis:'logos', why:'The silence of the house denotes consent, and a sanction in words is still awaited.'},
  {pid:'cic-cat3-7', pistis:'logos', why:'Since the leaders have been seized, he says the hearers are bound to believe that all the forces of Catilina were defeated.'},
  {pid:'cic-cat4-4', pistis:'logos', why:'He sets out the only two motions, the proposal of Silanus that the men be punished by death, and the proposal of Caesar, which omits that punishment.'},
  {pid:'cic-milo-2', pistis:'logos', why:'“When arms speak, the laws are silent” and the reason is given: one who waits for the word of the law pays an undeserved penalty before he can exact a deserved one.'},
  {pid:'thuc-mel-1', pistis:'logos', why:'The Athenians say that the strong do what they can and the weak suffer what they must, and the Melians answer on the ground of interest.'},
  {pid:'plato-ap-4', pistis:'logos', why:'There is great reason to hope that death is a good, because death is one of two things, either a state of nothingness or a change.'},
  {pid:'aug-ddc-2', pistis:'logos', why:'He asks who will dare to say that truth is to take its stand unarmed against falsehood, when the art of rhetoric is available to enforce either truth or falsehood.'},
  {pid:'eng-henry-better-men', pistis:'logos', why:'These men will be infinitely worse than the English commoners, because they are to be chosen blindfolded.'},
  {pid:'eng-webster-knapp-there', pistis:'logos', why:'He argues presence at the murder from the facts that the man was there before it, there after it, and there unwilling to be seen.'},
  {pid:'eng-lincoln-cooper-guilty', pistis:'logos', why:'If the hearer knows of the guilt, he is inexcusable unless he names the man and proves the fact; if he does not know of it, he is inexcusable for asserting it.'},
  {pid:'eng-paine-king-law', pistis:'logos', why:'As in absolute governments the king is law, so, he says, in free countries the law ought to be king.'},
  // Lysias (Lamb) and two Yonge speeches, plus labels on passages already in the bank. Each one holds for the excerpt of about 240 characters and for the longer excerpt.
  {pid:'lys-16-1', pistis:'ethos', why:'He would be most grateful for the accusation, because an examination of the record of a life is the greatest service that can be rendered to a victim of unjust slander.'},
  {pid:'lys-16-2', pistis:'ethos', why:'The confidence is in himself: once they have heard his conduct in the past, a man inclined to dislike him will, he hopes, think better of him.'},
  {pid:'lys-24-1', pistis:'ethos', why:'He can almost find it in him to be grateful to his accuser, for previously he had no excuse for rendering an account of his life, and now, owing to this man, he has got one.'},
  {pid:'lys-25-1', pistis:'ethos', why:'Full excuse is offered to the jury if, remembering past events, they are equally incensed against all those who remained in the city.'},
  {pid:'lys-19-apt', pistis:'ethos', why:'Even with no natural aptitude for the task, he takes it as necessary to defend his father and himself as best he can.'},
  {pid:'cic-man-1', pistis:'ethos', why:'On account of his youth he has not dared to intrude upon the authority of this place, and no arguments ought to be brought here except such as were the fruit of great ability.'},
  {pid:'lys-1-1', pistis:'pathos', why:'If the jury had the same feelings about others as about themselves, not one of them but would be indignant, and the appointed penalties would seem too mild.'},
  {pid:'lys-19-fear', pistis:'pathos', why:'He is greatly embarrassed: if he fails to speak with effect today, he and his father will be held to be guilty.'},
  {pid:'tac-cal-2', pistis:'pathos', why:'“To ravage, to slaughter, to usurp under false titles, they call empire” and “where they make a desert, they call it peace” are spoken to make that rule hateful.'},
  {pid:'eng-isaiah-evil-good', pistis:'pathos', why:'“Woe unto them that call evil good, and good evil” cries out against those who confound moral names.'},
  {pid:'eng-douglass-false', pistis:'pathos', why:'“America is false to the past, false to the present, and solemnly binds herself to be false to the future” charges the nation so that the hearers feel the shame of it.'},
  {pid:'cic-cat2-3', pistis:'pathos', why:'The comparison of forces is offered to make the citizens confident, not to prove a disputed point; Aristotle counts confidence among the passions, and says it arises when we judge that our resources are greater than the danger (II.5).'},
  {pid:'thuc-corc', pistis:'logos', why:'He calls it folly to sacrifice them, and he names the reason he wants remembered: there are but three considerable naval powers in Hellas, Athens, Corcyra, and Corinth.'},
  {pid:'eng-henry-stronger', pistis:'pathos', why:'The questions state no premise and prove nothing; they make the hearers picture themselves disarmed, with a British guard in every house, so that fear and shame at delay move them to act now.'},
  {pid:'eng-lincoln-house-divided', pistis:'logos', why:'This government cannot endure permanently half slave and half free.'},
  {pid:'eng-swift-cobwebs', pistis:'logos', why:'Laws, like cobwebs, may catch small flies, but let wasps and hornets break through.'},
  {pid:'eng-burke-bristol-conscience', pistis:'ethos', why:'Burke is telling his own electors what kind of representative he is: one who will not sacrifice his judgment and conscience even to them. The speech persuades by showing his virtue (arete), and the general form of the sentence does not make it chiefly an argument.'},
  // Thucydides (Crawley), Demosthenes (Pickard), and Lysias (Lamb), plus labels on passages already in the bank. Each holds for the excerpt of about 240 characters and for the longer one.
  {pid:'thuc-arch-money', pistis:'logos', why:'Archidamus argues from a general premise, that war depends less on arms than on the money that makes arms of use, to the advice that Sparta must provide money first. He does not rest the advice on his own character, and he does not try to stir a passion.'},
  {pid:'thuc-ath-weaker', pistis:'logos', why:'The envoys defend the empire from the common practice of mankind, from three motives (“fear, honour, and interest”), and from the law that the weaker are subject to the stronger. The passage is an argument; it neither asks the Spartans to trust the speakers nor works on their feelings.'},
  {pid:'thuc-per-141', pistis:'logos', why:'Pericles states two general premises, about money and about farmers, from which it follows that the Peloponnesians cannot sustain a long war. The force of the passage lies in this reasoning, not in the speaker’s character or the hearers’ feelings.'},
  {pid:'thuc-per-142', pistis:'logos', why:'Seamanship is an art that needs constant practice, so a people of farmers cannot learn it in their spare time. This is an argument from the nature of an art, and it neither rests on Pericles’ character nor appeals to a passion.'},
  {pid:'thuc-per-143', pistis:'logos', why:'Pericles sets out what follows from either outcome of a battle on land: a victory brings only another battle, and a defeat loses the allies. The passage persuades by reasoning about consequences, not by the speaker’s character or the hearers’ feelings.'},
  {pid:'thuc-herm-nature', pistis:'logos', why:'Hermocrates reasons from human nature, since men always rule those who submit to them, and so the fault lies with those who are over-ready to serve. The general premise is what persuades, and he does not rest it on his own character or on a passion of the hearers.'},
  {pid:'thuc-herm-examples', pistis:'logos', why:'Hermocrates argues from examples, since many who tried to punish a wrong, or to gain by force, lost what they had. Aristotle counts the example, beside the enthymeme, as one of the two kinds of logical proof (I.2).'},
  {pid:'dem-phil1-23', pistis:'logos', why:'Demosthenes derives the size of the force from facts about the war: Athens cannot yet meet Philip in the field, and it could neither pay nor feed a large army. The passage reasons from the situation, with no appeal to character or to feeling.'},
  {pid:'dem-phil1-31', pistis:'logos', why:'Philip attacks when the winds and the season keep the Athenians from sailing, so a force sent out only when it is needed will always arrive too late. This is an argument from cause to consequence, not an appeal to character or to feeling.'},
  {pid:'dem-phil3-8', pistis:'logos', why:'Demosthenes argues that peace is judged by acts and not by its name; Philip’s acts are acts of war, and so resistance is the only course left. The question draws a conclusion from the facts, and it does not rest on the speaker’s character.'},
  {pid:'dem-phil3-16', pistis:'logos', why:'Demosthenes states a general principle, that religion and justice have the same force in small things and in great, and applies it to Philip’s small breaches of the peace. The principle persuades; the passage does not rest on the speaker’s character or stir a passion.'},
  {pid:'eng-mason-screw', pistis:'logos', why:'Mason argues from likeness: an aristocratic body gains power by slow degrees and holds what it gains, as a screw does, and so it should be suspected of encroaching. The simile is itself an argument, and the sentence does not rest on Mason’s character or on a passion.'},
  {pid:'thuc-herm-concede', pistis:'ethos', why:'Hermocrates shows himself moderate and prudent, ready to give up something in reason and not blinded by animosity, and he offers his own conduct as the pattern for the other cities. The proof is the speaker’s character as the speech shows it.'},
  {pid:'thuc-bras-party', pistis:'ethos', why:'Brasidas answers the hearers’ doubts by vouching for his own intentions: he has not come to help one party, and he will not overturn their constitution. The Acanthians are asked to trust the man, so the pistis is ethos (his goodwill and honesty).'},
  {pid:'thuc-per-60', pistis:'ethos', why:'Pericles meets the anger of the Athenians by describing himself as second to no man in knowing the right policy and in explaining it, and as a patriot and an honest one. The passage persuades through the speaker’s character.'},
  {pid:'sal-cato-often', pistis:'ethos', why:'Cato reminds the senate that he has often spoken against luxury and avarice and has made enemies by it, and that he never excused his own faults. He asks to be heard as a man of severe and consistent virtue.'},
  {pid:'dem-rhod-15', pistis:'ethos', why:'Demosthenes says that he is not the patron of the Rhodian democrats and has not a single friend among them, and that he makes the proposal only for the advantage of Athens. He asks to be trusted as an adviser with no private interest.'},
  {pid:'cic-cat2-11', pistis:'pathos', why:'The dread is ironic, since Cicero mocks Catiline’s followers so that the citizens feel contempt for them and confidence in themselves. The passage moves the hearers; it does not prove a disputed point, and Cicero does not speak of his own character.'},
  {pid:'thuc-nic-native', pistis:'pathos', why:'Nicias sets before the soldiers the hope of seeing their own cities again, and he bids them not lose heart, so that they go into battle with courage and hope. Aristotle counts confidence among the passions (II.5), and the passage works on the hearers’ frame of mind.'},
  {pid:'thuc-plat-compassion', pistis:'pathos', why:'The Plataeans ask the Spartan judges for compassion and name its grounds: an undeserved fate, and the chance that misfortune may fall on anyone. These are the grounds Aristotle gives for pity (II.8), so the passage works on the judges’ feelings.'},
  {pid:'lys-12-18', pistis:'pathos', why:'The details of the funeral (the hired hut, the cloak refused, the cloak and pillow given by friends) are chosen to move pity for the dead man and indignation against the Thirty. Aristotle defines pity as pain at an evil that falls on one who does not deserve it (II.8).'},
  {pid:'lys-12-19', pistis:'pathos', why:'The gold earrings taken from the ears of his brother’s wife are named to make the jury indignant at the greed of the Thirty. The passage moves the hearers; it does not argue the charge, and it does not rest on the speaker’s character.'}
];
function pistisOf(p){
  const extra = (window.QUIZ_ITEMS && window.QUIZ_ITEMS.PISTEIS_ITEMS) || [];
  const it = PISTEIS_ITEMS.concat(extra).find(x => x.pid === p.id);
  return it ? it.pistis : '';
}
const ETHOS_ITEMS = [
  {id:'et1', pid:'plato-ap-1', which:'arete', label:'Virtue (arete)',
    why:'He will not borrow the law-court’s eloquence, and so the manner of the man is the proof of the man.'},
  {id:'et2', pid:'thuc-arch-1', which:'phronesis', label:'Practical wisdom (phronesis)',
    why:'He appeals to his years and his many wars, asking to be trusted because he has seen what war costs.'},
  {id:'et3', pid:'ant-3.2.1', which:'arete', label:'Virtue (arete)',
    why:'The quiet man (apragmon) is forced into court against his nature, and his character serves as argument.'},
  {id:'et4', pid:'cic-milo-1', which:'eunoia', label:'Goodwill (eunoia)',
    why:'The advocate fears for the bravest of men and for the republic, and that goodwill is his opening.'},
  {id:'et5', pid:'plato-ap-2', which:'arete', label:'Virtue (arete)',
    why:'He will not beg for his life, and the refusal shows the man.'},
  {id:'et6', pid:'thuc-fun-2', which:'phronesis', label:'Practical wisdom (phronesis)',
    why:'Athens is presented as an original, not a copy, and the city’s wisdom is offered as the speaker’s credit.'},
  {id:'et7', pid:'cic-marc-1', which:'eunoia', label:'Goodwill (eunoia)',
    why:'The silence was grief, not fear, and today he speaks again for the house, so that his goodwill is restored.'},
  {id:'et8', pid:'soph-ant-2', which:'arete', label:'Virtue (arete)',
    why:'“My nature is for mutual love, not hate”: she names the character from which the act follows.'},
  {id:'et9', pid:'thuc-diod-1', which:'phronesis', label:'Practical wisdom (phronesis)',
    why:'He argues from what counsel is, and asks to be trusted as a man who will not be rushed.'},
  {id:'et10', pid:'sal-caes-1', which:'phronesis', label:'Practical wisdom (phronesis)',
    why:'Caesar keeps the penalty within the law and asks to be heard as the man who sees what a novel punishment costs the republic.'},
  {id:'et11', pid:'cic-cat1-1', which:'eunoia', label:'Goodwill (eunoia)',
    why:'The questions shame the senate into the consul’s side, and his goodwill toward the republic appears as shared alarm.'},
  {id:'et12', pid:'aug-ddc-2', which:'eunoia', label:'Goodwill (eunoia)',
    why:'Truth must not stand unarmed, and the Christian orator’s goodwill is for the hearer’s good, not for a fee.'},
  // English tradition (public-domain quotations; sources eng_cer, eng_cem, kjv).
  {id:'eng-et1', pid:'eng-franklin-consent', which:'phronesis', label:'Practical wisdom (phronesis)', why:'He weighs the plan against the alternatives and accepts it for want of a better, which is the judgment of a prudent man.'},
  {id:'eng-et2', pid:'eng-hoar-humane', which:'eunoia', label:'Goodwill (eunoia)', why:'He first affirms that the soldiers are humane, so that his criticism comes from a friend of the army and not an enemy.'},
  {id:'eng-et3', pid:'eng-lincoln-misquotes', which:'arete', label:'Virtue (arete)', why:'He uses praeteritio: he says he will not charge Douglas with willful misquotation, and in saying so he puts that charge before the hearers. But he asserts only what can be shown, that the quotation is inaccurate, so he gains credit as a fair man while the graver charge is still lodged; and fairness, that is, justice, is a virtue (arete).'},
  // Speeches added from Thucydides, Sallust, Plato, Demosthenes, and Lysias. Aristotle names the three in Rhetoric II.1, 1378a.
  {id:'et16', pid:'thuc-nic-convictions', which:'arete', label:'Virtue (arete)',
    why:'Nicias says that he has “never spoken against my convictions to gain honour,” although the expedition would bring him honor. The speech shows an honest man, and honesty belongs to virtue.'},
  {id:'et17', pid:'thuc-per-140', which:'phronesis', label:'Practical wisdom (phronesis)',
    why:'Pericles shows that he knows how men behave in war: “as circumstances change, resolutions change.” He asks to be trusted as a man who judges well, which is practical wisdom.'},
  {id:'et18', pid:'sal-caes-passion', which:'phronesis', label:'Practical wisdom (phronesis)',
    why:'Caesar shows that he judges without hatred, affection, anger, or pity, because “The mind, when such feelings obstruct its view, can not easily see what is right.” Right judgment about what should be done is practical wisdom.'},
  {id:'et19', pid:'sal-cato-often', which:'arete', label:'Virtue (arete)',
    why:'Cato reminds the senate that he has often complained of luxury and avarice and has made enemies by it, and that he never excused a fault in himself. He offers his own strictness as a proof of his virtue.'},
  {id:'et20', pid:'plato-ap-31b', which:'eunoia', label:'Goodwill (eunoia)',
    why:'Socrates has neglected his own concerns and has gone to each Athenian “like a father or elder brother.” The speech shows goodwill toward the hearers.'},
  {id:'et21', pid:'dem-crown-1', which:'eunoia', label:'Goodwill (eunoia)',
    why:'Demosthenes names “the goodwill, which I ever feel towards this city and towards all of you,” and prays for the same in return. Goodwill toward the hearers is the third of Aristotle’s grounds of trust.'},
  {id:'et22', pid:'dem-rhod-1', which:'phronesis', label:'Practical wisdom (phronesis)',
    why:'Demosthenes says that he has “never yet felt any difficulty in pointing out to you the best course.” He claims to know what should be done, which is practical wisdom.'},
  {id:'et23', pid:'lys-3-3', which:'arete', label:'Virtue (arete)',
    why:'The speaker says that shame at having these facts known made him put up with his wrongs. The reluctance shows a decent and modest man, so the speech persuades by his character.'},
  {id:'et24', pid:'lys-21-1', which:'arete', label:'Virtue (arete)',
    why:'He asks the jury to understand “what kind of person I am” and lists the public services he paid for. The account shows a generous and public-spirited citizen, and Aristotle counts liberality among the virtues (Rhetoric I.9).'},
  {id:'et25', pid:'thuc-per-60', which:'eunoia', label:'Goodwill (eunoia)',
    prompt:'Pericles answers the assembly’s anger by naming what he brings to its counsel. Which phrase shows goodwill (eunoia), as Aristotle uses the word?',
    options:['second to no man either in knowledge of the proper policy','or in the ability to expound it','not only a patriot','but an honest one'],
    correct:2,
    note:'Pericles glosses each phrase himself in the next sentence: a man with knowledge and the power to expound it, “but no love for his country, he would be but a cold advocate for her interests.” Love of the city is the goodwill toward the hearers that Aristotle names beside good sense and virtue (Rhetoric II.1, 1378a). Knowledge of policy is good sense (phronesis), and honesty that is “proof against bribery” is virtue (arete).'},
  {id:'et26', pid:'dem-rhod-15', which:'eunoia', label:'Goodwill (eunoia)',
    why:'Demosthenes says that he is no patron of the Rhodian democrats and has no friend among them, and that he would not have made the proposal “had I not believed it to be for your advantage.” He shows that he seeks the hearers’ good and not a private interest, which is goodwill.'},
  {id:'et27', pid:'dem-chers-68', which:'arete', label:'Virtue (arete)',
    why:'He denies that he is “Bold, offensive, shameless” and claims “more courage” than the bold speakers. Courage, and the refusal of shamelessness, belong to virtue.'},
  {id:'et28', pid:'dem-chers-24', which:'arete', label:'Virtue (arete)',
    why:'He promises to “speak without reserve,” and says that he “could not speak otherwise.” Frankness that does not spare the hearers shows an honest man, which is virtue.'},
  {id:'et29', pid:'eng-burke-tranquillity', which:'phronesis', label:'Practical wisdom (phronesis)',
    why:'Burke says that he is not settling “a point of law” but “restoring tranquillity,” and that the character of a people must decide what government fits them. He asks to be trusted as a man who judges what the situation requires, which is practical wisdom.'},
  {id:'et30', pid:'lys-32-1', which:'arete', label:'Virtue (arete)',
    why:'The speaker calls a dispute with relations “most disgraceful” and says that he would not have brought it if the matter were not important. His reluctance shows a decent man who respects the claims of kinship, which is virtue.'},
  {id:'et31', pid:'eng-webster-mariner', which:'phronesis', label:'Practical wisdom (phronesis)',
    why:'Webster proposes to “imitate this prudence” of the mariner and to return to the question before going further. He shows himself as a man who judges where the debate stands and what should be done next, which is practical wisdom.'}
];
const LEXIS_ITEMS = [
  {id:'lx1', pid:'gor-hel-8', kind:'style',
    prompt:'Does the argument here still stand once the figures are removed, or is the figure itself the claim?',
    options:['The figure is the claim; calling speech a potentate personifies it but proves nothing','The claim would stand in plain clauses, since Gorgias proves at length that speech rules the soul','The figure is only ornament on an argument from cause that is fully stated in the passage','The personification is itself a proof, because a vivid image is a kind of evidence'],
    correct:0, note:'Helen 8 presents logos as a potentate. If we remove the personification and the antithesis of frail frame and wonders, the doctrine has little left but the image.'},
  {id:'lx2', pid:'thuc-diod-1', kind:'style',
    prompt:'Does the argument here still stand once the figures are removed, or is the figure itself the claim?',
    options:['The figure is the claim; without the balance of members nothing is being argued','The claim would stand in plain clauses: haste and passion oppose good counsel','The claim depends on picturing counsel as a person','The sentence is only an opening meant to win goodwill, and it states no claim at all'],
    correct:1, note:'Diodotus’s sentence can be said without isocolon (members of equal length), because the argument concerns counsel and not the shape of the clause.'},
  {id:'lx3', pid:'ant-3.1.1', kind:'style',
    prompt:'Does the argument here still stand once the figures are removed, or is the figure itself the claim?',
    options:['The figure is the whole case; without the ornament there is no argument from cause at all','Plain clauses would still state a death, a throw, and a name for the act','Plain clauses would leave only the father’s grief','The charge rests on a metaphor of the javelin as the killer, which plain words would remove'],
    correct:1, note:'The tetralogy’s first speech can be said without the ornament and still be a charge, because the fight is over cause, not lexis.'},
  {id:'lx4', pid:'gor-hel-10', kind:'style',
    prompt:'Does the argument here still stand once the figures are removed, or is the figure itself the claim?',
    options:['Sound and image are the claim that song is witchery; the figure is the claim','The claim would stand in plain clauses, since song is shown by argument to change belief','The rhyming members are only decoration on a claim that Gorgias proves from examples','The passage is a plain narration with no figure in it'],
    correct:0, note:'Gorgias offers an account of how the soul is moved, in the form of a figure (song as witchery); Aristotle names the same fact pathos and leaves out the drug.'},
  {id:'lx5', pid:'sal-caes-1', kind:'style',
    prompt:'Does the argument here still stand once the figures are removed, or is the figure itself the claim?',
    options:['Without the studied language of pity and horror, Caesar would have no case left to make','In plain clauses: inflict only such penalties as the laws have provided','The list of horrors is itself the claim','The claim of Caesar depends on the balance of his clauses, and would fail if said plainly'],
    correct:1, note:'Caesar can be plain, because his argument is from the law and from consequence, not from the sound of balanced members.'},
  {id:'lx6', pid:'cic-cat1-1', kind:'style',
    prompt:'The opening questions of the First Catilinarian (how much further, how much longer) are',
    options:['Only decoration, since the questions neither move the senate nor state the charge','The questions move the hearer; without them the charge remains, but it is weaker','The whole charge, since without the questions nothing at all is asserted against him','A complete proof from a necessary sign'],
    correct:1, note:'The questions amount to a charge. The fact they rest on (that the conspiracy is known) would remain as a plain assertion, and the questions are the means by which the hearer is moved to feel it.'},
  {id:'lx7', pid:'thuc-fun-2', kind:'style',
    prompt:'“Our constitution does not copy the laws of neighbouring states; we are rather a pattern to others than imitators ourselves.” If we drop the antithesis, what remains?',
    options:['Nothing remains, because the whole praise of Athens was in the turn of the antithesis','A claim about Athens that can still be judged true or false as praise','Only an image, which cannot be judged true or false','A proof that Athens is the best of cities, which the antithesis only decorates'],
    correct:1, note:'The antithesis serves the praise, and the claim (Athens is original) is still a claim when it is said without the turn.'},
  {id:'lx8', pid:'gor-hel-6', kind:'style',
    prompt:'The four aitiai are listed in parallel members. Is the list a figure in place of the argument, or an argument that happens to be figured?',
    options:['Only sound, since there are four equal clauses but not four distinct causes','A real partitio (division) dressed in isocolon: any one cause would acquit','A figure in place of the argument, since the equal members are what make the list persuasive','A narration of what happened to Helen, set out in the order of events'],
    correct:1, note:'The four causes are a division (partitio), and the equal members make them memorable; the argument would survive as a numbered list in plain prose.'},
  {id:'lx9', pid:'dem-3', kind:'style',
    prompt:'Demosthenes binds money, ships, cavalry, and a law that the force remain. If we remove any figure we hear, what remains?',
    options:['Nothing but sound, since the list of soldiers, ships, and cavalry is the whole speech','A deliberative policy argued from its parts, which can be numbered','A threat that moves the assembly by fear, with no policy left once the figure is gone','An encomium of the forces Athens already has'],
    correct:1, note:'A policy can be numbered, and that is arrangement and logos, not Gorgian witchery.'},
  {id:'lx10', pid:'aug-ddc-24', kind:'style',
    prompt:'Augustine at Caesarea wanted tears, not applause. On his account, the grand style has succeeded when',
    options:['The members are equal in length and the endings match in every period','The hearer is changed in life, though the room is silent','The hearers applaud loudly at the end','All figures of speech have been suppressed, so that only the plain style remains'],
    correct:1, note:'In DDC IV the grand style is known by the tears it draws, since style serves an office (flectere) and not display.'},
  // English tradition (public-domain quotations; sources eng_cer, eng_cem, kjv).
  {id:'eng-lx1', pid:'eng-ames-volcano', kind:'style', prompt:'Does the argument here still stand once the figures are removed, or is the figure itself the claim?', options:['The figure is the claim; the volcano makes the danger vivid but gives no reason for it','The claim would stand in plain clauses, as a cause shown from the effects that democracies have suffered','The volcano is a proof from a sign, since what conceals fire is sure to erupt','The metaphor adds nothing at all, neither fear nor force, to what is said plainly'], correct:0, note:'If we say plainly that democracy contains the causes of its own ruin, we see that a reason is still owed. The metaphor supplies the fear and not the proof.'},
  {id:'eng-lx2', pid:'eng-swift-cobwebs', kind:'style', prompt:'Does the argument here still stand once the figures are removed, or is the figure itself the claim?', options:['The figure is the claim; without the cobweb, the flies, and the wasps there is nothing left to assert','The claim would stand in plain clauses: the law catches the weak and lets the powerful go','The simile proves its claim, since cobwebs and laws are alike in every respect','The claim is about insects, and says nothing plain about how laws are applied'], correct:1, note:'The simile can be put plainly, that the law punishes small offenders and not great ones, and the plain claim can be tested against cases. So the figure states a claim; it does not replace one.'},
  {id:'eng-lx3', pid:'eng-lincoln-house-divided', kind:'style', prompt:'Does the argument here still stand once the figures are removed, or is the figure itself the claim?', options:['The figure is the claim; the house divided is all there is, and it proves nothing about the Union','The claim would stand in plain clauses: a nation cannot long remain half slave and half free','The saying from Scripture is the proof, and without it Lincoln asserts nothing','The plain claim would be that every house must one day fall, which says nothing of slavery'], correct:1, note:'Lincoln states the plain claim himself in the next sentence, that the government cannot endure half slave and half free. The saying from the Gospels gives it authority and force, but the claim is there without it.'},
  {id:'eng-lx4', pid:'eng-thoreau-railroad', kind:'style', prompt:'Does the argument here still stand once the figures are removed, or is the figure itself the claim?', options:['The figure is the claim; the crossing of the words is all there is, and nothing is asserted','The claim would stand in plain clauses: we serve our machines more than they serve us','The chiasmus proves the claim, since a reversal of words shows a reversal of things','In plain clauses the sentence only says that Thoreau dislikes traveling by train'], correct:1, note:'Put plainly, Thoreau says that men have made themselves servants of the railroad. The chiasmus makes the reversal memorable, but the claim can be stated and judged without it.'},
  // Aristotle’s own examples of style in Rhetoric III.2–4 (Freese’s English; passages arist-rhet-*).
  {id:'lx15', pid:'arist-rhet-3.3.1', kind:'style', prompt:'Aristotle names four causes of frigid style. Which cause do these phrases of Alcidamas show?', options:['Compound words, two words joined into one as in poetry','Strange words, which ordinary speech does not use','Epithets that are long, unseasonable, or too crowded','Metaphors that are farfetched, or too tragic for prose'], correct:0, note:'Rhetoric III.3.1. Each phrase contains a word made of two words (fire-colored, end-accomplishing, azure-colored), and Aristotle says that “all these appear poetical because they are compound.”'},
  {id:'lx16', pid:'arist-rhet-3.3.3c', kind:'style', prompt:'Aristotle names four causes of frigid style. Which cause do these phrases of Alcidamas show?', options:['Compound words, two words joined into one as in poetry','Strange words, which ordinary speech does not use','Epithets that are long, unseasonable, or too crowded','Metaphors that are farfetched, or too tragic for prose'], correct:2, note:'Rhetoric III.3.3. In each case Alcidamas adds words that the plain noun did not need, so Aristotle says that he uses epithets “not as a seasoning but as a regular dish”.'},
  {id:'lx17', pid:'arist-rhet-3.3.4b', kind:'style', prompt:'Aristotle names four causes of frigid style. Which cause do these phrases of Alcidamas show?', options:['Compound words, two words joined into one as in poetry','Strange words, which ordinary speech does not use','Epithets that are long, unseasonable, or too crowded','Metaphors that are farfetched, or too tragic for prose'], correct:3, note:'Rhetoric III.3.4. Philosophy is called a bulwark and the Odyssey a mirror, so each phrase transfers a name from another thing. Aristotle lists them under the fourth cause, inappropriate metaphors, and says that they “fail to produce persuasion”.'},
  {id:'lx18', pid:'arist-rhet-3.3.3a', kind:'style', prompt:'What, on Aristotle’s account, does an excess of epithets do to a speech in prose?', options:['It reveals the art, and it makes plain that the speaker is using poetry','It makes the style mean, since prose then sounds like common talk','It makes the argument stronger, since each epithet adds a true detail','It does no harm in prose, so long as each epithet is fitting in poetry'], correct:0, note:'Rhetoric III.3.3. White milk is fitting in poetry but less so in prose, and epithets used to excess “reveal the art and make it evident that it is poetry.”'},
  {id:'lx19', pid:'arist-rhet-3.3.3b', kind:'style', prompt:'Which does Aristotle judge the worse fault, a random style or an excess of epithets?', options:['Excess, because a random style only lacks merit, but excess is vicious','A random style, because it neglects the art, which excess at least shows','Neither, because both miss the mean, and so they are equal faults','A random style, because it gives the speech no foreign air at all'], correct:0, note:'Rhetoric III.3.3. Epithets may be used to a certain extent, but neglect of the mean “does more harm than speaking at random; for a random style lacks merit, but excess is vicious.”'},
  {id:'lx20', pid:'arist-rhet-3.3.3d', kind:'style', prompt:'Why, on Aristotle’s account, does tasteless poetic language make a speech obscure?', options:['Words are piled upon a hearer who already knows, and the meaning is buried','Poetic words are foreign, so the hearer cannot know what they mean at all','The hearers laugh at the style, and so they no longer attend to the matter','Poetic language is always obscure, so prose must use only proper words'], correct:0, note:'Rhetoric III.3.3. Such “idle chatter produces obscurity; for when words are piled upon one who already knows, it destroys perspicuity by a cloud of verbiage.” The fault is excess, not the use of an unusual word as such.'},
  {id:'lx21', pid:'arist-rhet-3.3.3e', kind:'style', prompt:'Why, according to Aristotle, do the epic poets use strange words?', options:['Because strange words imply dignity and self-assertion','Because the epic poets are full of noise, as the dithyrambic poets are','Because strange words make a long story clearer to its hearers','Because epic verse has no place for metaphor or for compounds'], correct:0, note:'Rhetoric III.3.3. Compound words suit the dithyrambic poets, “who are full of noise”; strange words suit the epic poets, “for they imply dignity and self-assertion”; metaphor suits the writers of iambics.'},
  {id:'lx22', pid:'arist-rhet-3.3.4a', kind:'style', prompt:'Aristotle names three ways in which a metaphor may be inappropriate. What fault does he find in a farfetched metaphor?', options:['It is obscure, as in the phrases of Gorgias he quotes','It is ridiculous, as the metaphors of the comic poets are','It is too dignified, and somewhat tragic in its effect','It is mean, and so below the dignity of its subject'], correct:0, note:'Rhetoric III.3.4. Some metaphors are ridiculous and some too dignified, “and if they are farfetched, they are obscure”. Gorgias’s “Affairs pale and bloodless” is his example.'},
  {id:'lx23', pid:'arist-rhet-3.3.4c', kind:'style', prompt:'On Aristotle’s account, why does the reproach of Gorgias make sense only of a young woman?', options:['He addresses the swallow as the woman Philomela was, not as the bird she is','The act of the swallow was disgraceful in itself, whether done by bird or woman','A swallow is a subject for comedy, and so any reproach of it is a jest','Gorgias spoke in plain words, so the reproach applies to anyone at all'], correct:0, note:'Rhetoric III.3.4. The act would be disgraceful for a young lady but not for a bird, so Gorgias reproached her “as she was, not as she is.” Aristotle calls this “the best tragic style”, that is, a style too grand for its occasion.'},
  {id:'lx24', pid:'arist-rhet-3.4.1', kind:'style', prompt:'What, on Aristotle’s account, is the difference between the simile and the metaphor about Achilles?', options:['The simile says that he rushed on like a lion; the metaphor calls him a lion','The simile calls Achilles a lion; the metaphor says that he is like a lion','The simile is a proof from likeness, but the metaphor is only an ornament','The simile belongs to prose and the metaphor to poetry, and they never mix'], correct:0, note:'Rhetoric III.4.1. Aristotle says that “there is very little difference.” Because both Achilles and the lion are courageous, the poet transfers the sense and calls Achilles a lion; with “like” the same thought is a simile.'},
  {id:'lx25', pid:'arist-rhet-3.4.2', kind:'style', prompt:'What does Aristotle say of the simile in prose?', options:['It is useful, but it should be used less often, because it is somewhat poetical','It should never be used in prose, because only proper words belong there','It is more useful than the metaphor in prose, because it states the likeness openly','It should be used often in prose, because it makes every argument clear'], correct:0, note:'Rhetoric III.4.2. “The simile is also useful in prose, but should be less frequently used, for there is something poetical about it.”'},
  {id:'lx26', pid:'arist-rhet-3.4.3a', kind:'style', prompt:'Aristotle explains this simile. In what way, according to him, was Idrieus like curs just unchained?', options:['Loosed from his bonds, he was dangerous, as curs attack and bite','Set free, he barked loudly at everyone but did no one any harm','Once released, he was faithful to whoever had set him free from prison','Let loose, he ran about without purpose, as dogs do when freed'], correct:0, note:'Rhetoric III.4.3. Aristotle explains, “for as they attack and bite, so he when loosed from his bonds was dangerous.”'},
  {id:'lx27', pid:'arist-rhet-3.4.3b', kind:'style', prompt:'Aristotle explains the last of these similes. In what way are poets’ verses like those in the bloom of youth who lack beauty?', options:['When the meter is broken up, the verses no longer look as they did, as such faces change once the bloom is gone','The verses please the young but not the old, as such faces please only those who are of the same age as themselves','The verses are admired for a time and then forgotten, as the young are praised and then grow old','The verses have sound but no sense, as such faces have color but no features worth admiring'], correct:0, note:'Rhetoric III.4.3. Aristotle explains, “neither the one after they have lost their bloom, nor the others after they have been broken up, appear the same as before.”'},
  {id:'lx28', pid:'arist-rhet-3.4.3c', kind:'style', prompt:'Aristotle explains the second simile. In what way, according to him, were the Boeotians like holm-oaks?', options:['They were beaten down by their civil strife, as holm-oaks are by knocking against each other','They were hard and stubborn, and would not bend to any argument, as the holm-oak does not bend','They were rooted in their own land and never left it, as the holm-oak stays where it grows','They were slow to grow but long to endure, as the holm-oak lives for many generations'], correct:0, note:'Rhetoric III.4.3. Aristotle explains, “for just as these are beaten down by knocking against each other, so are the Boeotians by their civil strife.”'},
  {id:'lx29', pid:'arist-rhet-3.4.3d', kind:'style', prompt:'Aristotle explains this simile. In what way was the skinny Cephisodotus like incense?', options:['He gave pleasure by wasting away, as incense does','His speeches vanished like smoke and left nothing','He was sweet in manner, as incense is sweet in smell','He was offered at every altar, as incense is offered'], correct:0, note:'Rhetoric III.4.3. Antisthenes likened him to incense, “for he also gives pleasure by wasting away.”'},
  {id:'lx30', pid:'arist-rhet-3.4.4', kind:'style', prompt:'If the goblet is called the shield of Dionysus, what does Aristotle say the shield may properly be called?', options:['The goblet of Ares','The shield of Ares','The goblet of Dionysus','The spear of Dionysus'], correct:0, note:'Rhetoric III.4.4. The goblet is to Dionysus as the shield is to Ares, and a metaphor from proportion should be reciprocal, so “the shield may properly be called the goblet of Ares.”'},
  {id:'lx31', pid:'arist-rhet-3.2.4', kind:'style', prompt:'Why, on Aristotle’s account, did the voice of Theodorus persuade where the voices of other actors did not?', options:['It seemed to be the speaker’s own voice, so the hearers did not suspect a trap','It was louder and fuller than the others, so every hearer could follow the words','It was more artful than the others, and hearers admire what is remote from them','It was used only for the grand passages, so the hearers were moved by the contrast'], correct:0, note:'Rhetoric III.2.4. Men are suspicious of one they think is laying a trap, “as they are of mixed wines”, and Theodorus’s voice “seemed to be the voice of the speaker, that of the others the voice of someone else.” So the art of style must be concealed.'},
  {id:'lx32', pid:'arist-rhet-3.2.10a', kind:'style', prompt:'Why, on Aristotle’s account, do pirates call themselves purveyors?', options:['They take their name from the better kind of thing, and so they ornament themselves','They take their name from the worse kind of thing, and so they depreciate themselves','They use a proper word, because purveying is what pirates in fact do for a living','They use a strange word, so that hearers will not understand what they really are'], correct:0, note:'Rhetoric III.2.10. To ornament a subject we take the metaphor from the better species under the same genus, and to depreciate it from the worse. The actors who call themselves “artists” and the pirates who call themselves purveyors both take the better name.'},
  {id:'lx33', pid:'arist-rhet-3.2.10b', kind:'style', prompt:'Why does Aristotle judge the line from the Telephus inappropriate?', options:['The word ruling is above the dignity of rowing, and so the artifice can be seen','The word ruling is below the dignity of a hero, and so the line depreciates him','The line uses a strange word, and so the hearers cannot tell what is meant','The line is a simile, and a simile should not be used in a tragedy at all'], correct:0, note:'Rhetoric III.2.10. The line is inappropriate “because the word ruling exceeds the dignity of the subject, and so the artifice can be seen.”'},
  {id:'lx34', pid:'arist-rhet-3.2.11', kind:'style', prompt:'Poetry and a scream are both sounds. Why, then, does Aristotle call “the scream of Calliope” a bad metaphor?', options:['A scream has no meaning, but poetry does, so the likeness fails','Calliope is a Muse, and a Muse may not be named in prose at all','The metaphor takes its name from a better kind, and so it flatters','The metaphor is too common, and so it gives no foreign air at all'], correct:0, note:'Rhetoric III.2.11. Aristotle says that “both are sounds, but the metaphor is bad, because the sounds have no meaning.” Poetry is sound with meaning, so the name does not fit it.'},
  {id:'lx35', pid:'arist-rhet-3.2.12', kind:'style', prompt:'Why, on Aristotle’s account, is gluing a good metaphor for what the cupping-glass does?', options:['The act had no name, and gluing is akin to it, since both are a kind of application','The act already had a proper name, but gluing was more vivid than that name','Gluing is a farfetched word, and a farfetched word makes a riddle hard to solve','Gluing comes from a worse kind of thing, and so it depreciates the physician'], correct:0, note:'Rhetoric III.2.12. We give names to things that have none by taking the metaphor “from what is akin and of the same kind”. “There was no name for what took place, but as in both cases there is a kind of application, he called the application of the cupping-glass gluing.”'},
  {id:'lx36', pid:'arist-rhet-3.2.14', kind:'style', prompt:'What did Simonides do when he called the mules “daughters of storm-footed steeds”?', options:['He named them from the honorable side of their parentage, and left the asses out','He named them from the dishonorable side of their parentage, as a jest at the winner','He gave them a strange word, so that no one would know the race was for mules','He used a proper word, since a mule is in fact the daughter of a horse and nothing else'], correct:0, note:'Rhetoric III.2.14. Epithets may come from what is vile or from what is more honorable, as with “the matricide” and “the avenger of his father.” Once he was paid enough, Simonides chose the horses, “and yet they were also the daughters of asses.”'},
  {id:'lx37', pid:'arist-rhet-3.2.15', kind:'style', prompt:'What, on Aristotle’s account, does Aristophanes do when he says “cloaklet” for “cloak”?', options:['He makes the thing appear less, whether it is good or bad','He makes the thing appear greater, as an epithet of honor does','He makes the thing more vivid, as a metaphor does','He uses a proper word, which makes his meaning clear'], correct:0, note:'Rhetoric III.2.15. “It is the diminutive which makes the good and the bad appear less”. Aristotle adds that the diminutive, like the epithet, must be used with due measure.'},
  // Aristotle’s own examples of style in Rhetoric III.9–11 (Freese’s English; passages arist-rhet-3.9 to 3.11).
  {id:'lx38', pid:'arist-rhet-3.9.2', kind:'style', prompt:'Why does Aristotle speak of runners who lose their breath at the goal?', options:['Hearers, like runners, wish to have the end in sight, and so a style without an end is unpleasant','A long speech tires the speaker as a race tires a runner, and so the speaker must stop before the end','The periodic style is measured like a race, and so it tires the hearer more than prose','The continuous style lets the hearer rest, as a runner rests once the race is over'], correct:0, note:'Rhetoric III.9.2. The continuous style “is unpleasant, because it is endless, for all wish to have the end in sight.” Runners show no fatigue while the end is in sight, and they lose their strength only when they reach it.'},
  {id:'lx39', pid:'arist-rhet-3.9.3', kind:'style', prompt:'Why, according to Aristotle, is the periodic style easy to remember?', options:['It has number, by which it can be measured, as verse also has','It uses familiar words, which the hearer knows already','It is joined by particles, so each part leads to the next','It sets contraries side by side, and contraries are always remembered'], correct:0, note:'Rhetoric III.9.3. Aristotle says that “the periodic style has number, which of all things is the easiest to remember; that explains why all learn verse with greater facility than prose”.'},
  {id:'lx40', pid:'arist-rhet-3.9.4', kind:'style', prompt:'What fault does Aristotle find in the line about Calydon?', options:['The period stops before the sense is complete, so the hearer may suppose what is false','The period is too long, so the hearer is left behind before the speaker reaches its end','The line is in iambics, and so its meter is out of place in prose','The line names a strange place, so the hearer cannot tell what is meant'], correct:0, note:'Rhetoric III.9.4. Aristotle says that “the period must be completed with the sense and not stop short”. A hearer who stops at the end of the first line may suppose “that Calydon is in Peloponnesus”, which is the contrary of the fact.'},
  {id:'lx41', pid:'arist-rhet-3.9.6a', kind:'style', prompt:'Why, on Aristotle’s account, do clauses that are too short make the hearer stumble?', options:['He is hurrying on toward a measure he expects, and the speaker stops him short','He cannot remember so many separate clauses, and so he loses the thread of the speech','He is left behind, as a walker is by companions who go past the turning point','He hears no contraries in them, and so he cannot tell where one clause ends'], correct:0, note:'Rhetoric III.9.6. The hearer has “a definite idea” of the measure, and “if he is checked by the speaker stopping, a sort of stumble is bound to occur”. Clauses that are too long have the opposite fault, since they leave the hearer behind.'},
  {id:'lx42', pid:'arist-rhet-3.9.6b', kind:'style', prompt:'Why does Aristotle liken long clauses to walkers who do not turn at the usual limit?', options:['The clauses leave the hearer behind, as such walkers leave their companions','The clauses make the hearer stumble, as a sudden stop makes a runner stumble','The clauses tire the speaker, as a long walk tires the one who leads it','The clauses are easy to follow, since the hearer can count them like steps'], correct:0, note:'Rhetoric III.9.6. “If too long, they leave the hearer behind, as those who do not turn till past the ordinary limit leave behind those who are walking with them.” The stumble belongs to clauses that are too short.'},
  {id:'lx43', pid:'arist-rhet-3.9.7a', kind:'style', prompt:'Aristotle says that the clauses of the periodic style are either divided or opposed. Of which kind are these?', options:['Divided, since the clauses are distinct but set no contraries against each other','Opposed, since contraries are set side by side in the two clauses','Continuous, since the sentence has no end in itself and stops only when the sense is complete','Simple, since the period consists of only one clause'], correct:0, note:'Rhetoric III.9.7. Aristotle gives this sentence as his example of clauses that are “divided”. Gathering the assemblies and instituting the contests are two acts, but neither is the contrary of the other, so the clauses are not opposed.'},
  {id:'lx44', pid:'arist-rhet-3.9.7b', kind:'style', prompt:'Aristotle says that the clauses of the periodic style are either divided or opposed. Of which kind are these?', options:['Opposed, since contraries are set side by side in the two clauses','Divided, since the clauses are distinct but set no contraries against each other','Continuous, since the sentence has no end in itself and stops only when the sense is complete','Simple, since the period consists of only one clause'], correct:0, note:'Rhetoric III.9.7. In opposed clauses “one contrary is brought close to another”. Here perishing is set against saving oneself, and Aristotle says of this and the other examples, “All these passages are examples of antithesis.”'},
  {id:'lx45', pid:'arist-rhet-3.9.7c', kind:'style', prompt:'Aristotle says that the clauses of the periodic style are either divided or opposed. Of which kind are these?', options:['Opposed, since contraries are set side by side in the two clauses','Divided, since the clauses are distinct but set no contraries against each other','Continuous, since the sentence has no end in itself and stops only when the sense is complete','Simple, since the period consists of only one clause'], correct:0, note:'Rhetoric III.9.7. Land is set against sea, and sailing against going on foot, so contraries are brought close together. Aristotle lists the sentence among his examples and says, “All these passages are examples of antithesis.”'},
  {id:'lx46', pid:'arist-rhet-3.9.8', kind:'style', prompt:'Why, on Aristotle’s account, does antithesis resemble a syllogism?', options:['Refutation is a bringing together of contraries, and antithesis also brings them together','Antithesis proves its conclusion from two premises that are true, as every syllogism must','Both have three terms, and in each the middle term joins the other two','Both please only those hearers who already know what the conclusion is'], correct:0, note:'Rhetoric III.9.8. Contraries are easily understood, “even more so when placed side by side,” and “antithesis resembles a syllogism; for refutation is a bringing together of contraries.”'},
  {id:'lx47', pid:'arist-rhet-3.9.9', kind:'style', prompt:'Aristotle gives this as an example of clauses with similar endings. How are the endings made alike?', options:['By the repetition of the same word at the end of each clause','By two inflections of one and the same word at the end','By a resemblance of one syllable only, and not of a whole word','By the same whole word at the beginning of each clause'], correct:0, note:'Rhetoric III.9.9. At the end of clauses the similarity may lie “in the last syllables, or the inflections of one and the same word, or the repetition of the same word.” Aristotle gives this sentence as his example of the repetition of a word, since the same word (“ill”) ends both clauses.'},
  {id:'lx48', pid:'arist-rhet-3.10.2', kind:'style', prompt:'Why, on Aristotle’s account, does metaphor teach us more than strange words or proper terms?', options:['Strange words we do not understand and proper terms we know already, but metaphor teaches through a likeness','Strange words are pleasant because they are new, but proper terms and metaphors are both too familiar to teach','Proper terms teach most, and metaphor only makes their meaning pleasant to hear','Metaphor is obscure, and the effort of solving it is the whole of what it teaches'], correct:0, note:'Rhetoric III.10.2. Learning easily is pleasant. Aristotle says that “we do not know the meaning of strange words, and proper terms we know already”, so metaphor “above all produces this effect”. When Homer calls old age stubble, he teaches us through the genus, “for both have lost their bloom.”'},
  {id:'lx49', pid:'arist-rhet-3.10.3', kind:'style', prompt:'Why, on Aristotle’s account, is a simile less pleasant than a metaphor?', options:['It is longer, and since it does not say that this is that, the mind does not examine it','It is shorter than the metaphor, and so it gives the mind too little to examine before it is over','It is more poetical, and so it is never fitting in prose','It hides the likeness, and so the mind cannot find what is meant'], correct:0, note:'Rhetoric III.10.3. The simile is “a metaphor differing only by the addition of a word,” and so it is less pleasant “because it is longer; it does not say that this is that, so that the mind does not even examine this.”'},
  {id:'lx50', pid:'arist-rhet-3.10.6', kind:'style', prompt:'On Aristotle’s account, what two faults must a metaphor avoid if the words are to please?', options:['It must be neither strange nor superficial','It must be neither proportional nor vivid','It must be neither drawn from poetry nor brief','It must be neither antithetical nor concise'], correct:0, note:'Rhetoric III.10.6. A strange metaphor “is difficult to take in at a glance,” and a superficial one “does not impress the hearer”. In the same section Aristotle names the three things to aim at: “metaphor, antithesis, actuality.”'},
  {id:'lx51', pid:'arist-rhet-3.10.7a', kind:'style', prompt:'Aristotle calls this a metaphor from proportion. What is the proportion?', options:['The youth are to the State as the spring is to the year','The war is to the State as the long winter is to the year','The dead are to the living as the night is to the day','Pericles is to the city as the farmer is to the field'], correct:0, note:'Rhetoric III.10.7. “Of the four kinds of metaphor the most popular are those based on proportion.” The youth stand to the State as spring stands to the year, so their loss is like a year that has lost its spring.'},
  {id:'lx52', pid:'arist-rhet-3.10.7b', kind:'style', prompt:'What, on Aristotle’s account, does Lysias add by setting “freedom” beside “valor”?', options:['A kind of antithesis, beside the metaphor and its vividness','A proper term, which makes the metaphor plain and less vivid','A farfetched metaphor, which makes the sentence obscure','A hyperbole, which shows the vehemence of a young speaker'], correct:0, note:'Rhetoric III.10.7. Aristotle says that “weep” alone would have made “a metaphor and a vivid one”, but that setting freedom beside valor “produces a kind of antithesis.”'},
  {id:'lx53', pid:'arist-rhet-3.10.7c', kind:'style', prompt:'Why, on Aristotle’s account, is the metaphor of Lycoleon vivid, though it holds only for the moment?', options:['While Chabrias is in danger the statue seems to plead for him, and the inanimate becomes animate','The statue is of bronze, and bronze lasts for all time, so the metaphor holds for all time as well','The statue is a proper term, and a proper term is always clearer than a metaphor','The phrase is an antithesis of the statue and the man, and antithesis is always vivid'], correct:0, note:'Rhetoric III.10.7. The metaphor is “for the moment, not for all time, but still vivid; for when Chabrias is in danger, the statue intercedes for him, the inanimate becomes animate”.'},
  {id:'lx54', pid:'arist-rhet-3.10.7d', kind:'style', prompt:'On what likeness, according to Aristotle, does the metaphor of the treaty as a trophy rest?', options:['Both treaty and trophy are signs of victory','Both treaty and trophy are set up after a battle','Both treaty and trophy are made of bronze or stone','Both treaty and trophy are gifts of fortune'], correct:0, note:'Rhetoric III.10.7. Aristotle says that it is a metaphor, “for both treaty and trophy are signs of victory.” The speaker adds that the treaty is the more splendid because it marks the end of the whole war.'},
  {id:'lx55', pid:'arist-rhet-3.11.2', kind:'style', prompt:'Why, on Aristotle’s account, does calling a good man “four-square” fail to set him before the eyes?', options:['It is a metaphor, but it does not express actuality','It is a proper term, and so it is not a metaphor at all','It is a farfetched metaphor, and so it is obscure','It is a simile, and so it is longer and less pleasant'], correct:0, note:'Rhetoric III.11.2. Things are set before the eyes “by words that signify actuality.” Calling him “four-square” is a metaphor, since a good man and a square are both complete, “but the phrase does not express actuality,” whereas “in full bloom” does.'},
  {id:'lx56', pid:'arist-rhet-3.11.3', kind:'style', prompt:'What, on Aristotle’s account, gives these lines of Homer their actuality?', options:['Homer speaks of lifeless things as if they were alive','Homer uses proper terms, which every hearer knows','Homer sets contraries side by side in each line','Homer adds epithets for the sake of the meter of each line'], correct:0, note:'Rhetoric III.11.3. Homer “speaks of inanimate things as if they were animate”, and his popularity is due to the actuality this creates: “the shameless stone,” “the eager spear-point,” and the rest “express actuality.”'},
  {id:'lx57', pid:'arist-rhet-3.11.5', kind:'style', prompt:'What likeness did Archytas see between an arbitrator and an altar?', options:['One who has been wronged takes refuge in either of them','Both stand in a public place where everyone can see them','Both receive gifts from those who come to them for help','Both are honored, though neither one can speak for itself'], correct:0, note:'Rhetoric III.11.5. “Archytas said that there was no difference between an arbitrator and an altar, for the wronged betakes itself to one or the other.” Aristotle gives it as a likeness in things that are far apart, which it needs sagacity to see.'},
  {id:'lx58', pid:'arist-rhet-3.11.6', kind:'style', prompt:'Why, on Aristotle’s account, does a verse like this one please?', options:['It ends contrary to the hearer’s expectation, so that he sees he has learned something','It uses a proper term, chilblains, where a poet would have used a metaphor','It sets two contraries side by side, and contraries are easily understood when placed together','It is a period complete with its sense, so it is easy to remember'], correct:0, note:'Rhetoric III.11.6. Smart sayings come “from misleading the hearer beforehand. For it becomes more evident to him that he has learnt something, when the conclusion turns out contrary to his expectation”. The hearer expected “sandals”, and the verse said “chilblains”.'},
  {id:'lx59', pid:'arist-rhet-3.11.9', kind:'style', prompt:'Why, on Aristotle’s account, does a saying please more when it is concise and antithetical?', options:['Antithesis teaches more, and conciseness gives knowledge more quickly','Antithesis is pleasant to hear, and conciseness spares the speaker’s breath','Antithesis hides the meaning, and conciseness makes the hearer search for it','Antithesis and conciseness both make the saying sound like verse'], correct:0, note:'Rhetoric III.11.9. Aristotle says that “the more concisely and antithetically they are expressed, the greater is their popularity. The reason is that antithesis is more instructive and conciseness gives knowledge more rapidly”.'},
  {id:'lx60', pid:'arist-rhet-3.11.15', kind:'style', prompt:'In the saying about the black eye, what, on Aristotle’s account, makes it a hyperbole?', options:['The great quantity, since a whole basket of mulberries is far more than one bruise','The color alone, since any comparison of one color with another is a hyperbole','The words “you would have thought,” which turn the metaphor into a simile','The comparison of a man to a fruit, which is a metaphor taken from species to species'], correct:0, note:'Rhetoric III.11.15. The saying is a metaphor “because the black eye is something purple, but the great quantity constitutes the hyperbole.” The color gives the likeness, and the amount gives the exaggeration.'},
  {id:'lx61', pid:'arist-rhet-3.11.15b', kind:'style', prompt:'Why, on Aristotle’s account, is hyperbole unbecoming in elderly speakers?', options:['It shows vehemence, which is youthful and belongs to those in a passion','It is a metaphor, and metaphor belongs only to the poets and not to orators','It is obscure, and the old have less patience with what is not clear','It is a kind of jest, and jests are fitting only for comic poets'], correct:0, note:'Rhetoric III.11.15–16. Aristotle writes, “There is something youthful about hyperboles; for they show vehemence”, so those in a passion use them most, and “it is unbecoming for elderly people to make use of them.”'}
];
const AUG_ITEMS = [
  {id:'au1', pid:'aug-ddc-12',
    prompt:'Augustine, following Cicero, names three offices: to teach, to delight, to move (docere, delectare, flectere). Which of the three is a necessity?',
    options:['To delight, since without pleasure no hearer will listen at all','To teach, since it depends on what we say, not how we say it','To move, since the applause of the hearers is the test','None, since a Christian must not use rhetoric at all'],
    correct:1, note:'In DDC IV, “To teach is a necessity, to delight is a beauty, to persuade is a triumph” (Shaw’s “to persuade” renders flectere, to move). Teaching lies in the matter, and the other two lie in the manner.'},
  {id:'au2', pid:'aug-ddc-17',
    prompt:'Which style does Augustine assign to teaching?',
    options:['The grand (grande), because teaching must move to tears','The subdued (summissum), because teaching must be understood','The temperate (temperatum), for praise and blame, which delight the hearer','No single style, since every style is fit for teaching alike'],
    correct:1, note:'The subdued style is for teaching, the temperate for delighting, and the grand for moving. The orator should mix them and should not use the grand style everywhere.'},
  {id:'au3', pid:'aug-ddc-24',
    prompt:'The sign that the grand style has done its office is',
    options:['Applause, and a name for the preacher','Tears, and a change, for the Caterva ended.','Matching endings (homoeoteleuton) in every member','The suppression of everything taken from Cicero'],
    correct:1, note:'He asked for groans, not cheers, and the Caterva story shows flectere.'},
  {id:'au4', pid:'aug-ddc-2',
    prompt:'Why may the Christian use rhetoric?',
    options:['Because winning a paid case is the end of the art','Because truth must not stand unarmed against falsehood','Because pagan eloquence is good in itself, whatever cause it serves','Because the Scriptures command the preacher to study the pagan orators'],
    correct:1, note:'In DDC IV the art is available for truth or for falsehood. Who will dare say that truth should take the field unarmed?'},
  {id:'au5', pid:'aug-ddc-17',
    prompt:'The temperate style, in Augustine’s account, is especially for',
    options:['Teaching a difficult doctrine so that it is understood','Praise and blame, which delight and make the good attractive','Moving the hearers to act at once, so that their whole life is changed','Teaching only, since delight has no place in Christian speech'],
    correct:1, note:'The temperate style serves delectare, showing the good as lovely; the grand serves flectere, moving the will to act.'},
  {id:'au6', pid:'aug-serm-1',
    prompt:'A sermon that opens by asking to be heard as God’s word in an earthen vessel is chiefly',
    options:['A display of the preacher’s own ethos, as a sophist would make','Teaching (docere) in the subdued style, with some ethos of humility','Moving (flectere) in the grand style, since it calls the hearers to tears','Delighting (delectare) in the temperate style, with praise of the evangelists'],
    correct:1, note:'The treasure in earthen vessels makes the opening one of teaching; humility shows ethos, but the office is still docere.'},
  {id:'au7', pid:'aug-ddc-12',
    prompt:'“To teach is a necessity, to delight is a beauty, to persuade is a triumph.” The three offices are',
    options:['Three different arts, belonging to three different men','One orator’s three offices, kept from Cicero for Scripture’s end','Three ends of which the Christian orator should seek only the first','Three styles, each of which must be kept apart from the other two'],
    correct:1, note:'Augustine keeps Cicero’s offices and changes the end, since the Christian orator serves a truth already found.'},
  {id:'au8', pid:'aug-ddc-24',
    prompt:'If the room shouts and does not weep, Augustine’s judgment of a grand-style sermon is that',
    options:['It has succeeded, since the shouting is the test','It has not yet done the office of moving (flectere)','It has done the office of delighting, which is the end of the grand style','It has failed, since the grand style ought to be avoided in sermons'],
    correct:1, note:'Applause can be the delight of the temperate style, but the grand style is for a change of life.'},
  {id:'au9', pid:'aug-ddc-19-38',
    prompt:'According to Augustine, how should one great matter be spoken of at different times?',
    options:['Always in the grand style, because every matter that the Christian teacher speaks of is great','Quietly when it is taught, temperately when it is urged, and powerfully when an averse mind must be turned','In the style that fits the size of the matter, so that small things are spoken quietly and great things powerfully','Always quietly, because a great matter needs proofs and not ornament or emotion'],
    correct:1, note:'On Christian Doctrine IV.19.38. Augustine says that the same important matter is treated “quietly when it is being taught, temperately when its importance is being urged, and powerfully when we are forcing a mind that is averse to the truth to turn and embrace it.” So the style follows what the speaker must do at that moment, not the size of the subject.'},
  {id:'au10', pid:'aug-ddc-20-40-night',
    prompt:'In which style, according to Augustine, does Paul write this call to cast off the works of darkness?',
    options:['The subdued style, which teaches','The temperate style, which delights','The grand style, which moves the will','No style of eloquence, since Paul did not follow the rules of rhetoric'],
    correct:1, note:'On Christian Doctrine IV.20.40. Augustine begins this run of Paul’s exhortations with the words “In the following words of the apostle we have the temperate style,” and he points out the periods of two members with which Paul closes them.'},
  {id:'au11', pid:'aug-ddc-20-42-style',
    prompt:'How, according to Augustine, does the grand style differ from the temperate?',
    options:['It uses no ornaments at all, since ornament belongs only to the temperate style','It seeks out more ornaments than the temperate style, and so it is the more decorated of the two','It differs only in length, because it speaks of great matters at greater length','It depends on strong feeling, and it takes ornaments as they come rather than seeking them'],
    correct:3, note:'On Christian Doctrine IV.20.42. The grand style “is not so much decked out with verbal ornaments as exalted into vehemence by mental emotion.” It uses nearly all the ornaments of the temperate style, “but if they do not happen to be at hand, it does not seek for them.”'},
  {id:'au12', pid:'aug-ddc-20-43',
    prompt:'In which style does Augustine place this passage of Paul to the Romans?',
    options:['The grand style, which moves the will to act','The temperate style, since the passage is full of ornament','The subdued style, since the passage explains a doctrine','A mixed style, in which no one style prevails'],
    correct:0, note:'On Christian Doctrine IV.20.43. Augustine introduces the passage with the words “in the same way”, after his first example of the grand style, and he says that Paul treats the subject “with both power and beauty.” Ornament is present, but the grand style uses ornaments as they come (IV.20.42), so the ornament does not make the passage temperate.'},
  {id:'au13', pid:'aug-ddc-21-46',
    prompt:'Why, according to Augustine, does Ambrose use the subdued style for so great a subject as the equality of the Holy Spirit with the Father and the Son?',
    options:['Because the subject is a small one, and the subdued style is for small things','Because his object requires facts and proofs, not beauty of diction or the stirring of emotion','Because his readers already believed the doctrine and needed only to be delighted by it','Because the grand style should never be used for a matter of doctrine, however great it may be'],
    correct:1, note:'On Christian Doctrine IV.21.46. Ambrose employs the subdued style “because the object he has in view demands, not beauty of diction, nor the swaying of the mind by the stir of emotion, but facts and proofs.” The subject is very great, but the office is teaching, so the style is subdued.'},
  {id:'au14', pid:'aug-ddc-21-48',
    prompt:'Why does Augustine place Ambrose’s praise of the virgin in the temperate style and not in the grand?',
    options:['Because virginity is too small a subject for the grand style','Because it teaches a doctrine that its readers did not yet understand','Because it shows those who have taken the vows what they should be, and does not urge others to take them','Because Ambrose wished to be praised for the beauty of his own writing, and so he chose ornament over force'],
    correct:2, note:'On Christian Doctrine IV.21.48. Augustine cites these passages as temperate “because their purpose is not to induce those who have not yet devoted themselves to take the vows of virginity, but to show of what character those who have taken vows ought to be.” To persuade someone to take the vows would require the grand style.'},
  {id:'au15', pid:'aug-ddc-21-50',
    prompt:'Augustine gives Ambrose’s attack on women who paint their faces as an example of which style?',
    options:['The temperate, since it is full of antitheses and other ornaments','The subdued, since it argues point by point from the nature of the act','The grand, since it calls on them passionately to change what they do','A mixture of all three styles, since no one of the three styles prevails in it'],
    correct:2, note:'On Christian Doctrine IV.21.50. Augustine says that “this eloquence calls passionately upon women to avoid tampering with their appearance by deceitful arts, and to cultivate modesty and fear,” and so “the style is neither subdued nor temperate, but majestic throughout.”'},
  {id:'au16', pid:'aug-ddc-22-51',
    prompt:'Why, according to Augustine, should the styles be mixed in one discourse?',
    options:['Because one style kept up without change fails to hold the hearer’s attention','Because Scripture mixes them, and the preacher must imitate Scripture in every point','Because each style serves only one part of the speech, and every speech has all the parts','Because a mixed discourse is shorter, and a short discourse is easier to remember'],
    correct:0, note:'On Christian Doctrine IV.22.51. “For when we keep monotonously to one style, we fail to retain the hearer\'s attention; but when we pass from one style to another, the discourse goes off more gracefully, even though it extend to greater length.”'},
  {id:'au17', pid:'aug-ddc-23-52',
    prompt:'When a knotty question must be settled in the course of a discourse, which style does Augustine say it requires?',
    options:['The grand style, since a hard question needs the greatest force','The temperate style, since ornament makes a hard question easier to bear','The subdued style, since it requires accuracy of distinction','The style in which the discourse began, since the style should not change'],
    correct:2, note:'On Christian Doctrine IV.23.52. Augustine writes that “whatever may be the style of the speech or writing, when knotty questions turn up for solution, accuracy of distinction is required, and this naturally demands the subdued style.”'},
  {id:'au18', pid:'aug-ddc-24-54',
    prompt:'What kind of change, according to Augustine, does the quiet (subdued) style make in its hearers?',
    options:['It makes them do what they knew they ought to do but were unwilling to do','It teaches what they did not know, or persuades them of what they thought incredible','It leads them to live so as to deserve praise and to avoid blame','It changes no one, since it pleases the ear and does not reach the mind or the will'],
    correct:1, note:'On Christian Doctrine IV.24.54. The quiet style changes many, “but it was to teach them what they were ignorant of, or to persuade them of what they thought incredible, not to make them do what they knew they ought to do but were unwilling to do.” That last change belongs to the grand style.'},
  {id:'au19', pid:'aug-ddc-25-55',
    prompt:'Of what, according to Augustine, does the speaker persuade his hearers in the grand style?',
    options:['That what he says is true','That his speech is elegant and ornate','To do what they are aware they ought to do, but do not','To applaud the speaker, and so to show that they have been moved'],
    correct:2, note:'On Christian Doctrine IV.25.55. In the subdued style the speaker persuades the hearers “that what he says is true; in the majestic style, he persuades them to do what they are aware they ought to do, but do not; in the temperate style, he persuades them that his speech is elegant and ornate.”'},
  {id:'au20', pid:'aug-ddc-28-61',
    prompt:'If a man cannot speak both eloquently and wisely, what does Augustine advise?',
    options:['He should speak eloquently, since eloquence makes even a weak case persuasive','He should speak wisely without eloquence, rather than eloquently without wisdom','He should not speak at all until he has learned the rules of rhetoric','He should speak in the grand style, since force makes up for a lack of wisdom'],
    correct:1, note:'On Christian Doctrine IV.28.61. “But the man who cannot speak both eloquently and wisely should speak wisely without eloquence, rather than eloquently without wisdom.” Augustine makes the same point in IV.5.7, where he quotes the teachers of rhetoric against eloquence without wisdom.'}
];
// Choosing among correct sentences. Each item gives a short context and three or four versions of the next
// sentence, all grammatical and all saying the same thing; versions[0] is the right answer.
const EFFECT_KINDS = {
  knownnew:'A sentence usually begins with what the reader already knows from the sentences before it, and it puts the new information toward the end.',
  endfocus:'The end of a sentence is the place of greatest weight, so we usually put there the word or phrase that we most want the reader to notice.',
  cohesion:'When a sentence keeps the subject of the sentence before it, the reader can follow one topic from sentence to sentence.',
  cleft:'A cleft sentence (“It was … who …”, or “What … was …”) divides one statement into two clauses, and so it singles out one part of the statement for emphasis.',
  passive:'The passive voice lets the thing acted on stand as the subject, so it can keep the topic at the beginning of the sentence and move the doer of the action to the end.',
  rhythm:'In a series we usually put the shorter or weaker members before the longer or stronger, and a periodic sentence holds its main clause until the end.'
};
const EFFECT_ITEMS = [
  {id:'re-library', kind:'knownnew', context:'The town library was built in 1902 with money from a local merchant. For sixty years it had only one room.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['That one room now holds a collection of old maps and newspapers.', 'A collection of old maps and newspapers is now held in that one room.', 'There is now a collection of old maps and newspapers in that one room.'], why:'Known information usually comes before new information. The room was named in the sentence before, so it is known, and the maps and newspapers are new. The version that begins “That one room” starts from the room and ends on the collection. The version that begins “A collection” puts the new information first. The version that begins “There is now” puts the new information in the middle and ends on the room, which the reader already knows.'},
  {id:'re-bridge', kind:'knownnew', context:'In the spring the river rose higher than anyone could remember. It carried away the old wooden bridge below the mill.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['In its place the town built a stone bridge with three arches.', 'A stone bridge with three arches was built by the town in its place.', 'The town built a stone bridge with three arches in its place.'], why:'Known information usually comes before new information. The old bridge is known from the sentence before, and the stone bridge is new. The version that begins “In its place” starts from the old bridge and ends on the new one. The version that begins “A stone bridge” puts the new bridge first and ends on the old one. The version that begins “The town built” ends on the words “in its place”, so the new bridge stands in the middle rather than at the end.'},
  {id:'re-letter', kind:'knownnew', context:'Among the papers in the attic, Maria found a letter written in 1863. Its author was her great-grandfather, a soldier in the Union army.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['The letter describes the long march north to Gettysburg.', 'The long march north to Gettysburg is described in the letter.', 'There is a description of the long march north to Gettysburg in the letter.'], why:'Known information usually comes before new information. The letter is known, and the march to Gettysburg is new. The version that begins “The letter describes” starts from the letter and ends on the march. The version that begins “The long march” puts the new information first. The version that begins “There is a description” puts the march in the middle and ends on the letter, which the reader already knows.'},
  {id:'re-tulips', kind:'knownnew', context:'Each autumn the class plants bulbs along the south wall of the school. Last year the bulbs were tulips.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['The tulips were a gift from a grower in Michigan.', 'A grower in Michigan gave the tulips as a gift.', 'It was a grower in Michigan who gave the tulips as a gift.'], why:'Known information usually comes before new information. The tulips are known, and the grower in Michigan is new. The version that begins “The tulips were” starts from the tulips and ends on the grower. The version that begins “A grower in Michigan” puts the new information first. The version that begins “It was a grower” is a cleft that stresses the grower, but it still puts the grower before the tulips, so the known information comes last.'},
  {id:'re-cassatt', kind:'knownnew', context:'The museum’s newest painting arrived last week from a private collection in Boston.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['It was painted in 1880 by Mary Cassatt.', 'Mary Cassatt painted it in 1880.', 'In 1880 Mary Cassatt painted it.'], why:'Known information usually comes before new information. The painting is known, and the painter is new. The version that begins “It was painted” is passive, so it can start from the painting and end on the painter. The version that begins “Mary Cassatt painted” puts the painter first. The version that begins “In 1880” also puts new information first, and it ends on the word “it”, which refers to the painting that the reader already knows.'},
  {id:'re-island', kind:'knownnew', context:'Ten miles off the coast lies a small rocky island.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['On the island there is a lighthouse built in 1850.', 'A lighthouse built in 1850 is on the island.', 'There is a lighthouse built in 1850 on the island.'], why:'Known information usually comes before new information. The island is known, and the lighthouse is new. The version that begins “On the island” starts from the island and ends on the lighthouse. The version that begins “A lighthouse” puts the new information first. The version that begins “There is” lets the lighthouse come after the verb, but it ends on the island, which the reader already knows.'},
  {id:'re-council', kind:'knownnew', context:'Last month the city council voted on a plan to close Elm Street to cars.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['The plan passed by a single vote.', 'By a single vote the plan passed.', 'It was by a single vote that the plan passed.'], why:'Known information usually comes before new information. The plan is known, and the narrow result of the vote is new. The version that begins “The plan passed” starts from the plan and ends on the single vote. The version that begins “By a single vote” puts the new information first. The version that begins “It was by a single vote” is a cleft that stresses the vote, but it also puts the vote first and ends on the plan, which the reader already knows.'},
  {id:'re-bees', kind:'knownnew', context:'A colony of honeybees can hold more than fifty thousand workers. In summer each worker lives only a few weeks.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['In that short life her tasks are cleaning cells, feeding the young, and gathering nectar.', 'Cleaning cells, feeding the young, and gathering nectar are her tasks in that short life.', 'Her tasks are cleaning cells, feeding the young, and gathering nectar in that short life.'], why:'Known information usually comes before new information. The short life of the worker is known, and her tasks are new. The version that begins “In that short life” starts from what the reader knows and ends on the list of tasks. The version that begins “Cleaning cells” puts the new list first. The version that begins “Her tasks are” ends on the words “in that short life”, which the reader already knows.'},
  {id:'re-gutenberg', kind:'knownnew', context:'In the 1450s Johannes Gutenberg printed a Bible with movable metal type.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['Of that Bible he printed about 180 copies.', 'About 180 copies of that Bible were printed by him.', 'He printed about 180 copies of that Bible.'], why:'Known information usually comes before new information. The Bible is known, and the number of copies is new. The version that begins “Of that Bible” starts from the Bible and ends on the number. The version that begins “About 180 copies” puts the number first. The version that begins “He printed” ends on the words “that Bible”, which the reader already knows.'},
  {id:'re-viola', kind:'knownnew', context:'This year the school play was Shakespeare’s Twelfth Night, and the hardest part to cast was Viola.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['The part of Viola went to a ninth-grader named Ana.', 'A ninth-grader named Ana got the part of Viola.', 'To a ninth-grader named Ana went the part of Viola.'], why:'Known information usually comes before new information. The part of Viola is known from the sentence before, and the student who will play it is new. The version that begins “The part of Viola” starts from the part and ends on the student. The version that begins “A ninth-grader” puts the new information first. The version that begins “To a ninth-grader” also puts the student first, and it ends on the part.'},
  {id:'re-galileo', kind:'knownnew', context:'In January 1610 Galileo turned his new telescope toward Jupiter.', prompt:'Which version puts what the reader already knows first, and the new information at the end?', versions:['Near the planet he saw several small points of light.', 'He saw several small points of light near the planet.', 'Several small points of light were seen by him near the planet.'], why:'Known information usually comes before new information. The planet is known, and the points of light are new. The version that begins “Near the planet” starts from the planet and ends on the points of light. The version that begins “He saw” ends on the planet, which the reader already knows. The version that begins “Several small points” puts the new information first.'},
  {id:'re-ring', kind:'endfocus', context:'The search for the missing ring went on all afternoon. They looked under the beds, in the garden, and even in the flour bin.', prompt:'Which version ends on the information that answers the question the passage has raised?', versions:['At last they found it in the dog’s bowl.', 'In the dog’s bowl they found it at last.', 'They found it in the dog’s bowl at last.'], why:'The end of a sentence carries the most weight, so the answer to the question that the passage raises belongs there. The passage asks where the ring was, and the version that begins “At last they found” ends on the dog’s bowl. The version that begins “In the dog’s bowl” gives the answer first and ends on the words “at last”. The version that begins “They found it” also ends on “at last”, so the answer falls in the middle.'},
  {id:'re-farm', kind:'endfocus', context:'The general had won every battle of the campaign, and the city expected him to ask for a triumph. But when he returned, he asked the senate for only one thing.', prompt:'Which version ends on the one thing that the general asked for?', versions:['He asked the senate for permission to return to his farm.', 'For permission to return to his farm he asked the senate.', 'Permission to return to his farm he asked of the senate.'], why:'The end of a sentence carries the most weight, and the passage has made the reader wait to learn what the general wanted. The version that begins “He asked the senate” ends on his request to return to his farm. The version that begins “For permission” puts the request first and ends on the senate, which the reader already knows. The version that begins “Permission to return” also puts the request first, and it ends on the senate.'},
  {id:'re-wall', kind:'endfocus', context:'Most people think that the hardest part of building a stone wall is lifting the stones.', prompt:'Which version ends on the words that correct the common opinion?', versions:['The hardest part, in fact, is choosing them.', 'Choosing them is, in fact, the hardest part.', 'In fact, choosing them is the hardest part.'], why:'The end of a sentence carries the most weight, so a correction belongs there. The hardest part is already named in the sentence before, and the new claim is that choosing the stones is harder than lifting them. The version that begins “The hardest part” ends on “choosing them”. The version that begins “Choosing them is” ends on “the hardest part”, which repeats what the reader already knows. The version that begins “In fact” also ends on “the hardest part”.'},
  {id:'re-fell', kind:'endfocus', context:'The bridge had stood for two hundred years. Engineers inspected it every spring and found nothing wrong.', prompt:'Which version ends on the strongest word?', versions:['Then, on a calm morning in May, it fell.', 'It fell, then, on a calm morning in May.', 'Then it fell on a calm morning in May.'], why:'The end of a sentence carries the most weight, and Quintilian says that, where the structure allows, it is best to end the sentence with a verb (IX.4.26). Here the fall of the bridge is the event that the passage has prepared, and the version that begins “Then, on a calm” ends on “fell”. The version that begins “It fell, then” ends on the date, which matters less than the fall. The version that begins “Then it fell” also ends on the date.'},
  {id:'re-copies', kind:'endfocus', context:'The publisher printed five thousand copies of the novel and expected them to last a year.', prompt:'Which version ends on the words that overturn the publisher’s expectation?', versions:['They were all sold within a week.', 'Within a week they were all sold.', 'Within a week all of them had been sold.'], why:'The end of a sentence carries the most weight. The publisher expected the copies to last a year, so the surprise lies in the short time it took to sell them. The version that begins “They were all sold” ends on “within a week”. The version that begins “Within a week they” puts the time first and ends on “sold”. The version that begins “Within a week all” also puts the time first and ends on “sold”.'},
  {id:'re-patience', kind:'endfocus', context:'On the day she retired, the old teacher was asked what she had learned in forty years of teaching.', prompt:'Which version ends on the answer to the question she was asked?', versions:['She said that she had learned patience.', 'Patience, she said, was what she had learned.', 'Patience was what she said she had learned.'], why:'The end of a sentence carries the most weight, so the answer belongs there. The version that begins “She said” ends on “patience”. The version that begins “Patience, she said” gives the answer first and ends on “what she had learned”, which repeats the question. The version that begins “Patience was what” also gives the answer first and ends on the question.'},
  {id:'re-napoleon', kind:'endfocus', context:'Many people believe that Napoleon was unusually short.', prompt:'Which version ends on the words that correct the common belief?', versions:['For a Frenchman of his time, he was of about average height.', 'He was, in height, about average for a Frenchman of his time.', 'His height was about average for a Frenchman of his time.'], why:'The end of a sentence carries the most weight, so a correction belongs there. The version that begins “For a Frenchman” ends on “about average height”, which answers the belief that he was short. The version that begins “He was, in height” ends on the words “his time”, so the correction falls in the middle. The version that begins “His height was” also ends on “his time”.'},
  {id:'re-elm', kind:'endfocus', context:'For years the town tried to save the old elm on the green. Arborists cabled its limbs and treated its bark.', prompt:'Which version ends on the strongest word?', versions:['Last summer, despite all their care, the elm died.', 'The elm died last summer, despite all their care.', 'Despite all their care, the old elm died last summer.'], why:'The end of a sentence carries the most weight, and here the death of the elm is the event that the passage has prepared. The version that begins “Last summer” ends on “died”. The version that begins “The elm died” ends on the care given to the tree, which the reader already knows. The version that begins “Despite all” ends on the time, which matters less than the death of the tree.'},
  {id:'re-thief', kind:'endfocus', context:'For months the paintings in the gallery had been disappearing one by one. The police suspected an outsider.', prompt:'Which version ends on the answer to the question the passage has raised?', versions:['The thief, it turned out, was the night guard.', 'The night guard, it turned out, was the thief.', 'It turned out that the night guard was the thief.'], why:'The end of a sentence carries the most weight. The passage asks who the thief was, and the version that begins “The thief, it turned out” ends on the night guard. The version that begins “The night guard” gives the answer first and ends on “the thief”, which the reader already knows. The version that begins “It turned out” also ends on “the thief”.'},
  {id:'re-together', kind:'endfocus', context:'Before the race, the coach told the team that only one thing mattered.', prompt:'Which version ends on the one thing that the coach said mattered?', versions:['The one thing that mattered, he said, was finishing together.', 'Finishing together, he said, was the one thing that mattered.', 'He said that finishing together was the one thing that mattered.'], why:'The end of a sentence carries the most weight. The sentence before has made the reader wait to learn what mattered, and the version that begins “The one thing” ends on “finishing together”. The version that begins “Finishing together” gives the answer first and ends on the words “the one thing that mattered”, which repeat the sentence before. The version that begins “He said” also ends on those words.'},
  {id:'re-rain', kind:'endfocus', context:'The drought lasted three summers. The wells went dry, and the farmers sold their cattle.', prompt:'Which version ends on the word that the whole passage has been waiting for?', versions:['In the fourth spring, at last, came the rain.', 'The rain came at last in the fourth spring.', 'At last the rain came in the fourth spring of the drought.'], why:'The end of a sentence carries the most weight, and in a passage about drought the rain is what the reader is waiting for. The version that begins “In the fourth spring” ends on “the rain”. The version that begins “The rain came” ends on the time. The version that begins “At last the rain” also ends on the time.'},
  {id:'re-everett', kind:'endfocus', context:'At Gettysburg, Lincoln spoke after Edward Everett, who had spoken for two hours.', prompt:'Which version ends on the words that make the contrast with Everett?', versions:['Lincoln, when his turn came, spoke for about two minutes.', 'Lincoln spoke for about two minutes when his turn came.', 'For about two minutes, when his turn came, Lincoln spoke.'], why:'The end of a sentence carries the most weight, and here the point of the passage is the contrast between two hours and two minutes. The version that begins “Lincoln, when his turn came” ends on “about two minutes”. The version that begins “Lincoln spoke” ends on “when his turn came”, which the reader already knows. The version that begins “For about two minutes” puts the contrast first and ends on “Lincoln spoke”.'},
  {id:'re-curie', kind:'cohesion', context:'Marie Curie was born in Warsaw in 1867 and studied physics in Paris.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['In 1903 she shared the Nobel Prize in Physics with Pierre Curie and Henri Becquerel.', 'In 1903 the Nobel Prize in Physics was shared by her, Pierre Curie, and Henri Becquerel.', 'In 1903 Pierre Curie and Henri Becquerel shared the Nobel Prize in Physics with her.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The paragraph is about Marie Curie, and she is the subject of the sentence before. The version that begins “In 1903 she shared” keeps her as the subject. The version that begins “In 1903 the Nobel Prize” makes the prize the subject. The version that begins “In 1903 Pierre Curie” makes the two men the subject, so the paragraph turns away from her.'},
  {id:'re-townhall', kind:'cohesion', context:'The new town hall opened in September.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['It was designed by an architect from Chicago.', 'An architect from Chicago designed it.', 'Its designer was an architect from Chicago.', 'There was an architect from Chicago who designed it.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The town hall is the subject of the sentence before. The version that begins “It was designed” is passive, so the town hall stays the subject. The version that begins “An architect” makes the architect the subject. The version that begins “Its designer” makes the designer the subject, and the version that begins “There was” turns the sentence toward the architect as well.'},
  {id:'re-hadrian', kind:'cohesion', context:'Hadrian’s Wall runs for about seventy-three miles across northern England.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['It was begun in 122 at the order of the emperor Hadrian.', 'The emperor Hadrian ordered it begun in 122.', 'In 122 the emperor Hadrian gave the order to begin it.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The wall is the subject of the sentence before. The version that begins “It was begun” keeps the wall as the subject. The version that begins “The emperor Hadrian” makes the emperor the subject. The version that begins “In 122” also makes the emperor the subject.'},
  {id:'re-dog', kind:'cohesion', context:'Our neighbor’s dog barks at every car that passes.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['It barks loudest of all at the mail carrier.', 'The mail carrier gets the loudest barking of all.', 'Its loudest barks are for the mail carrier.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The dog is the subject of the sentence before. The version that begins “It barks” keeps the dog as the subject. The version that begins “The mail carrier” makes the mail carrier the subject. The version that begins “Its loudest barks” makes the barks the subject.'},
  {id:'re-kingfisher', kind:'cohesion', context:'The kingfisher hunts from a perch above the water.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['It feeds mostly on small fish, which it catches in a quick dive.', 'Small fish, caught in a quick dive, are its usual food.', 'Its usual food is small fish, which it catches in a quick dive.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The kingfisher is the subject of the sentence before. The version that begins “It feeds” keeps the bird as the subject. The version that begins “Small fish” makes the fish the subject. The version that begins “Its usual food” makes the food the subject of the main clause, although the bird returns as the subject of the clause at the end.'},
  {id:'re-committee', kind:'cohesion', context:'The committee met on Monday to review the budget.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['It recommended a cut of ten percent to every department.', 'A cut of ten percent to every department was its recommendation.', 'Its advice was a ten percent cut to every department.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The committee is the subject of the sentence before. The version that begins “It recommended” keeps the committee as the subject. The version that begins “A cut of ten percent” makes the cut the subject. The version that begins “Its advice” makes the advice the subject.'},
  {id:'re-franklin', kind:'cohesion', context:'Benjamin Franklin left school at the age of ten.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['At twelve he was apprenticed to his brother James, a printer.', 'At twelve his brother James, a printer, took him on as an apprentice.', 'His brother James, a printer, became his master when he was twelve.'], why:'A paragraph is easier to follow when its sentences keep the same subject. Franklin is the subject of the sentence before. The version that begins “At twelve he” is passive, so Franklin stays the subject. The version that begins “At twelve his brother” makes James the subject. The version that begins “His brother James” also makes James the subject.'},
  {id:'re-titanic', kind:'cohesion', context:'The ship left Southampton on April 10, 1912, on its first voyage.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['Four days later it struck an iceberg.', 'Four days later an iceberg was struck by it.', 'Four days later there was a collision between it and an iceberg.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The ship is the subject of the sentence before. The version that begins “Four days later it” keeps the ship as the subject. The version that begins “Four days later an iceberg” is passive, and it makes the iceberg the subject, although the reader is following the ship. The version that begins “Four days later there” turns the sentence toward the collision, and the ship appears only in the words “between it and an iceberg”.'},
  {id:'re-violin', kind:'cohesion', context:'The violin in the museum’s glass case was made in Cremona in 1715.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['For forty years it belonged to a famous player.', 'A famous player owned it for forty years.', 'Its owner for forty years was a famous player.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The violin is the subject of the sentence before. The version that begins “For forty years it” keeps the violin as the subject. The version that begins “A famous player” makes the player the subject. The version that begins “Its owner” makes the owner the subject.'},
  {id:'re-elena', kind:'cohesion', context:'Elena reached the station just as the train pulled in.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['She saw her brother waiting on the platform.', 'Her brother was waiting on the platform, and she saw him.', 'On the platform her brother was waiting, and she saw him.'], why:'A paragraph is easier to follow when its sentences keep the same subject. Elena is the subject of the sentence before. The version that begins “She saw” keeps her as the subject. The version that begins “Her brother” makes the brother the subject of the first clause, and Elena returns only in the second. The version that begins “On the platform” also makes the brother the subject of the first clause.'},
  {id:'re-comet', kind:'cohesion', context:'The comet was first seen by an amateur astronomer in March.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['By May it could be seen without a telescope.', 'By May people could see it without a telescope.', 'By May no telescope was needed to see it.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The comet is the subject of the sentence before, which is passive. The version that begins “By May it” keeps the comet as the subject. The version that begins “By May people” makes people the subject. The version that begins “By May no telescope” makes the telescope the subject.'},
  {id:'re-california', kind:'cohesion', context:'In the seventeenth century, many mapmakers drew California as an island.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['They copied the error from one another for more than a hundred years.', 'The error was copied from one map to another for more than a hundred years.', 'For over a century the error passed from mapmaker to mapmaker.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The mapmakers are the subject of the sentence before. The version that begins “They copied” keeps them as the subject. The version that begins “The error was copied” makes the error the subject. The version that begins “For over a century” also makes the error the subject.'},
  {id:'re-orchestra', kind:'cohesion', context:'The orchestra had rehearsed the symphony for six weeks.', prompt:'Which version keeps the same subject as the sentence before it?', versions:['On the night of the concert it played without a single mistake.', 'On the night of the concert its playing was flawless.', 'On the night of the concert there was not a single mistake in its playing.'], why:'A paragraph is easier to follow when its sentences keep the same subject. The orchestra is the subject of the sentence before. The version that begins “On the night of the concert it played” keeps the orchestra as the subject. The version that begins “On the night of the concert its playing” makes the playing the subject. The version that begins “On the night of the concert there” turns the sentence toward the mistakes, and the orchestra appears only in the word “its”.'},
  {id:'re-mate', kind:'cleft', context:'Everyone assumed that the captain had given the order to turn back. The ship’s log tells a different story.', prompt:'Which version gives the most weight to the person who gave the order?', versions:['It was the first mate who gave the order to turn back.', 'The first mate gave the order to turn back.', 'It was the order to turn back that the first mate gave.', 'What the first mate gave was the order to turn back.'], why:'An it-cleft gives the most weight to the part that follows “It was”. The passage expects the captain, so the person who gave the order is the point of contrast, and the version that begins “It was the first mate” singles out the first mate. The version that begins “The first mate gave” names the first mate as the plain subject, which receives less weight than the stressed part of a cleft. The version that begins “It was the order” stresses the order, which the reader already knows. The version that begins “What the first mate gave” also puts the weight on the order.'},
  {id:'re-theater', kind:'cleft', context:'The town has always credited the mayor with saving the old theater.', prompt:'Which version gives the most weight to the people who saved the theater?', versions:['It was a group of high school students who raised the money to save it.', 'A group of high school students raised the money to save it.', 'It was the money to save it that a group of high school students raised.', 'What a group of high school students raised was the money to save it.'], why:'An it-cleft gives the most weight to the part that follows “It was”. The town credits the mayor, so the students are the point of contrast, and the version that begins “It was a group” singles them out. The version that begins “A group of high school” names them as the plain subject, which receives less weight than the stressed part of a cleft. The version that begins “It was the money” stresses the money. The version that begins “What a group” also puts the weight on the money, at the end.'},
  {id:'re-key', kind:'cleft', context:'The detective searched the whole room for the stolen papers, but he found something else.', prompt:'Which version gives the most weight to what the detective found?', versions:['It was a second key that he found under the carpet.', 'He found a second key under the carpet.', 'It was under the carpet that he found a second key.', 'Where he found a second key was under the carpet.'], why:'An it-cleft gives the most weight to the part that follows “It was”. The passage says that the detective found something other than the papers, so the reader wants to know what it was, and the version that begins “It was a second key” stresses the key. The version that begins “He found” puts the key in the middle and ends on the carpet. The version that begins “It was under the carpet” stresses the place. The version that begins “Where he found” also stresses the place, which it puts at the end.'},
  {id:'re-menu', kind:'cleft', context:'The students expected the new principal to change the schedule and the dress code.', prompt:'Which version gives the most weight to the thing that she changed first?', versions:['What she changed first was the lunch menu.', 'She changed the lunch menu first.', 'It was she who changed the lunch menu first.'], why:'A what-cleft puts the stressed part at the end, after “was”. The students expected the schedule or the dress code, so the lunch menu is the surprise, and the version that begins “What she changed” ends on it. The version that begins “She changed” puts the lunch menu in the middle and ends on “first”. The version that begins “It was she” stresses the principal, whom the reader already knows.'},
  {id:'re-wiring', kind:'cleft', context:'The insurance company assumed that the fire had started in the kitchen.', prompt:'Which version gives the most weight to the true cause of the fire?', versions:['It was the old wiring in the attic that started the fire.', 'The old wiring in the attic started the fire.', 'It was the fire that the old wiring in the attic started.', 'What the old wiring in the attic started was the fire.'], why:'An it-cleft gives the most weight to the part that follows “It was”. The company assumed a cause in the kitchen, so the true cause is the point of contrast, and the version that begins “It was the old wiring” singles it out. The version that begins “The old wiring” names the cause as the plain subject, which receives less weight than the stressed part of a cleft. The version that begins “It was the fire” stresses the fire, which the reader already knows. The version that begins “What the old wiring” also puts the weight on the fire.'},
  {id:'re-floor', kind:'cleft', context:'Visitors to the cathedral usually notice the tall windows first.', prompt:'Which version gives the most weight to the floor, in contrast with the windows?', versions:['It was the floor, however, that received the most care from the builders.', 'The floor, however, received the most care from the builders.', 'It was from the builders, however, that the floor received the most care.'], why:'An it-cleft gives the most weight to the part that follows “It was”. The version that begins “It was the floor” stresses the floor, which is the point of contrast with the windows. The version that begins “The floor, however” names the floor as the plain subject, which receives less weight than the stressed part of a cleft. The version that begins “It was from the builders” stresses the builders, who are not in contrast with anything in the passage.'},
  {id:'re-tempest', kind:'cleft', context:'The class had read three plays by Shakespeare, and most students liked Macbeth best.', prompt:'Which version gives the most weight to the play that Jonah preferred?', versions:['It was The Tempest, however, that Jonah preferred to all of them.', 'Jonah, however, preferred The Tempest to all of them.', 'It was Jonah, however, who preferred The Tempest to all of them.'], why:'An it-cleft gives the most weight to the part that follows “It was”. The version that begins “It was The Tempest” stresses the play, which is the point of contrast with Macbeth. The version that begins “Jonah, however” puts the play in the middle of the sentence, so it receives less weight. The version that begins “It was Jonah” stresses Jonah rather than the play.'},
  {id:'re-archive', kind:'cleft', context:'Most of the letters in the archive are from merchants and bankers.', prompt:'Which version gives the most weight to the writer, in contrast with the merchants and bankers?', versions:['It was a farmer’s wife, though, who wrote the most valuable one.', 'A farmer’s wife, though, wrote the most valuable one.', 'It was the most valuable one, though, that a farmer’s wife wrote.', 'What a farmer’s wife wrote, though, was the most valuable one.'], why:'An it-cleft gives the most weight to the part that follows “It was”. The version that begins “It was a farmer’s wife” stresses the writer, who is the point of contrast with the merchants and bankers. The version that begins “A farmer’s wife” names her as the plain subject, which receives less weight than the stressed part of a cleft. The version that begins “It was the most valuable” stresses the letter rather than its writer. The version that begins “What a farmer’s wife” also puts the weight on the letter, at the end.'},
  {id:'re-wolf', kind:'cleft', context:'In the story, the whole village believed that a wolf had been killing the sheep.', prompt:'Which version gives the most weight to the true killer?', versions:['It was the shepherd’s own dog that had been killing them.', 'The shepherd’s own dog had been killing them.', 'It was the sheep that the shepherd’s own dog had been killing.', 'What the shepherd’s own dog had been killing was the sheep.'], why:'An it-cleft gives the most weight to the part that follows “It was”. The village believed that a wolf was the killer, so the true killer is the point of contrast, and the version that begins “It was the shepherd’s” singles out the dog. The version that begins “The shepherd’s own dog” names the dog as the plain subject, which receives less weight than the stressed part of a cleft. The version that begins “It was the sheep” stresses the sheep, which the reader already knows. The version that begins “What the shepherd’s” also puts the weight on the sheep.'},
  {id:'re-greeks', kind:'cleft', context:'Columbus is often said to have proved that the earth is round.', prompt:'Which version gives the most weight to the people who had shown it?', versions:['It was the Greeks, centuries earlier, who had shown that the earth is round.', 'The Greeks, centuries earlier, had shown that the earth is round.', 'It was centuries earlier that the Greeks had shown that the earth is round.', 'What the Greeks had shown, centuries earlier, was that the earth is round.'], why:'An it-cleft gives the most weight to the part that follows “It was”. The passage credits Columbus, so the Greeks are the point of contrast, and the version that begins “It was the Greeks” singles them out. The version that begins “The Greeks, centuries” names them as the plain subject, which receives less weight than the stressed part of a cleft. The version that begins “It was centuries earlier” stresses the time rather than the people. The version that begins “What the Greeks” puts the weight on the roundness of the earth, which the reader already knows.'},
  {id:'re-declaration', kind:'passive', context:'The Declaration of Independence is kept in the National Archives in Washington.', prompt:'Which version begins with the Declaration, the topic of the passage, and ends on the man who drafted it?', versions:['Its first draft was written in June 1776 by Thomas Jefferson.', 'Thomas Jefferson wrote its first draft in June 1776.', 'In June 1776 Thomas Jefferson wrote its first draft.', 'In June 1776 its first draft was written by Thomas Jefferson.'], why:'The passive voice lets the thing acted on stand as the subject, so the Declaration can stay at the head of the sentence while the writer moves to the end. The version that begins “Its first draft” does both. The version that begins “Thomas Jefferson” puts the writer first. The version that begins “In June 1776 Thomas” also puts the writer near the beginning, and it ends on the draft. The version that begins “In June 1776 its” is passive and ends on the writer, but it begins with the date rather than the Declaration.'},
  {id:'re-iwojima', kind:'passive', context:'The photograph of the flag-raising on Iwo Jima has been reproduced on stamps and on statues. Few people remember who took it.', prompt:'Which version ends on the answer to the question the passage has raised?', versions:['It was taken by Joe Rosenthal, a photographer for the Associated Press.', 'Joe Rosenthal, a photographer for the Associated Press, took it.', 'A photographer for the Associated Press, Joe Rosenthal, took it.'], why:'The passive voice moves the doer of the action to the end, where it receives the most weight. The passage asks who took the photograph, and the version that begins “It was taken” ends on the photographer. The version that begins “Joe Rosenthal” gives the answer first and ends on “took it”. The version that begins “A photographer” also gives the answer first.'},
  {id:'re-penicillin', kind:'passive', context:'Penicillin has saved millions of lives.', prompt:'Which version keeps penicillin, the topic, both as the subject and at the beginning of the sentence?', versions:['It was discovered in a London laboratory in 1928 by Alexander Fleming.', 'Alexander Fleming discovered it in a London laboratory in 1928.', 'In 1928 Alexander Fleming discovered it in a London laboratory.', 'In a London laboratory in 1928 it was discovered by Alexander Fleming.'], why:'The passive voice lets the thing acted on stand as the subject. The version that begins “It was discovered” makes penicillin the subject and puts it first. The version that begins “Alexander Fleming” makes Fleming the subject. The version that begins “In 1928” also makes Fleming the subject. The version that begins “In a London laboratory” is passive and keeps penicillin as the subject, but it puts the place and the date before it.'},
  {id:'re-window', kind:'passive', context:'The museum’s front window was found shattered on Monday morning.', prompt:'The person who broke the window is unknown. Which version avoids making an unknown person the subject of the sentence?', versions:['Nothing, however, had been taken.', 'No one, however, had taken anything.', 'However, no one had taken anything.'], why:'The passive voice lets us leave out a doer who is unknown, and so the sentence can stay with the museum and its things. The version that begins “Nothing” is passive, and its subject is “nothing”, that is, none of the museum’s things. The version that begins “No one” makes an unknown person the subject. The version that begins “However” also makes an unknown person the subject.'},
  {id:'re-vaccine', kind:'passive', context:'Researchers tested the new vaccine on thirty thousand volunteers.', prompt:'Which version keeps the volunteers as the subject?', versions:['Half of them were given the vaccine, and half were given a placebo.', 'The researchers gave half of them the vaccine and half a placebo.', 'The vaccine was given to half of them, and a placebo to the other half.'], why:'The passive voice lets the people acted on stand as the subject. The version that begins “Half of them” makes the volunteers the subject of both clauses. The version that begins “The researchers” makes the researchers the subject. The version that begins “The vaccine was given” is also passive, but it makes the vaccine and the placebo the subjects, not the volunteers.'},
  {id:'re-bell', kind:'passive', context:'The town’s bell was cast in 1790 and hung in the tower of the meetinghouse.', prompt:'Which version keeps the bell as the subject, as in the sentence before?', versions:['In 1855 it was cracked by a fire.', 'A fire cracked it in 1855.', 'In 1855 a fire cracked it.', 'In 1855 there was a fire that cracked it.'], why:'The passive voice lets the thing acted on stand as the subject. The version that begins “In 1855 it” keeps the bell as the subject. The version that begins “A fire” makes the fire the subject. The version that begins “In 1855 a fire” also makes the fire the subject. The version that begins “In 1855 there” turns the sentence toward the fire.'},
  {id:'re-blacksmith', kind:'passive', context:'The bridge was designed by a famous engineer from New York.', prompt:'Which version keeps the bridge as the subject, as in the sentence before, and ends on its surprising builder?', versions:['It was built, however, by a local blacksmith who had never studied engineering.', 'A local blacksmith who had never studied engineering, however, built it.', 'However, a local blacksmith who had never studied engineering built it.', 'There was, however, a local blacksmith who had never studied engineering, and he built it.'], why:'The passive voice keeps the thing acted on as the subject and moves the doer of the action to the end, where it receives the most weight. The version that begins “It was built” does both. The version that begins “A local blacksmith” makes the blacksmith the subject and ends on “built it”. The version that begins “However” also makes the blacksmith the subject. The version that begins “There was” turns the sentence toward the blacksmith and ends on “built it”.'},
  {id:'re-parks', kind:'passive', context:'Rosa Parks worked as a seamstress in Montgomery, Alabama.', prompt:'Which version keeps Rosa Parks as the subject?', versions:['In 1999 she was awarded the Congressional Gold Medal.', 'In 1999 Congress awarded her its Gold Medal.', 'In 1999 the Congressional Gold Medal was awarded to her.'], why:'The passive voice lets the person acted on stand as the subject. The version that begins “In 1999 she” keeps Rosa Parks as the subject. The version that begins “In 1999 Congress” makes Congress the subject. The version that begins “In 1999 the Congressional” is also passive, but it makes the medal the subject.'},
  {id:'re-petition', kind:'passive', context:'The old law was repealed in 1920, although no one in the legislature had wanted to touch it.', prompt:'Which version begins with the change, which the reader already knows, and ends on what brought it about?', versions:['The change was forced by a petition signed by ten thousand farmers.', 'A petition signed by ten thousand farmers forced the change.', 'Ten thousand farmers signed a petition that forced the change.', 'It was a petition signed by ten thousand farmers that forced the change.'], why:'The passive voice keeps the known thing at the head of the sentence and moves the cause to the end. The version that begins “The change was forced” does both. The version that begins “A petition” puts the cause first and ends on the change. The version that begins “Ten thousand farmers” also puts the cause first. The version that begins “It was a petition” is a cleft that stresses the petition, but it puts the petition before the change.'},
  {id:'re-essay', kind:'passive', context:'Every year the school gives a prize for the best essay on local history.', prompt:'Which version keeps the prize as the subject and ends on this year’s winner?', versions:['This year it was won by a student who had arrived from Vietnam only two years before.', 'This year a student who had arrived from Vietnam only two years before won it.', 'A student who had arrived from Vietnam only two years before won it this year.', 'This year the winner was a student who had arrived from Vietnam only two years before.'], why:'The passive voice keeps the thing acted on as the subject and moves the doer of the action to the end. The version that begins “This year it” does both. The version that begins “This year a student” makes the student the subject and ends on “won it”. The version that begins “A student” also makes the student the subject. The version that begins “This year the winner” ends on the student, but it makes the winner the subject, not the prize.'},
  {id:'re-rosetta', kind:'passive', context:'The Rosetta Stone was found in Egypt in 1799 by French soldiers.', prompt:'Which version begins with the stone, the topic of the passage, and ends on the man who deciphered it?', versions:['Its hieroglyphs were deciphered in 1822 by Jean-François Champollion.', 'Jean-François Champollion deciphered its hieroglyphs in 1822.', 'In 1822 Jean-François Champollion deciphered its hieroglyphs.', 'In 1822 its hieroglyphs were deciphered by Jean-François Champollion.'], why:'The passive voice lets the thing acted on stand as the subject and moves the doer of the action to the end. The version that begins “Its hieroglyphs” does both. The version that begins “Jean-François” puts the decipherer first. The version that begins “In 1822 Jean-François” also puts him near the beginning, and it ends on the hieroglyphs. The version that begins “In 1822 its” is passive and ends on Champollion, but it begins with the date rather than the stone.'},
  {id:'re-house', kind:'rhythm', context:'The old house needed a great deal of work.', prompt:'Which version puts the members of the series in order from shortest to longest?', versions:['It needed paint, new windows, and a roof that would keep out the winter rain.', 'It needed a roof that would keep out the winter rain, new windows, and paint.', 'It needed new windows, a roof that would keep out the winter rain, and paint.'], why:'In a series we usually put the shorter members before the longer, so that the sentence grows toward its end. The version that ends “keep out the winter rain” moves from the shortest member to the longest. The version that ends “new windows, and paint” puts the longest member first and ends on the shortest. The version that ends “winter rain, and paint” puts the longest member in the middle and ends on the shortest.'},
  {id:'re-college', kind:'rhythm', context:'The founders of the college wanted their students to learn three things.', prompt:'Which version puts the members of the series in order from shortest to longest?', versions:['They wanted them to learn Latin, mathematics, and the habit of thinking for themselves.', 'They wanted them to learn the habit of thinking for themselves, mathematics, and Latin.', 'They wanted them to learn mathematics, the habit of thinking for themselves, and Latin.'], why:'In a series we usually put the shorter members before the longer, so that the sentence grows toward its end. The version that ends “thinking for themselves” moves from the shortest member to the longest. The version that ends “mathematics, and Latin” puts the longest member first and ends on the shortest. The version that ends “themselves, and Latin” puts the longest member in the middle and ends on the shortest.'},
  {id:'re-soldiers', kind:'rhythm', context:'At the end of the war the soldiers came home.', prompt:'Which version puts the members of the series in order from shortest to longest?', versions:['They came home tired, hungry, and uncertain of what they would find.', 'They came home uncertain of what they would find, tired, and hungry.', 'They came home hungry, uncertain of what they would find, and tired.'], why:'In a series we usually put the shorter members before the longer, so that the sentence grows toward its end. The version that ends “what they would find” moves from the shortest member to the longest. The version that ends “tired, and hungry” puts the longest member first. The version that ends “find, and tired” puts the longest member in the middle and ends on a short one.'},
  {id:'re-tax', kind:'rhythm', context:'The speaker described what the new tax would do to the small farmers of the county.', prompt:'Which version rises in force, so that no weaker word follows a stronger one?', versions:['It would burden them, impoverish them, and finally drive them from their land.', 'It would drive them from their land, impoverish them, and finally burden them.', 'It would impoverish them, drive them from their land, and finally burden them.'], why:'Quintilian says that “sentences rise and grow in force”, and he warns against making a weaker word follow a stronger one (IX.4.23). Driving the farmers from their land is worse than impoverishing them, and impoverishing them is worse than burdening them. The version that ends “drive them from their land” rises from the weakest to the strongest. The version that ends “impoverish them, and finally burden them” falls from the strongest to the weakest. The version that ends “their land, and finally burden them” puts the strongest in the middle and ends on the weakest.'},
  {id:'re-flood', kind:'rhythm', context:'The flood destroyed much of the valley.', prompt:'Which version rises in force, so that no weaker member follows a stronger one?', versions:['It ruined the crops, it destroyed the houses, and it took the lives of eleven people.', 'It took the lives of eleven people, it destroyed the houses, and it ruined the crops.', 'It destroyed the houses, it took the lives of eleven people, and it ruined the crops.'], why:'Quintilian says that “sentences rise and grow in force”, and he warns against making a weaker word follow a stronger one (IX.4.23). The loss of eleven lives is the gravest of the three, and the loss of the houses is graver than the loss of the crops. The version that ends “the lives of eleven people” rises from the least to the gravest. The version that ends “houses, and it ruined the crops” falls from the gravest to the least. The version that ends “people, and it ruined the crops” puts the gravest in the middle and ends on the least.'},
  {id:'re-settlers', kind:'rhythm', context:'The settlers who founded the town brought very little with them.', prompt:'Which version puts the members of the series in order from shortest to longest?', versions:['They brought their seed, their tools, and the hope of governing themselves by their own laws.', 'They brought the hope of governing themselves by their own laws, their tools, and their seed.', 'They brought their tools, the hope of governing themselves by their own laws, and their seed.'], why:'In a series we usually put the shorter members before the longer, so that the sentence grows toward its end. The version that ends “by their own laws” moves from the shortest member to the longest. The version that ends “their tools, and their seed” puts the longest member first and ends on a short one. The version that ends “laws, and their seed” puts the longest member in the middle and ends on a short one.'},
  {id:'re-school', kind:'rhythm', context:'The town had waited two years for the new school to open.', prompt:'Which version holds the main clause until the end, so that the sentence is periodic?', versions:['When the doors finally opened, after two winters of delay and a dozen meetings of the council, the children ran in.', 'The children ran in when the doors finally opened, after two winters of delay and a dozen meetings of the council.', 'When the doors finally opened, the children ran in, after two winters of delay and a dozen meetings of the council.'], why:'A periodic sentence holds its main clause until the end, so that the sense is complete only when the sentence closes. In this sentence the main clause is “the children ran in”. The version that ends “the children ran in” holds it until the end. The version that begins “The children ran in” is loose, because it states the main clause first. The version that begins “When the doors finally opened, the children” puts the main clause in the middle and then adds the long phrase about the delay, so the sentence goes on after its sense is complete.'},
  {id:'re-captain', kind:'rhythm', context:'The captain had kept up the spirits of the crew through forty days at sea.', prompt:'Which version holds the main clause until the end, so that the sentence is periodic?', versions:['On the forty-first morning, when the coast of Ireland rose out of the fog, he at last allowed himself to sleep.', 'He at last allowed himself to sleep on the forty-first morning, when the coast of Ireland rose out of the fog.', 'On the forty-first morning he at last allowed himself to sleep, when the coast of Ireland rose out of the fog.'], why:'A periodic sentence holds its main clause until the end, so that the sense is complete only when the sentence closes. In this sentence the main clause is “he at last allowed himself to sleep”. The version that begins “On the forty-first morning, when” holds the main clause until the end. The version that begins “He at last” is loose, because it states the main clause first. The version that begins “On the forty-first morning he” puts the main clause in the middle, so the sentence goes on after its sense is complete.'},
  {id:'re-summit', kind:'rhythm', context:'The climbers reached the summit late in the afternoon.', prompt:'Which version puts the short clause first, so that the sentence grows toward its end?', versions:['Though they were tired, they began the long descent across the ice to their camp that same evening.', 'They began the long descent across the ice to their camp that same evening, though they were tired.', 'They began, though they were tired, the long descent across the ice to their camp that same evening.'], why:'In a sentence of two clauses we usually put the shorter clause first, so that the sentence grows toward its end. The version that begins “Though they were tired” puts the short clause first. The version that ends “though they were tired” puts it last, so the sentence closes on its weakest part. The version that begins “They began, though” puts the short clause in the middle, where it interrupts the main clause.'},
  {id:'re-boethius', kind:'rhythm', src:['boeth','appown'], cite:'The context and two of the versions are this course’s own; one version is the original sentence of Boethius, The Consolation of Philosophy, Book I, prose 1 (trans. H. R. James).', context:'Boethius, in prison, has just written a poem lamenting his misfortunes.', prompt:'Which version sets the scene first and holds the main clause until the end, so that the sentence ends on the woman who appears?', versions:['While I was thus mutely pondering within myself, and recording my sorrowful complainings with my pen, it seemed to me that there appeared above my head a woman of a countenance exceeding venerable.', 'It seemed to me that there appeared above my head a woman of a countenance exceeding venerable, while I was thus mutely pondering within myself, and recording my sorrowful complainings with my pen.', 'A woman of a countenance exceeding venerable, it seemed to me, appeared above my head while I was thus mutely pondering within myself, and recording my sorrowful complainings with my pen.'], why:'A periodic sentence holds its main clause until the end, and here the end of the sentence also goes to the most important new thing, the woman who speaks in the rest of the book. The version that begins “While I was” is the sentence of Boethius in James’s translation, and it sets the scene before the main clause and ends on the woman. The version that begins “It seemed to me” states the main clause first and ends on his writing, which the reader already knows. The version that begins “A woman” names the woman first, so she appears before the scene is set. Those two versions are this course’s own rewriting.'},
  {id:'re-cicero', kind:'rhythm', src:['cic_cat','appown'], cite:'The context and two of the versions are this course’s own; one version is the original sentence of Cicero, Second Oration against Catiline 12 (trans. Blakiston).', context:'Cicero answers those who say that he drove Catiline into exile, and he recalls the meeting of the senate on the day before.', prompt:'Which version holds the main clause until the end, so that the sentence is periodic?', versions:['When I yesterday, men of Rome, having nearly been murdered in my own house, convened the senate in the temple of Jupiter Stator, I denounced the whole matter to the members of that assembly.', 'I denounced the whole matter to the members of that assembly yesterday, men of Rome, when, having nearly been murdered in my own house, I convened the senate in the temple of Jupiter Stator.', 'Having nearly been murdered in my own house, I denounced the whole matter yesterday, men of Rome, to the members of that assembly, when I convened the senate in the temple of Jupiter Stator.'], why:'A periodic sentence holds its main clause until the end, so that the sense is complete only when the sentence closes. The main clause is “I denounced the whole matter to the members of that assembly”. The version that begins “When I yesterday” is Cicero’s sentence in Blakiston’s translation, and it holds the main clause until the end. The version that begins “I denounced” is loose, because it states the main clause first. The version that begins “Having nearly been murdered” puts the main clause in the middle and then adds the clause about the senate. Those two versions are this course’s own rewriting.'}
];
function passages(){
  const app = window.PASSAGES || [];
  const hid = window.QUIZ_PASSAGES || [];
  if(!window.__ARS_QUIZ) return app;
  const prefer = window.__ARS_QUIZ_PREFER;
  if(prefer === 'hidden') return hid.length ? hid : app;
  if(prefer === 'app') return app;
  return hid.length ? app.concat(hid) : app;
}
function itemPool(name, arr){
  const extra = (window.QUIZ_ITEMS && window.QUIZ_ITEMS[name]) || [];
  if(!window.__ARS_QUIZ || !extra.length) return arr;
  const prefer = window.__ARS_QUIZ_PREFER;
  if(prefer === 'hidden') return extra;
  if(prefer === 'app') return arr;
  return arr.concat(extra);
}
function passageById(id){
  const all = (window.PASSAGES || []).concat(window.QUIZ_PASSAGES || []);
  return all.find(p => p.id === id);
}
// Ids of passages whose text repeats a later entry word for word (Thucydides 2.37 is filed twice,
// as thuc-per-2 and thuc-fun-2). The later entry is kept; the species pool drops the earlier one.
function dupTextIds(){
  const last = {}, dup = {};
  passages().forEach(p => { if(last[p.text]) dup[last[p.text]] = true; last[p.text] = p.id; });
  return dup;
}
function byTrack(tr){ return passages().filter(p => p.track === tr); }
function figNames(p){ return [...new Set((p.spans||[]).map(s => s.figure))]; }
function withFig(name){ return passages().filter(p => (p.spans||[]).some(s => s.figure === name)); }
function wrapFigs(text, spans, prefer){
  const all = (spans||[]).filter(s => s.start >= 0 && s.end <= text.length && s.start < s.end);
  const chosen = [];
  const preferOnes = prefer ? all.filter(s => s.figure === prefer) : [];
  if(preferOnes.length) chosen.push(preferOnes[0]);
  all.forEach(s => {
    if(chosen.indexOf(s) >= 0) return;
    if(chosen.some(u => !(s.end <= u.start || s.start >= u.end))) return;
    chosen.push(s);
  });
  chosen.sort((a,b) => b.start - a.start);
  let t = text;
  chosen.forEach(s => {
    const inner = t.slice(s.start, s.end);
    t = t.slice(0, s.start) + '<span class="figspan" data-fig="'+esc(s.figure)+'">'+inner+'</span>' + t.slice(s.end);
  });
  return t;
}
function esc(s){ return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function citeP(p){ return p.author+', <i>'+esc(p.work)+'</i> '+esc(p.locus); }
function excerpt(p, n){ n = n || 220; const t = p.text || ''; return t.length > n ? t.slice(0, n).replace(/\s+\S*$/, '') + '…' : t; }
function shownLen(p, n){ return excerpt(p, n).replace(/…$/, '').length; }
// The first span of the figure that falls wholly inside the excerpt of length n, if there is one.
function shownSpan(p, fig, n){
  const shown = excerpt(p, n).replace(/…$/, '').length;
  return (p.spans||[]).find(s => s.figure === fig && s.end <= shown);
}
// Passages that may serve as wrong answers for a figure: they neither mark the figure nor list it
// in unmarkedFigures (figures a reader could fairly find there, left unmarked), and their excerpt differs from the answer's.
function wrongPool(yes, fig, n){
  const shown = excerpt(yes, n);
  return passages().filter(p => p.id !== yes.id && figNames(p).indexOf(fig) < 0
    && (p.unmarkedFigures||[]).indexOf(fig) < 0 && excerpt(p, n) !== shown);
}
// k wrong answers whose excerpts all differ from one another (some passages share an opening).
function pickWrong(yes, fig, n, k){
  const out = [], seen = [];
  sample(wrongPool(yes, fig, n), Infinity).forEach(p => {
    const e = excerpt(p, n);
    if(out.length < k && seen.indexOf(e) < 0){ out.push(p); seen.push(e); }
  });
  return out;
}
// The length a student sees: the excerpt plus the citation, with tags removed.
function whichOptLen(p, n){
  const html = '<span style="font-size:16px">'+esc(excerpt(p, n))+'</span><br><span style="font-size:14px;color:var(--ink-soft);font-style:italic">'+citeP(p)+'</span>';
  return html.replace(/<[^>]+>/g,'').length;
}
// Wrong excerpts for a which-excerpt question. At least one option is as long as the right one, when the pool has one, so length does not name the answer.
function pickWrongLen(yes, fig, n, k){
  const yesLen = whichOptLen(yes, n);
  const pool = wrongPool(yes, fig, n);
  const longer = pool.filter(p => whichOptLen(p, n) >= yesLen);
  const out = [], seen = [excerpt(yes, n)];
  function take(arr){
    sample(arr, arr.length).forEach(p => {
      const e = excerpt(p, n);
      if(out.length < k && seen.indexOf(e) < 0){ out.push(p); seen.push(e); }
    });
  }
  if(longer.length) take(longer);
  if(out.length < k) take(pool);
  return out;
}
function pickPass(pred, prefix){
  let arr = pred ? passages().filter(pred) : passages();
  if(!arr.length && window.__ARS_QUIZ){
    const app = window.PASSAGES || [];
    arr = pred ? app.filter(pred) : app;
  }
  if(!arr.length) arr = window.PASSAGES || [];
  return pickSeen(arr, x => (prefix||'') + x.id);
}
function mcQ(opts){
  const order = opts.options.map((o,i) => i);
  for(let i = order.length - 1; i > 0; i--){ const j = Math.floor(Math.random()*(i+1)); [order[i],order[j]] = [order[j],order[i]]; }
  const options = order.map(i => opts.options[i]);
  const correct = order.indexOf(opts.correct);
  return {
    kind:'mc', prompt:opts.prompt, options, correct,
    passage:opts.passage, source:opts.source, orig:opts.orig, olang:opts.olang, src:opts.src,
    check(ans){
      const right = ans === correct;
      return {right, note: opts.note, also: opts.also || ''};
    }
  };
}


const EX = {};
EX.species = {
  id:'species', title:'The Three Species',
  instr:'We name the species, or kind of speech, by what the hearers are asked to judge: forensic (the past; the just and the unjust), deliberative (the future; the expedient and the harmful), or epideictic (the present; the noble and the shameful). A passage from a mixed speech takes the chief species of the speech, that is, what its hearers are asked to decide. Ten questions make a set; a passage is not repeated in the set.',
  src:['arist_rhet'],
  gen(diff){
    const dup = dupTextIds();
    const p = pickPass(x => isOration(x) && !dup[x.id] && !cardTaught('species:'+x.id), 'sp:');
    const sp = speciesOf(p);
    const labels = {
      forensic:'Forensic: the jury, the past, the just and the unjust',
      deliberative:'Deliberative: the assembly, the future, the expedient',
      epideictic:'Epideictic: the spectator, praise and blame, the noble'
    };
    const opts = ['forensic','deliberative','epideictic'];
    const cue = diff <= 2 ? '<div class="q-cue">'+esc(p.cue||'')+'</div>' : '';
    return mcQ({
      prompt:'What is the species of this speech?',
      options: opts.map(k => labels[k]),
      correct: opts.indexOf(sp),
      passage: cue + esc(excerpt(p, diff >= 4 ? 280 : 420)),
      source: citeP(p), orig: p.orig, olang: p.olang, src: srcOf(p),
      note: sp.charAt(0).toUpperCase()+sp.slice(1)+'. In I.3 Aristotle makes the species follow what the hearer is asked to judge.',
      also: labels[sp]
    });
  }
};
